-- India goals and standards for the four synthetic spaces, built for partner educators at CHRIST (Deemed to be University)
-- (campuses in Karnataka, Uttar Pradesh and Maharashtra). All of it is AI-drafted and unreviewed by an Indian curriculum expert.
--
-- 1. A new Uttar Pradesh Curriculum Repository (the first for that state), nested under the India repository, and an honest label for the
--    four India repositories that carry this content: public documents summarised by an AI. No expert has reviewed them yet.
-- 2. 67 new records (10 karnataka, 9 maharashtra, 40 india, 8 uttar-pradesh): frameworks and syllabus topics
--    that set school goals and standards, each with the document it was read from and the passage. Summaries are in our own words.
-- 3. Each synthetic space is declared as grounded in the four India repositories, so its members can read them.
-- 4. 108 proposed links from parts of the spaces to those records (50 bio-core, 14 interdisciplinary, 23 social-core, 21 computational-core). Their relation type
--    starts with proposed_, which the views show as "AI-drafted, unconfirmed". A person confirms, edits or removes each one.
-- 5. An "India (English)" view for each space, offered to the editor, contributor, reviewer and viewer roles.
--
-- To undo: DELETE FROM curriculum_repository_records WHERE source_repo = 'openlpm-starter-draft' AND source_record_id LIKE 'IN-%'; (their links go with them),
-- DELETE FROM project_repository_links WHERE jurisdiction IN ('IN','IN-KA','IN-MH','IN-UP') AND project_id IN (SELECT id FROM projects WHERE slug LIKE '%-lpm-synth'),
-- DELETE FROM project_dashboard_views WHERE template_id LIKE '%-india-en', and DELETE FROM projects WHERE slug = 'uttar-pradesh-curriculum-repository'.

SET search_path = public, extensions;

-- ============================================================================
-- 1. Uttar Pradesh repository, and labels for the India repositories
-- ============================================================================

DO $MIGRATION$
DECLARE
  v_india UUID;
  v_owner_id UUID;
  v_owner_invited_by UUID;
  v_up UUID;
  v_project UUID;
  v_view UUID;
  v_role TEXT;
BEGIN
  SELECT id INTO v_india FROM projects WHERE slug = 'india-curriculum-repository';
  SELECT user_id, invited_by INTO v_owner_id, v_owner_invited_by FROM project_members WHERE project_id = v_india AND role = 'owner' LIMIT 1;

  INSERT INTO projects (slug, name, description, project_kind, parent_project_id, is_private, epistemic_status, epistemic_status_note, focus_type, region_tags, created_by)
  SELECT
    'uttar-pradesh-curriculum-repository',
    'Uttar Pradesh Curriculum Repository',
    'School curriculum goals and standards for Uttar Pradesh: who sets the syllabus, how the state uses the national (NCERT) books and framework, and what its science, social science and computing syllabi ask. First layer, written 2026-10-30 from public documents for partner educators at CHRIST (Deemed to be University), Delhi NCR campus (Ghaziabad).',
    'curriculum-repository',
    v_india,
    TRUE,
    'in-development',
    'AI-drafted from public documents and summarised in our own words. No Indian curriculum expert has reviewed it. Each record says which document was read and which passage; treat anything marked secondary-source-only as unconfirmed.',
    'regional',
    ARRAY['IN-UP'],
    v_owner_id
  WHERE NOT EXISTS (SELECT 1 FROM projects WHERE slug = 'uttar-pradesh-curriculum-repository');

  SELECT id INTO v_up FROM projects WHERE slug = 'uttar-pradesh-curriculum-repository';
  IF v_owner_id IS NOT NULL THEN
    INSERT INTO project_members (project_id, user_id, role, invited_by)
    VALUES (v_up, v_owner_id, 'owner', v_owner_invited_by)
    ON CONFLICT (project_id, user_id) DO NOTHING;
  END IF;

  -- The India repositories hold public documents summarised by an AI. Their earlier label (human-curated, already in classroom use)
  -- overstates that. Kerala keeps its label because it is outside this view.
  UPDATE projects SET epistemic_status = 'in-development',
    epistemic_status_note = 'AI-drafted from public documents and summarised in our own words. No Indian curriculum expert has reviewed it. Each record says which document was read and which passage; treat anything marked secondary-source-only as unconfirmed.'
  WHERE slug IN ('india-curriculum-repository', 'karnataka-curriculum-repository', 'maharashtra-curriculum-repository');
END
$MIGRATION$;

-- ============================================================================
-- 2. Records
-- ============================================================================

INSERT INTO curriculum_repository_records (id, project_id, record_type, jurisdiction, source_repo, source_record_id, title, content, access_tier, event_date)
SELECT v.id::uuid, p.id, v.record_type, v.jurisdiction, v.source_repo, v.source_record_id, v.title, v.content::jsonb, 'summary-only', NULLIF(v.event_date, '')::date
FROM (VALUES
  ('42500419-082f-5b57-aaf7-06265a9e99c2', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-MANDATE-sep-commission-final-report-2025', 'Karnataka State Education Policy Commission: final report with school education recommendations (submitted 8 August 2025)', '{"id":"IN-KA-MANDATE-sep-commission-final-report-2025","label":"Karnataka State Education Policy Commission: final report with school education recommendations (submitted 8 August 2025)","sourceUrl":"https://educationforallinindia.com/wp-content/uploads/2025/08/Karnataka-State-Education-Commission-Press-Note-on-SEP-Report-2025.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: State Education Policy Commission, Press Note on report submitted (6 pages), opening paragraphs and the ''School Education'' recommendations on pages 1 to 2 (items 1, 4, 5, 10, 11 and 25 used). Date of submission from Deccan Herald, 10 August 2025.. Read the commission''s own 6-page press note on educationforallinindia.com, a third-party site. No copy on a Karnataka government site could be opened, and the 2,197-page report was not read. Every point used also appears in Deccan Herald and The Hans India of 10 August 2025. Deccan Herald quotes a note from the Higher Education Minister''s office and says the chair submitted the report on Friday 8 August 2025. The press note has an apparent typo: it says the commission started on 1 November 2025 and also that it was appointed by order on 11 October 2023. What happened next, from news reports: on 26 November 2025 Deccan Herald reported a Higher Education Department order forming an official-level review committee with a two-week deadline; the Cabinet discussed the recommendations on 7 May 2026; on 16 May 2026 a six-member Cabinet sub-committee under Home Minister G Parameshwara was set up to review the report (PTI via Telangana Today; Devdiscourse). No decision adopting the report was found. Background: PTI reported on 21 August 2023 that Karnataka would scrap NEP 2020 and form a committee for a state policy, with the old system continuing meanwhile. The member counts differ between the press note (17 members, 6 advisers) and a 2023 news report; this was not re-checked. The press note never mentions NCF-SE 2023. This record is AI-drafted and no subject expert has reviewed it. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"State Education Policy Commission, Press Note on report submitted (6 pages), opening paragraphs and the ''School Education'' recommendations on pages 1 to 2 (items 1, 4, 5, 10, 11 and 25 used). Date of submission from Deccan Herald, 10 August 2025.","description":"The commission recommends a 2+8+4 school structure (two years pre-primary, eight elementary, four secondary), teaching in Kannada or the mother tongue up to Class 5, and two languages: Kannada or mother tongue plus English. It calls for a state-made Comprehensive Curriculum for School Education to end reliance on NCERT textbooks, and for Constitutional Value Education as a compulsory subject. These are recommendations to the government.","verificationStatus":"secondary-source-only","issuingBody":"Karnataka State Education Policy Commission (chair Prof. Sukhdeo Thorat), appointed by the Government of Karnataka","mandateType":"policy-statement","adoptionDate":"2025-08-08","dateGranularity":"day","statementText":"The commission recommends a 2+8+4 school structure (two years pre-primary, eight elementary, four secondary), teaching in Kannada or the mother tongue up to Class 5, and two languages: Kannada or mother tongue plus English. It calls for a state-made Comprehensive Curriculum for School Education to end reliance on NCERT textbooks, and for Constitutional Value Education as a compulsory subject. These are recommendations to the government.","subject":"general","topicTags":["state-education-policy","nep-2020","school-structure","two-language-policy","ncert-textbooks","constitutional-values"]}', '2025-08-08'),
  ('33e91b6d-48be-5a1c-861e-dbef6a8092af', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-MANDATE-textbook-revision-2014-17-ncf2005-kcf2007', 'Karnataka Department of Education and Textbook Society: Classes 1 to 10 textbook revision (orders of 2014 and 2015, books from 2017-18)', '{"id":"IN-KA-MANDATE-textbook-revision-2014-17-ncf2005-kcf2007","label":"Karnataka Department of Education and Textbook Society: Classes 1 to 10 textbook revision (orders of 2014 and 2015, books from 2017-18)","sourceUrl":"https://cdn1.byjus.com/wp-content/uploads/2019/07/kseeb-Class-8-Science-Part-1.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: KTBS, Science, Eighth Standard, Part 1 (Revised): Preface (page ii) and ''About the Revision of Textbooks'' (pages vi to vii). KTBS, Social Science, Tenth Standard, Part 1 (Revised - 2022): Chairpersons'' Note (names KCF 2007 and NCF 2005) and Foreword ''On review of text books'' (revised books reached students in 2017-18).. Read the front-matter passages in Byjus-hosted PDFs of two KTBS books (Class 8 Science Part 1, Revised; Class 10 Social Science Part 1, Revised 2022). No copy on a Karnataka government site could be opened. The KTBS home page (Wayback capture, 2023) lists the 2017-18 revision as one of its two textbook sets. The Class 10 Social Science Chairpersons'' Note names KCF 2007 and NCF 2005. Its Foreword says the revised books reached students only in 2017-18 and that a government committee re-reviewed them from 2021, which led to the revised 2022 social science books. Later changes to Kannada and social science books in 2022 and 2023 are not covered here. The AI reader did not see a 2025-26 edition. This record is AI-drafted and no subject expert has reviewed it. A second AI reader could not confirm all of it: Every claim in statementText matches the passages: orders of 24 November 2014 and 19 September 2015, 27 committees, 2017-18 target year, the Chief Minister''s wish list, three expert committees comparing state books with NCERT, and the NCF 2005 and KCF 2007 base.; Provenance only: the passages were read in Byjus-hosted copies of KTBS books. No copy on a Karnataka government site could be opened. An official Wayback capture of the KTBS home page (2023) lists two textbook sets, ''2015-16 Textbooks (Rachane)'' and ''2017-18 Textbooks (Parishkarane)'', which fits the revision story but is not the passage itself.; The 2022 Class 10 Social Science Part 1 Foreword (On review of text books) says the revised books reached students only in the 2017-18 school year. This supports the 2017 date. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"KTBS, Science, Eighth Standard, Part 1 (Revised): Preface (page ii) and ''About the Revision of Textbooks'' (pages vi to vii). KTBS, Social Science, Tenth Standard, Part 1 (Revised - 2022): Chairpersons'' Note (names KCF 2007 and NCF 2005) and Foreword ''On review of text books'' (revised books reached students in 2017-18).","description":"Karnataka revised its Classes 1 to 10 textbooks through 27 committees under orders of 24 November 2014 and 19 September 2015, with the new books due in 2017-18. The Chief Minister asked for books that build equality, moral values, scientific temper, critical thinking, secularism and national commitment. Three expert committees compared state science, mathematics and social science books with NCERT so they would not fall below the central standard. The books name NCF 2005 and the state''s 2007 curriculum framework as their base.","verificationStatus":"secondary-source-only","issuingBody":"Government of Karnataka, Department of Education, with the Karnataka Textbook Society (R)","mandateType":"policy-statement","adoptionDate":"2017","dateGranularity":"year","statementText":"Karnataka revised its Classes 1 to 10 textbooks through 27 committees under orders of 24 November 2014 and 19 September 2015, with the new books due in 2017-18. The Chief Minister asked for books that build equality, moral values, scientific temper, critical thinking, secularism and national commitment. Three expert committees compared state science, mathematics and social science books with NCERT so they would not fall below the central standard. The books name NCF 2005 and the state''s 2007 curriculum framework as their base.","subject":"general","gradeFrom":1,"gradeTo":10,"topicTags":["textbook-revision","ncf-2005","kcf-2007","scientific-temper","ncert-comparison"]}', ''),
  ('871fb635-bf8b-5631-885d-c28f6d58de6b', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-UNIT-class10-science-heredity-and-evolution', 'Karnataka Textbook Society, Class 10 Science Part 2, chapter ''Heredity and Evolution'' (NCERT chapter 9, pages 52 to 69)', '{"id":"IN-KA-UNIT-class10-science-heredity-and-evolution","label":"Karnataka Textbook Society, Class 10 Science Part 2, chapter ''Heredity and Evolution'' (NCERT chapter 9, pages 52 to 69)","sourceUrl":"https://cdn1.byjus.com/wp-content/uploads/2022/09/KSEEB-Class-10-Science-Part-2-Textbook.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: KTBS, Science, Tenth Standard, Part 2: contents page (printed ii) and chapter 9 ''Heredity and Evolution'', pages 52 to 69 (sections 9.1 to 9.6.1, summary, exercises). The same chapter and page range are in two PDF files of the book, one created in March 2018 and one in September 2022.. Read the whole chapter in two Byjus-hosted PDFs of the KTBS book (files created March 2018 and September 2022; the book prints no year). No copy on a Karnataka government site could be opened. The cover carries NCERT''s name and emblem, and the contents page lists NCERT chapter numbers. The text is NCERT''s chapter ''Heredity and Evolution'': its opening paragraph and the headings of section 9.2 are identical to those of NCERT''s current chapter 8 ''Heredity'' (reprint 2026-27, ncert.nic.in), where they are numbered 8.x. NCERT''s current chapter has no beetle story, speciation, fossils or human evolution, so these Karnataka books differ from NCERT''s book today. LICENCE: (1) KOER''s English Heredity page (last edited 17 May 2017) holds no chapter text. It links to a KTBS-hosted PDF of chapter 21 ''Heredity'' from an older Karnataka book, and to a unit plan (ODT, uploaded 20 June 2016) that covers Mendel, DNA structure and replication, genetic engineering and biotechnology and has no evolution. (2) KOER''s CC BY-SA 4.0 notice is the standard footer of its wiki, ''unless otherwise noted''. It covers KOER''s own wiki pages and uploads, and says nothing about the KTBS chapter. (3) The KTBS site''s copyright policy (Wayback capture of 4 December 2024) lets site material be reproduced free of charge with acknowledgement and without misleading use, and excludes material owned by third parties. It is not a Creative Commons licence. (4) Every page of the 2022 file carries a ''KTBS Not to be republished'' watermark (the March 2018 Class 10 file has none, but the Class 6 and Class 8 science files carry it), and NCERT''s book is marked ''all rights reserved''. So the open licence applies to KOER''s pages about the chapter. The textbook text itself has no open licence that the AI reader could find. The older Karnataka-written chapter 21 could not be read (Wayback kept only the first 1 MiB), so its own terms are unknown. The AI reader did not see a 2025-26 or 2026-27 Karnataka edition. Please confirm whether evolution is still taught in Class 10 in Karnataka. This record is AI-drafted and no subject expert has reviewed it. A second AI reader could not confirm all of it: Chapter number, title and pages are right. The contents page (printed page ii) gives NCERT chapter 9 ''Heredity and Evolution'' at pages 52 to 69, and the chapter opens with the heading 9 Heredity and Evolution. Sections 9.1 to 9.6.1, the summary and 12 exercises are on those pages in both files.; statementText matches the chapter text: Mendel''s pea crosses, dominant and recessive traits, sex determination, the beetle story with natural selection and genetic drift, speciation by isolation, fossils, evolution as a tree, no ''progress'', and all humans as one species with an African origin. The chapter does not use the words allele or mutation.; Print years: the book prints no year in Part 2. The ''2018'' and ''2022'' in the title are the creation dates of the two PDF files (13 March 2018 and 13 September 2022). They are not print years. The Part 1 acknowledgements mention a review of the book in 2017-18, and its Kannada preface says the NCERT-based Class 10 book is being introduced ''this year'' without naming it. The date 2018 is therefore approximate.; Provenance only: the book was read in two Byjus-hosted PDFs that carry KTBS''s cover (the 2022 file also has a KTBS watermark on every page). No copy on a Karnataka government site could be opened. Wayback holds KTBS file captures but only the first 1 MiB of each (the chapter 21 file is listed as 6.7 MB).; Licence: the existing project finding that this chapter is CC BY-SA 4.0 via KOER is not supported for this chapter. See notes. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"KTBS, Science, Tenth Standard, Part 2: contents page (printed ii) and chapter 9 ''Heredity and Evolution'', pages 52 to 69 (sections 9.1 to 9.6.1, summary, exercises). The same chapter and page range are in two PDF files of the book, one created in March 2018 and one in September 2022.","description":"Class 10 students study how variation arises in reproduction and how traits pass from parents, using Mendel''s pea experiments, dominant and recessive traits and sex determination. The chapter then teaches evolution: a beetle example of natural selection and genetic drift, speciation by isolation, fossils, evolutionary trees, and the point that evolution does not mean progress. It states that all humans are one species with an African origin.","verificationStatus":"secondary-source-only","issuingBody":"Karnataka Textbook Society (R), Government of Karnataka","mandateType":"curriculum-unit","adoptionDate":"2018","dateGranularity":"year","statementText":"Class 10 students study how variation arises in reproduction and how traits pass from parents, using Mendel''s pea experiments, dominant and recessive traits and sex determination. The chapter then teaches evolution: a beetle example of natural selection and genetic drift, speciation by isolation, fossils, evolutionary trees, and the point that evolution does not mean progress. It states that all humans are one species with an African origin.","subject":"science","gradeFrom":10,"gradeTo":10,"topicTags":["heredity","variation","mendel","natural-selection","genetic-drift","speciation","fossils","human-evolution"]}', ''),
  ('f945df88-74c6-54a0-bdd2-0bcaf06657d6', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-UNIT-class8-science-evolution-of-life', 'Karnataka Textbook Society, Class 8 Science Part 2 (Revised), chapter 22 ''Evolution of life'' (pages 127 to 137)', '{"id":"IN-KA-UNIT-class8-science-evolution-of-life","label":"Karnataka Textbook Society, Class 8 Science Part 2 (Revised), chapter 22 ''Evolution of life'' (pages 127 to 137)","sourceUrl":"https://cdn1.byjus.com/wp-content/uploads/2019/07/kseeb-Class-8-Science-Part-2.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: KTBS, Science, Eighth Standard, Part 2 [Revised]: index page (printed ii) and chapter 22 ''Evolution of life'', pages 127 to 137 (text, activities 22.1 to 22.3, exercises).. Read the whole chapter in a Byjus-hosted PDF of the KTBS book (file created May 2018; it carries a ''Not to be republished'' watermark, so only paraphrase is used). No copy on a Karnataka government site could be opened. The book prints no year. The year 2017 comes from its revision note (revised books due from 2017-18); the file date is a PDF date. The Class 8 science books name Karnataka authors, so this chapter is state-written. The KOER wiki page ''Evolution of Life'' lists a Karnataka Class 8 ''chapter 23 Evolution of life'' linked to an older KTBS file, with objectives on fossils, comparative anatomy, vestigial organs and the geological time scale. That describes an earlier edition. The chapter the AI reader read has none of those topics. It says Mendel''s heredity will be studied in higher classes and does not discuss genes or alleles. It uses the phrase ''survival of the fittest'' without defining fitness as reproductive success. The AI reader did not see a 2025-26 edition. This record is AI-drafted and no subject expert has reviewed it. A second AI reader could not confirm all of it: Chapter number, title and pages are right. The Part 2 index (printed page ii) lists chapter 22 ''Evolution of life'' at pages 127 to 137 with 5 teaching periods. Activities 22.1 to 22.3 and the exercises are on those pages.; statementText matches the chapter: chemical evolution (Oparin and Haldane) and the first cells, organic evolution as descent through modification, Lamarckism with Weismann''s tail-cutting experiment on rats, Darwin''s variation, overproduction, struggle for existence and natural selection, de Vries''s mutation idea, and neo-Darwinism with Mendel''s heredity deferred to higher classes.; Date: ''2018 print'' came from the PDF creation date (7 May 2018). The book prints no year. Its own revision note says the revised books could be in force from 2017-18. adoptionDate is changed to 2017 on that basis.; Provenance only: read in a Byjus-hosted PDF with a KTBS cover and watermark. No copy on a Karnataka government site could be opened. The official KTBS file (8th-english-science-2.pdf, 16.5 MB) is held by Wayback only as its first 1 MiB. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"KTBS, Science, Eighth Standard, Part 2 [Revised]: index page (printed ii) and chapter 22 ''Evolution of life'', pages 127 to 137 (text, activities 22.1 to 22.3, exercises).","description":"Class 8 students meet a full chapter on evolution. It covers chemical evolution and the first cells, organic evolution as descent with change, Lamarck''s use-and-disuse idea and Weismann''s tail-cutting experiment against it, Darwin''s account of variation, overproduction, competition and natural selection, de Vries''s mutation idea, and neo-Darwinism as a combination with Mendel''s heredity.","verificationStatus":"secondary-source-only","issuingBody":"Karnataka Textbook Society (R), Government of Karnataka","mandateType":"curriculum-unit","adoptionDate":"2017","dateGranularity":"year","statementText":"Class 8 students meet a full chapter on evolution. It covers chemical evolution and the first cells, organic evolution as descent with change, Lamarck''s use-and-disuse idea and Weismann''s tail-cutting experiment against it, Darwin''s account of variation, overproduction, competition and natural selection, de Vries''s mutation idea, and neo-Darwinism as a combination with Mendel''s heredity.","subject":"science","gradeFrom":8,"gradeTo":8,"topicTags":["evolution","natural-selection","lamarck","darwin","mutation","origin-of-life"]}', ''),
  ('cb0cf9da-6439-5ab2-94a5-aa5ab6929454', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-UNIT-class6-science-habitats-and-adaptation', 'Karnataka Textbook Society, Class 6 Science (English medium), chapter 9 ''The Living Organisms: Characteristics and Habitats'' (2018-19)', '{"id":"IN-KA-UNIT-class6-science-habitats-and-adaptation","label":"Karnataka Textbook Society, Class 6 Science (English medium), chapter 9 ''The Living Organisms: Characteristics and Habitats'' (2018-19)","sourceUrl":"https://cdn1.byjus.com/wp-content/uploads/2019/08/Karnataka-Board-Class-6-science-english-medium.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: KTBS, Science, Sixth Standard, English medium: Kannada preface (page ix, dates the book to 2018-19), contents, and chapter 9, pages 79 to 94 (sections 9.1 to 9.3; adaptation and acclimatisation in 9.2).. Read the adaptation and acclimatisation passages and the section headings in a Byjus-hosted PDF of the KTBS book (file created April 2018). No copy on a Karnataka government site could be opened. The foreword is NCERT''s, dated December 2005, so this is NCERT''s Class VI text printed by Karnataka. The Kannada preface says the book is brought in for 2018-19. The chapter text does not mention inheritance or offspring and does not describe variation among individuals; the word ''variations'' appears only for differences between kinds of habitat. It describes adaptation as organisms getting adjusted to their surroundings over thousands of years, and says organisms that cannot adapt die while the adapted survive. The AI reader did not open the Classes 1 to 5 environmental studies books, so the stage contrast with the model may disappear if adaptation is taught earlier. The AI reader did not see a 2025-26 edition. This record is AI-drafted and no subject expert has reviewed it. A second AI reader could not confirm all of it: Chapter number, title and pages are right: chapter 9 ''The Living Organisms: Characteristics and Habitats'' starts on page 79 and chapter 10 starts on page 95. The camel and fish examples, adaptation, acclimatisation (small short-term changes) and the sentence about organisms that cannot adapt are in sections 9.1 and 9.2. The text says adaptation takes thousands of years.; The date is supported. The book''s Kannada preface (page ix) says the NCERT-based Class 6 science book is being brought in across 7 media in 2018-19. The title''s ''2018 print'' is replaced with ''2018-19 edition''.; Note wording: the notes said the chapter ''never mentions inheritance, variation or offspring''. The word ''variations'' does appear, but it describes differences between kinds of habitat. The chapter does not describe variation among individuals or inheritance.; Provenance only: read in a Byjus-hosted PDF with a KTBS cover and watermark. No copy on a Karnataka government site could be opened. The official KTBS file (6th-english-science.pdf, 65 MB) is held by Wayback only as its first 1 MiB. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"KTBS, Science, Sixth Standard, English medium: Kannada preface (page ix, dates the book to 2018-19), contents, and chapter 9, pages 79 to 94 (sections 9.1 to 9.3; adaptation and acclimatisation in 9.2).","description":"Class 6 students learn that different places hold different living things, and that features such as a camel''s long legs or a fish''s streamlined body, scales and gills help an organism live in its habitat. The chapter calls such features adaptation, separates it from short-term acclimatisation, and says adaptation takes a long time. It also introduces land and water habitats and the living and non-living parts of a habitat.","verificationStatus":"secondary-source-only","issuingBody":"Karnataka Textbook Society (R), Government of Karnataka","mandateType":"curriculum-unit","adoptionDate":"2018","dateGranularity":"year","statementText":"Class 6 students learn that different places hold different living things, and that features such as a camel''s long legs or a fish''s streamlined body, scales and gills help an organism live in its habitat. The chapter calls such features adaptation, separates it from short-term acclimatisation, and says adaptation takes a long time. It also introduces land and water habitats and the living and non-living parts of a habitat.","subject":"science","gradeFrom":6,"gradeTo":6,"topicTags":["adaptation","habitat","acclimatisation","diversity-of-life"]}', ''),
  ('f8ff6526-1d17-5dff-a21a-e9fbc4d0cffe', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-UNIT-class8-social-science-sociology-social-institutions', 'Karnataka Textbook Society, Class 8 Social Science (Revised Textbook), Sociology chapter 3 ''Social Institutions'' (pages 149 to 153)', '{"id":"IN-KA-UNIT-class8-social-science-sociology-social-institutions","label":"Karnataka Textbook Society, Class 8 Social Science (Revised Textbook), Sociology chapter 3 ''Social Institutions'' (pages 149 to 153)","sourceUrl":"https://cdn1.byjus.com/wp-content/uploads/2020/01/KSEEB-Class-8-Social-Science-Textbook.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: KTBS, Social Science, Eighth Standard (Revised Textbook): contents page and Sociology chapter 3 ''Social Institutions'', pages 149 to 153, read in full.. Read the whole chapter in a Byjus-hosted PDF of the KTBS book (file created July 2019; no copy on a Karnataka government site could be opened). The book prints no year. The year 2017 comes from its revision note (revised books due from 2017-18); the file date is a PDF date. The KTBS home page (Wayback capture, 2023) says revised social science books for Classes 6 to 10 were adopted for 2022-23, so please compare this chapter with the 2022-23 print. The Preface says sociology, business studies and commerce chapters begin in Class 8 under NCF 2005. The AI reader read only the contents pages for the other sociology chapters: Class 8 Introduction to Sociology, Culture and Types of Society; Class 9 Family, Socialization, Social Change and Community; Class 10 Collective Behaviour and Protests, and Social Challenges. The AI reader did not find chapters on shared resources or commons. The AI reader did not see a 2025-26 edition. This record is AI-drafted and no subject expert has reviewed it. A second AI reader could not confirm all of it: Chapter, title and pages are right: Sociology chapter 3 ''Social Institutions'', pages 149 to 153 (contents page lists it at 149). statementText matches the chapter: institutions as lasting structures meeting human needs, examples including family, marriage, courts and schools, written and unwritten rules, interdependence, transfer of culture across generations, roles by age, correction of rule-breakers, and family, marriage and religion.; Date: 2019 is the PDF creation date (4 July 2019). The book prints no year. Its revision note says the revised books could be in force from 2017-18, and the Class 10 Social Science Foreword says the revised books reached students in 2017-18. adoptionDate is changed to 2017.; The KTBS home page (Wayback capture, 2023) says revised Class 6 to 10 social science books were adopted for 2022-23. The file the AI reader read may be the earlier edition. Byjus lists the same file for 2022-23, and the AI reader could not confirm that the 2022-23 print has identical Sociology text.; Provenance only: read in a Byjus-hosted PDF with a KTBS cover. No copy on a Karnataka government site could be opened. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"KTBS, Social Science, Eighth Standard (Revised Textbook): contents page and Sociology chapter 3 ''Social Institutions'', pages 149 to 153, read in full.","description":"Class 8 students learn that social institutions such as the family, marriage, the court and the school are lasting structures of roles and rules that meet human needs. The chapter says institutions have both written rules (courts, schools, governments) and unwritten ones (customs, traditions), depend on each other, carry culture across generations, give members roles by age, and correct breaches of their rules. It works through family, marriage and religion.","verificationStatus":"secondary-source-only","issuingBody":"Karnataka Textbook Society (R), Government of Karnataka","mandateType":"curriculum-unit","adoptionDate":"2017","dateGranularity":"year","statementText":"Class 8 students learn that social institutions such as the family, marriage, the court and the school are lasting structures of roles and rules that meet human needs. The chapter says institutions have both written rules (courts, schools, governments) and unwritten ones (customs, traditions), depend on each other, carry culture across generations, give members roles by age, and correct breaches of their rules. It works through family, marriage and religion.","subject":"social-science","gradeFrom":8,"gradeTo":8,"topicTags":["social-institutions","norms","rules","roles","culture","sociology"]}', ''),
  ('5b6f8644-5ee0-5531-af5c-f6bdf355afeb', 'karnataka-curriculum-repository', 'policy-timeline-event', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-EVENT-preamble-reading-cabinet-decision-2023-06', 'Karnataka cabinet decision that schools and colleges read the Preamble of the Constitution daily (15 June 2023)', '{"id":"IN-KA-EVENT-preamble-reading-cabinet-decision-2023-06","label":"Karnataka cabinet decision that schools and colleges read the Preamble of the Constitution daily (15 June 2023)","sourceUrl":"https://news.careers360.com/karnataka-govt-makes-reading-of-constitutions-preamble-mandatory-in-schools-colleges","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: PTI report on the Karnataka cabinet decision, 15 June 2023, as carried by Careers360; also LiveLaw and Bar and Bench, 16 June 2023. Follow-ups read: Deccan Herald, 28 August 2023; ANI via Asianet Newsable, 15 September 2023; Bar and Bench, 6 October 2026.. Read news reports of the decision: PTI via Careers360 (15 June 2023), LiveLaw and Bar and Bench (16 June 2023). PTI says schools and colleges, and the other two add universities. The AI reader did not find the cabinet minute or any Department of School Education circular, so the issuing department, order number and start date are unknown to the AI reader. On 28 August 2023 Deccan Herald quoted Education Minister Madhu Bangarappa saying an order would follow within days and that daily reading in all schools would start on 5 September. On 15 September 2023 ANI (via Asianet Newsable) reported that reading was compulsory in schools and colleges from that day. No order number appeared in any of them. Earlier, on 19 November 2019, Deccan Chronicle reported a circular from the Commissioner of Public Instruction making Preamble reading compulsory at morning assembly from 26 November 2019; the circular itself was not found. On 6 October 2026 the Supreme Court dismissed a petition for a national rule on daily Preamble recitation and noted that the Preamble is already taught from Class 6 (Bar and Bench). This record is AI-drafted and no subject expert has reviewed it. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"PTI report on the Karnataka cabinet decision, 15 June 2023, as carried by Careers360; also LiveLaw and Bar and Bench, 16 June 2023. Follow-ups read: Deccan Herald, 28 August 2023; ANI via Asianet Newsable, 15 September 2023; Bar and Bench, 6 October 2026.","description":"On 15 June 2023 the Karnataka cabinet decided that every school, college and university in the state, whether government, aided or private, must read the Preamble of the Constitution of India daily, and that government offices must display it. The minister linked the step to the freedom struggle and the purpose of the Constitution. The reports give no order number.","verificationStatus":"secondary-source-only","slug":"preamble-reading-cabinet-decision-2023-06","dateStart":"2023-06-15","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["preamble","constitutional-values","school-routine","civics"]}', '2023-06-15'),
  ('57ac2530-a73d-5e85-8ca4-db5ea46207cf', 'karnataka-curriculum-repository', 'policy-timeline-event', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-EVENT-ai-education-announced-2026-08', 'Karnataka Chief Minister announces AI Akshara Abhiyana and Coding Gurukula, with AI education from Class 6 (15 August 2026)', '{"id":"IN-KA-EVENT-ai-education-announced-2026-08","label":"Karnataka Chief Minister announces AI Akshara Abhiyana and Coding Gurukula, with AI education from Class 6 (15 August 2026)","sourceUrl":"https://www.deccanchronicle.com/southern-states/karnataka/dk-shivakumar-announces-ai-education-in-schools-on-independence-day-1979361","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: PTI report on the Independence Day speech, Deccan Chronicle, 15 August 2026, and The Pioneer, 16 August 2026; follow-up PTI report, Deccan Chronicle, 5 October 2026 (karnataka-plans-to-introduce-ai-training-in-govt-schools-from-class-6-1993312), also Careers360 and Elets eGov, 6 October 2026.. Read the speech report in Deccan Chronicle (15 August 2026) and The Pioneer (16 August 2026), and the follow-up in Deccan Chronicle (PTI, 5 October 2026), Careers360 (PTI) and Elets eGov (own byline, citing a Chief Minister''s Office statement). The August reports say nothing about partners, numbers, budget, timeline or curriculum. The October reports describe a directive to explore the idea, name Google as having shown interest, and say Class 9 training has started; none cites a government order. Deccan Chronicle of 24 July 2026 already reported the Chief Minister linking the state AI University to AI education from Class 6, so the 15 August speech restates an earlier plan with new programme names. Other outlets (The Week, 8 October 2026; Let''s Data Science) describe the Class 6 plan as still open and mention certificate courses from January 2027 and a proposed state AI university; The AI reader did not re-open The Week. The AI reader left out a devlibrary.in item describing a plan from Grade 1 with IIT input, because it names no primary source. The AI reader wrote no model links because no content has been published to compare. Please look for the department''s order or syllabus when it appears. This record is AI-drafted and no subject expert has reviewed it. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"PTI report on the Independence Day speech, Deccan Chronicle, 15 August 2026, and The Pioneer, 16 August 2026; follow-up PTI report, Deccan Chronicle, 5 October 2026 (karnataka-plans-to-introduce-ai-training-in-govt-schools-from-class-6-1993312), also Careers360 and Elets eGov, 6 October 2026.","description":"In his Independence Day speech on 15 August 2026 the Chief Minister announced two programmes, AI Akshara Abhiyana and Coding Gurukula, saying AI education would reach schools from Class 6. On 5 October 2026 he asked officials to study extending AI training, already started for Class 9 in government schools, down to Class 6, with the IT department and private partners. No curriculum, hours or order was published.","verificationStatus":"secondary-source-only","slug":"ai-education-announced-2026-08","dateStart":"2026-08-15","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["artificial-intelligence","coding","school-announcement","class-6"]}', '2026-08-15'),
  ('794fb702-4089-5b1e-a156-c90f964867a1', 'karnataka-curriculum-repository', 'policy-timeline-event', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-EVENT-ict-at-schools-third-party-evaluation-2015', 'NCERT Central Institute of Educational Technology: third-party evaluation of the ICT@Schools scheme in Karnataka high schools (2015)', '{"id":"IN-KA-EVENT-ict-at-schools-third-party-evaluation-2015","label":"NCERT Central Institute of Educational Technology: third-party evaluation of the ICT@Schools scheme in Karnataka high schools (2015)","sourceUrl":"https://ciet.ncert.gov.in/storage/app/public/files/14/reports/ICTReportofKarnataka.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CIET, NCERT, Third Party Evaluation of ICT@Schools Scheme in Karnataka (2015): Introduction (page 1), sample (page 3), hardware (page 4), software, internet and use of ICT (pages 7 to 8), problems (pages 16 to 17), results (page 18), recommendations (pages 19 to 20).. Read the report text on NCERT''s own site (ciet.ncert.gov.in). It is an evaluation, so it describes provision as of the study (sample of 184 of 1,571 Phase II high schools in 15 districts, with students from Classes 8 to 10). It is ten years old and says nothing about Classes 6 and 7 or about any newer syllabus. In the hardware count, 165 of 463 thin clients (36 per cent) were non-working, and only 19 schools had working internet. SSLC exam sites list vocational computing options such as Programming in ANSI C and Elements of Computer Science; The AI reader did not find their syllabi and did not write them up. My one link is weak: the report says the range of ICT software was narrow but does not say programming was absent. This record is AI-drafted and no subject expert has reviewed it. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"CIET, NCERT, Third Party Evaluation of ICT@Schools Scheme in Karnataka (2015): Introduction (page 1), sample (page 3), hardware (page 4), software, internet and use of ICT (pages 7 to 8), problems (pages 16 to 17), results (page 18), recommendations (pages 19 to 20).","description":"The evaluation reviewed computer education in Karnataka government high schools, which the state had expanded since 2000-01 through Mahiti Sindhu and the national ICT@Schools scheme. In 184 sampled schools it found many computers out of order, little working internet, and ICT lessons built on office programs and media players. It found no well-defined ICT programme and advised the state to draw up a curricular programme, adapting the national ICT curriculum.","verificationStatus":"primary-source-confirmed","slug":"ict-at-schools-third-party-evaluation-2015","dateStart":"2015","dateGranularity":"year","eventType":"other","temporalStatus":"past-completed","topicTags":["ict-at-schools","computer-education","ict-curriculum","high-school"]}', ''),
  ('2f02b644-59ee-5b2e-9fbe-3c15d4e14896', 'karnataka-curriculum-repository', 'institutional-mandate-record', 'IN-KA', 'openlpm-starter-draft', 'IN-KA-MANDATE-scf-foundational-stage-draft-2023-03', 'Karnataka Department of School Education and Literacy: draft State Curriculum Framework for the Foundational Stage (25 March 2023)', '{"id":"IN-KA-MANDATE-scf-foundational-stage-draft-2023-03","label":"Karnataka Department of School Education and Literacy: draft State Curriculum Framework for the Foundational Stage (25 March 2023)","sourceUrl":"https://www.deccanherald.com/india/karnataka/curriculum-framework-for-foundation-level-education-released-in-ktaka-1203597.html","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Deccan Herald, ''Curriculum framework for foundation-level education released in K''taka'', 26 March 2023; EducationWorld, 25 March 2023 (karnataka-report-on-state-curriculum-framework-for-foundational-stage-released); Deccan Herald, ''Kannada script complex, says draft State Curriculum Framework'', 30 March 2023. The framework document itself was not read.. Secondary sources only: Deccan Herald (26 and 30 March 2023) and EducationWorld (25 March 2023). Deccan Herald says the department issued a press communication; The AI reader could not find it online. The framework itself (said to exist in Kannada and English) was not on any site the AI reader could open, and the AI reader could not confirm that a final version was issued. Deccan Herald reports the draft recommends 4 hours of schooling a day for ages 3 to 6 and 5.5 hours for ages 6 to 8, and asks the state to settle its language-of-instruction policy; these are not used in the statement. Nali Kali background from news reports: a multi-grade, activity-based programme first used at a government school in HD Kote in 1995 (Deccan Herald; Hans India says 1995-96) and in all government Kannada-medium schools by 2010-11 (Hans India). On 11 February 2026 Deccan Herald reported that the Department of School Education and Literacy confirmed Nali Kali would be phased out from 2026-27 in 16,762 Urdu- and Kannada-medium schools, citing its textbook procurement order. On 12 February 2026 the State Kannada Development Authority said the scheme had failed to meet its aims (Hans India). The Federal (19 February 2026) gave a figure of 29,000 schools from an unnamed official; The AI reader did not re-open it. The reports use small groups as a teaching method and do not describe what children learn about groups or cooperation, so the AI reader wrote no links to the Social-Core model. This record is AI-drafted and no subject expert has reviewed it. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-KA","sourcePassage":"Deccan Herald, ''Curriculum framework for foundation-level education released in K''taka'', 26 March 2023; EducationWorld, 25 March 2023 (karnataka-report-on-state-curriculum-framework-for-foundational-stage-released); Deccan Herald, ''Kannada script complex, says draft State Curriculum Framework'', 30 March 2023. The framework document itself was not read.","description":"The draft covers children aged 3 to 8 in two steps, ages 3 to 6 and 6 to 8, and adapts the national foundational-stage framework of October 2022. It proposes changes to Chilipili, the anganwadi programme, and to Nali Kali, the activity-based programme for Classes 1 to 3, and recommends play and activity-based learning. It was put out for public comment, with the aim of use from 2023-24.","verificationStatus":"secondary-source-only","issuingBody":"Department of School Education and Literacy and Department of Women and Child Development, Government of Karnataka","mandateType":"curriculum-framework","adoptionDate":"2023-03-25","dateGranularity":"day","statementText":"The draft covers children aged 3 to 8 in two steps, ages 3 to 6 and 6 to 8, and adapts the national foundational-stage framework of October 2022. It proposes changes to Chilipili, the anganwadi programme, and to Nali Kali, the activity-based programme for Classes 1 to 3, and recommends play and activity-based learning. It was put out for public comment, with the aim of use from 2023-24.","subject":"general","topicTags":["foundational-stage","early-years","chilipili","nali-kali","play-based-learning"]}', '2023-03-25'),
  ('18842d15-a424-5873-b64b-d3c643733029', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-scert-scf-foundational-stage-2024', 'SCERT Maharashtra, State Curriculum Framework (Foundational Stage) 2024, for ages 3 to 8 (Balvatika to Class 2)', '{"id":"IN-MH-MANDATE-scert-scf-foundational-stage-2024","label":"SCERT Maharashtra, State Curriculum Framework (Foundational Stage) 2024, for ages 3 to 8 (Balvatika to Class 2)","sourceUrl":"https://maa.ac.in/documents/SCF_FS_Final.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Rajya Abhyaskram Arakhada: Payabhut Star 2024 (State Curriculum Framework, Foundational Stage 2024), Marathi. Credits page p. ii (first edition March 2024); contents pp. vii-x; chapter 2 sections 2.2-2.3 pp. 53-54 (curricular goals CG-1 to CG-13, Table 2.3 A on p. 54); domain competencies sections 2.4.2-2.4.4 pp. 58-60.. Read in the SCERT PDF (Marathi, 348 pages). The text layer is unreadable, so the credits page, contents, sections 2.2-2.3 and the competency tables were read as page images. The checker re-read the credits page (first edition March 2024, PDF page 4 is p. ii), Table 2.3 A on p. 54 (13 goals) and the competency tables on pp. 58-59 as images and confirmed them. The page offset is 16 (PDF page 80 is p. 64). adoptionDate is the first-edition month printed on the credits page. It is a publication date. The document gives no approval date; the 16 April 2025 GR says the state steering committee approved it. A Marathi reader should check the wording of the goals. Neither reader opened the pedagogy, assessment or content-selection chapters. The matching syllabus is a separate book, Payabhut Shikshan Abhyaskram 2024 (599 pages), which was downloaded and not read. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Rajya Abhyaskram Arakhada: Payabhut Star 2024 (State Curriculum Framework, Foundational Stage 2024), Marathi. Credits page p. ii (first edition March 2024); contents pp. vii-x; chapter 2 sections 2.2-2.3 pp. 53-54 (curricular goals CG-1 to CG-13, Table 2.3 A on p. 54); domain competencies sections 2.4.2-2.4.4 pp. 58-60.","description":"The state framework for ages 3 to 8: three years of Balvatika (pre-school) and Classes 1 and 2. It sets 13 curricular goals: twelve under five areas of child development (body, social and emotional growth, thinking, language and literacy, arts and culture) and one on positive learning habits. It follows the national foundational-stage framework of 2022 and calls for play-based teaching.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Maharashtra, Pune, for the School Education and Sports Department, Government of Maharashtra","mandateType":"curriculum-framework","adoptionDate":"2024-03","dateGranularity":"month","statementText":"The state framework for ages 3 to 8: three years of Balvatika (pre-school) and Classes 1 and 2. It sets 13 curricular goals: twelve under five areas of child development (body, social and emotional growth, thinking, language and literacy, arts and culture) and one on positive learning habits. It follows the national foundational-stage framework of 2022 and calls for play-based teaching.","subject":"general","gradeFrom":1,"gradeTo":2,"topicTags":["foundational-stage","early-childhood","play-based-learning","child-development","literacy","numeracy"]}', ''),
  ('1de646bc-047a-5f2e-8b7a-92f93ba62c72', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-scert-scf-school-education-2024-stages-and-subjects', 'SCERT Maharashtra, State Curriculum Framework for School Education 2024: stages and subjects for Classes 3 to 12', '{"id":"IN-MH-MANDATE-scert-scf-school-education-2024-stages-and-subjects","label":"SCERT Maharashtra, State Curriculum Framework for School Education 2024: stages and subjects for Classes 3 to 12","sourceUrl":"https://maa.ac.in/documents/curriculum/1.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Rajya Abhyaskram Arakhada: Shalaye Shikshan 2024 (State Curriculum Framework, School Education 2024), Marathi. Credits page (first edition October 2024); foreword pp. iii-iv; contents pp. v-vi; vision, Prastavana pp. 1-2; Part A chapter 2, Figure 2(i) p. 34 and sections 2.3.2-2.3.4 pp. 44-46; Part B chapter 6, educational technology pp. 140-145; Part C chapter 9, subject scheme pp. 333-339, including the notes on textbooks on p. 338.. Read in the SCERT PDF (Marathi, 414 pages) as page images because the text layer is unreadable. The checker re-read as images: the credits page (first edition October 2024), Figure 2(i) on p. 34, p. 44, the subject tables on pp. 333-338 and the p. 338 notes. The page offset is 8 (PDF page 209 is p. 201). Words relied on: ''आपल्या सभोवतालचे जग-१'' and ''-२'' for the two-part Our Surrounding World, ''अनिवार्य'' (compulsory) for Marathi to Class 12, ''पूर्वमाध्यमिक स्तर'' for the Classes 6 to 8 stage, and ''जशीच्या तशी'' (as they are) for the NCERT books. The subject tables list no computing subject. The educational technology chapter treats ICT, AI and generative AI as teaching tools and names the national YUVAi programme for students. It lists no state computing syllabus. Neither reader read the Class 11 and 12 subject list closely. The framework makes Hindi available from Class 1 for Marathi and English medium schools; news reports say the Hindi rule in the 2025 GR was put on hold. A news report gives 9 September 2024 for steering committee approval. No official document seen gives it, and a second search found only news pages, so the date stays unverified. The July 2025 SCERT draft and the SCERT home-page remark about a 2026 syllabus were not checked. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Rajya Abhyaskram Arakhada: Shalaye Shikshan 2024 (State Curriculum Framework, School Education 2024), Marathi. Credits page (first edition October 2024); foreword pp. iii-iv; contents pp. v-vi; vision, Prastavana pp. 1-2; Part A chapter 2, Figure 2(i) p. 34 and sections 2.3.2-2.3.4 pp. 44-46; Part B chapter 6, educational technology pp. 140-145; Part C chapter 9, subject scheme pp. 333-339, including the notes on textbooks on p. 338.","description":"Maharashtra''s framework for Classes 3 to 12, written to follow NEP 2020 and NCF-SE 2023. It uses the 5+3+3+4 stages (calling Classes 6 to 8 the pre-secondary stage), keeps Marathi compulsory to Class 12, and has Classes 3 to 5 study science and social studies as a two-part course called Our Surrounding World. The Class 3 to 10 subject tables list no separate computing subject. Its notes say NCERT science and mathematics books are adopted as they are, with local pictures and examples.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Maharashtra, Pune, for the School Education and Sports Department, Government of Maharashtra","mandateType":"curriculum-framework","adoptionDate":"2024-10","dateGranularity":"month","statementText":"Maharashtra''s framework for Classes 3 to 12, written to follow NEP 2020 and NCF-SE 2023. It uses the 5+3+3+4 stages (calling Classes 6 to 8 the pre-secondary stage), keeps Marathi compulsory to Class 12, and has Classes 3 to 5 study science and social studies as a two-part course called Our Surrounding World. The Class 3 to 10 subject tables list no separate computing subject. Its notes say NCERT science and mathematics books are adopted as they are, with local pictures and examples.","subject":"general","gradeFrom":3,"gradeTo":12,"topicTags":["state-curriculum-framework","ncf-se-2023","nep-2020","stages","subject-scheme","marathi"]}', ''),
  ('dd95ba1c-dbd3-5872-96fd-16bb8f24d06a', 'maharashtra-curriculum-repository', 'policy-timeline-event', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-EVENT-gr-2025-04-16-phased-rollout-of-new-curriculum', 'Maharashtra School Education Dept. GR of 16 April 2025: new curriculum and textbooks phased in from 2025-26 to 2028-29', '{"id":"IN-MH-EVENT-gr-2025-04-16-phased-rollout-of-new-curriculum","label":"Maharashtra School Education Dept. GR of 16 April 2025: new curriculum and textbooks phased in from 2025-26 to 2028-29","sourceUrl":"https://maa.ac.in/documents/shasan_nirnay/GR_syllabus_implementation.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Government Resolution No. Sankirna-2025/Pra.Kra.94/SD-4 (Marathi), School Education and Sports Department, Mantralaya, Mumbai, dated 16 April 2025, titled on phased implementation of the new curriculum from 2025-26 under NEP 2020. All 6 pages read: preamble pp. 1-2; decision and items 1-4 (stages, year-by-year table, languages, curriculum and bridge course) p. 3; items 5-7 (textbooks, subject scheme, assessment) p. 4; item 8 (timetable) p. 5.. Read the whole GR (Marathi) as page images; the checker re-read all six pages as images. The GR is dated 16 April 2025 (digital signature stamp reads 2025.04.16). The year-by-year table on p. 3 was read digit by digit: 2025-26 Class 1; 2026-27 Classes 2, 3, 4 and 6; 2027-28 Classes 5, 7, 9 and 11; 2028-29 Classes 8, 10 and 12. Words relied on: ''टप्प्या-टप्प्याने'' (phase by phase), ''आवश्यक त्या बदलासह'' (with the necessary changes) and ''राष्ट्रीय शैक्षणिक संशोधन व प्रशिक्षण परिषद (NCERT)''. NCERT textbook wording is in the preamble (p. 2) and item 5 (p. 4). The word CBSE appears nowhere in the GR. The framework itself uses ''NCERT/CBSE'' once (p. 338), for books in other languages. News reports call the plan CBSE-style. Item 3 made Hindi the third language for Classes 1 to 5 in Marathi and English medium schools. News reports say the minister put that item on hold on 22 April 2025 and that a later GR in June 2025 changed it. Neither reader read that later GR, so the current language rule needs checking. Balvatika 1 to 3 is left to a separate GR with the Women and Child Development department. The state GR portal needs a captcha and was not searched. The 2026-27 Class 3 and Class 6 books on Balbharati''s site are first editions dated 2026, which fits the table. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Government Resolution No. Sankirna-2025/Pra.Kra.94/SD-4 (Marathi), School Education and Sports Department, Mantralaya, Mumbai, dated 16 April 2025, titled on phased implementation of the new curriculum from 2025-26 under NEP 2020. All 6 pages read: preamble pp. 1-2; decision and items 1-4 (stages, year-by-year table, languages, curriculum and bridge course) p. 3; items 5-7 (textbooks, subject scheme, assessment) p. 4; item 8 (timetable) p. 5.","description":"The Government of Maharashtra approved putting SCERT''s two 2024 curriculum frameworks (foundational stage and school education) into effect in phases, with suitable changes. The new curriculum starts in Class 1 in 2025-26, Classes 2, 3, 4 and 6 in 2026-27, Classes 5, 7, 9 and 11 in 2027-28, and Classes 8, 10 and 12 in 2028-29. NCERT textbooks are to be adopted with the changes Maharashtra needs, Balbharati makes the books available, and SCERT prepares bridge courses.","verificationStatus":"primary-source-confirmed","slug":"gr-2025-04-16-phased-rollout-of-new-curriculum","dateStart":"2025-04-16","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["phased-implementation","ncert-textbooks","balbharati","ncf-se-2023","holistic-progress-card","bridge-course"]}', '2025-04-16'),
  ('90468668-74b4-5f29-a1ad-2c5dc0881b48', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-scert-scf-school-education-2024-science', 'SCERT Maharashtra, State Curriculum Framework for School Education 2024, Science: aims and goals for Classes 6 to 10', '{"id":"IN-MH-MANDATE-scert-scf-school-education-2024-science","label":"SCERT Maharashtra, State Curriculum Framework for School Education 2024, Science: aims and goals for Classes 6 to 10","sourceUrl":"https://maa.ac.in/documents/curriculum/1.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Rajya Abhyaskram Arakhada: Shalaye Shikshan 2024 (Marathi), Part C chapter 3, Vidnyan Shikshan (Science education), pp. 201-212. Aims 3.1 pp. 201-203; nature of knowledge 3.2 p. 203; Middle-stage (pre-secondary, Classes 6 to 8) goals and competencies 3.4 b pp. 204-206; Secondary-stage (Classes 9 and 10) goals and competencies 3.4 c pp. 207-209; pedagogy 3.6 pp. 211-212.. Read as page images (Marathi) and re-read by the checker. Confirmed: nine middle-stage goals CG-1 to CG-9 (pp. 204-206), eight secondary goals CG-1 to CG-8 (pp. 207-209), and the three competencies on p. 208. Words relied on: ''आनुवंशिकता'', ''जनुक'', ''गुणसूत्र'' (heredity, gene, chromosome) in C-3.3; ''मेंडेल'', ''नियम'', ''लोकसंख्या पातळी'' (Mendel, rules, population level) in C-4.4; ''नैसर्गिक निवड'', ''जैविक उत्क्रांती पुरावे'', ''युग्म विकल्पी (एलिल)'', ''वारंवारता'' (natural selection, evidence of biological evolution, allele, frequency) in C-4.5. The English national framework (NCF-SE 2023, Part C, Science, secondary table, p. 281) has the same codes. Where the Marathi differs from it: C-3.3 gives variation as ''according to change in position of genes'' in Marathi and as changes in the DNA sequence in English; C-4.4 says ''related to evolution'' (उत्क्रांतीसंबंधी) in Marathi and ''inheritance of traits'' in English, so the drafter''s reading as rules of inheritance is right; C-6.1 says ''creation of the living world'' in Marathi and ''spontaneous generation of life'' in English. These look like translation differences, and a Marathi reader should confirm. The statement uses none of these three words. Section 3.6 pedagogy starts on p. 211. The framework''s textbook notes (p. 338) say NCERT science books are adopted as they are, which matters for the national deletion of evolution content; see the stages-and-subjects record. Neither reader read Classes 11 and 12 science. The Class 6 Science book mapping and chapter 4 remarks in the draft were not rechecked. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Rajya Abhyaskram Arakhada: Shalaye Shikshan 2024 (Marathi), Part C chapter 3, Vidnyan Shikshan (Science education), pp. 201-212. Aims 3.1 pp. 201-203; nature of knowledge 3.2 p. 203; Middle-stage (pre-secondary, Classes 6 to 8) goals and competencies 3.4 b pp. 204-206; Secondary-stage (Classes 9 and 10) goals and competencies 3.4 c pp. 207-209; pedagogy 3.6 pp. 211-212.","description":"The science chapter names seven aims, including creativity and understanding how scientific knowledge developed over time, and describes science as a creative effort whose knowledge keeps changing. Classes 6 to 8 follow nine curricular goals and Classes 9 and 10 follow eight. In Classes 9 and 10, students explain DNA, genes and chromosomes, study population-level effects of Mendel''s rules, and analyse natural selection using evidence for evolution, including allele frequency in a population.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Maharashtra, Pune, for the School Education and Sports Department, Government of Maharashtra","mandateType":"curriculum-framework","adoptionDate":"2024-10","dateGranularity":"month","statementText":"The science chapter names seven aims, including creativity and understanding how scientific knowledge developed over time, and describes science as a creative effort whose knowledge keeps changing. Classes 6 to 8 follow nine curricular goals and Classes 9 and 10 follow eight. In Classes 9 and 10, students explain DNA, genes and chromosomes, study population-level effects of Mendel''s rules, and analyse natural selection using evidence for evolution, including allele frequency in a population.","subject":"science","gradeFrom":6,"gradeTo":10,"topicTags":["science","nature-of-science","heredity","genes","natural-selection","evolution","allele-frequency","scientific-inquiry"]}', ''),
  ('da56312a-57af-52a1-b432-200d5d48e9e4', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-scert-scf-school-education-2024-social-science', 'SCERT Maharashtra, State Curriculum Framework for School Education 2024, Social Science: goals for Classes 6 to 10', '{"id":"IN-MH-MANDATE-scert-scf-school-education-2024-social-science","label":"SCERT Maharashtra, State Curriculum Framework for School Education 2024, Social Science: goals for Classes 6 to 10","sourceUrl":"https://maa.ac.in/documents/curriculum/1.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Rajya Abhyaskram Arakhada: Shalaye Shikshan 2024 (Marathi), Part C chapter 4, Samajikshastre Shikshan (Social science education), pp. 216-228. Structure pp. 216-217; aims and nature of knowledge 4.1-4.2 p. 218; Middle-stage goals CG-1 to CG-11 (Classes 6 to 8) pp. 220-223, with C-8.1 to C-8.3 on the Constitution and local government on p. 222; Secondary-stage goals (Classes 9 and 10) pp. 223-228, with CG-5 on p. 226, CG-6 on pp. 226-227 and C-8.6 on the cooperative movement on p. 228.. Read as page images (Marathi); a Marathi reader should check the AI reader''s wording. CG is the framework''s curricular goal and C its competency. The Class 6 History and Civics textbook (first edition June 2026, approved 19 May 2026) has a civics part on social life, the Constitution, the Preamble, rural and urban local self-government and district administration; The AI reader read its contents and competency table but not every chapter. Older books still in use for 2026-27: the Class 8 civics part (2018) on the parliamentary system and the Class 10 Political Science part (2018) on working of the Constitution. The AI reader found no textbook chapter that develops the cooperative-movement competency (C-8.6); the Class 9 history book mentions cooperatives only in passing. Economics appears inside the Class 9 geography book in the current set (a chapter called Introduction to Economics). AI-drafted and not reviewed by a Maharashtra educator. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Rajya Abhyaskram Arakhada: Shalaye Shikshan 2024 (Marathi), Part C chapter 4, Samajikshastre Shikshan (Social science education), pp. 216-228. Structure pp. 216-217; aims and nature of knowledge 4.1-4.2 p. 218; Middle-stage goals CG-1 to CG-11 (Classes 6 to 8) pp. 220-223, with C-8.1 to C-8.3 on the Constitution and local government on p. 222; Secondary-stage goals (Classes 9 and 10) pp. 223-228, with CG-5 on p. 226, CG-6 on pp. 226-227 and C-8.6 on the cooperative movement on p. 228.","description":"In Classes 6 to 8, students learn why India needs a Constitution, how it was made and how the three tiers of local self-government work, and they study cultural diversity, inequality and prejudice. In Classes 9 and 10, they study constitutional values and democratic process, discrimination and ways to reduce it, and the cooperative movement in India and Maharashtra. Some goals are specific to Maharashtra, such as the Maratha state and the saint tradition.","verificationStatus":"primary-source-confirmed","issuingBody":"State Council of Educational Research and Training (SCERT) Maharashtra, Pune, for the School Education and Sports Department, Government of Maharashtra","mandateType":"curriculum-framework","adoptionDate":"2024-10","dateGranularity":"month","statementText":"In Classes 6 to 8, students learn why India needs a Constitution, how it was made and how the three tiers of local self-government work, and they study cultural diversity, inequality and prejudice. In Classes 9 and 10, they study constitutional values and democratic process, discrimination and ways to reduce it, and the cooperative movement in India and Maharashtra. Some goals are specific to Maharashtra, such as the Maratha state and the saint tradition.","subject":"social-science","gradeFrom":6,"gradeTo":10,"topicTags":["civics","constitution","local-self-government","democracy","social-diversity","prejudice","cooperative-movement","maharashtra-history"]}', ''),
  ('c73622f5-ff13-594f-8fc5-c1c62d0d96c5', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution', 'Balbharati, Science and Technology Std X Part 2, Chapter 1 ''Heredity and Evolution'' (2018, reprint 2022)', '{"id":"IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution","label":"Balbharati, Science and Technology Std X Part 2, Chapter 1 ''Heredity and Evolution'' (2018, reprint 2022)","sourceUrl":"https://ebooks.ebalbharati.in/pdfs/1003000270.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Science and Technology, Standard Ten, Part 2 (English medium), Balbharati, first edition 2018, reprint 2022. Chapter 1, Heredity and Evolution, pp. 1-11 (chapter 2 starts on p. 12); competency statements and contents on the front-matter pages (PDF pages 9 and 10, lettered G and H in the text layer); preface dated 18 March 2018; textbook approved 29 December 2017 for use from 2018-19.. Read the full chapter text in the English-medium PDF; the checker re-read it and confirmed the chapter title, page range, edition years, preface date and contents. Balbharati reserves all rights, so the record paraphrases. The last sentence of the Lamarck section says organisms can pass on acquired characters, straight after the text says that idea was disproved. This looks like a printing or translation slip; please check the Marathi book. The chapter treats natural selection as survival of the fittest and lists three objections to Darwin. It gives no worked example for speciation and does not use the word allele. This is the 2018 book. Under the 16 April 2025 GR, Class 10 moves to the new curriculum in 2028-29, so it should still be the Class 10 book in 2026-27; please confirm what schools use. The national NCERT deletion of evolution content has not removed this chapter from the 2018 state book. The state framework (p. 338) says NCERT science books are adopted as they are, so what the Class 10 book of 2028-29 keeps is open. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"Science and Technology, Standard Ten, Part 2 (English medium), Balbharati, first edition 2018, reprint 2022. Chapter 1, Heredity and Evolution, pp. 1-11 (chapter 2 starts on p. 12); competency statements and contents on the front-matter pages (PDF pages 9 and 10, lettered G and H in the text layer); preface dated 18 March 2018; textbook approved 29 December 2017 for use from 2018-19.","description":"An 11-page chapter for Class 10. It covers heredity (a one-sentence mention of Mendel, then DNA, how genes make proteins, and mutation), the idea of gradual evolution, six kinds of evidence (body form, bone structure, vestigial organs, fossils, connecting links, embryos), Darwin''s natural selection, Lamarck''s use and disuse, speciation through isolation, and the stages of human evolution.","verificationStatus":"primary-source-confirmed","issuingBody":"Maharashtra State Bureau of Textbook Production and Curriculum Research (Balbharati), Pune","mandateType":"curriculum-unit","adoptionDate":"2018-03","dateGranularity":"month","statementText":"An 11-page chapter for Class 10. It covers heredity (a one-sentence mention of Mendel, then DNA, how genes make proteins, and mutation), the idea of gradual evolution, six kinds of evidence (body form, bone structure, vestigial organs, fossils, connecting links, embryos), Darwin''s natural selection, Lamarck''s use and disuse, speciation through isolation, and the stages of human evolution.","subject":"science","gradeFrom":10,"gradeTo":10,"topicTags":["heredity","mutation","evolution","natural-selection","darwin","lamarck","speciation","human-evolution","fossils"]}', ''),
  ('4c79faad-bc30-55fd-9417-dfdcb5c04f5e', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-UNIT-balbharati-general-science-class-7-living-world-adaptations-and-classification', 'Balbharati, General Science Std VII, Chapter 1 ''The Living World: Adaptations and Classification'' (2017, reprint 2022)', '{"id":"IN-MH-UNIT-balbharati-general-science-class-7-living-world-adaptations-and-classification","label":"Balbharati, General Science Std VII, Chapter 1 ''The Living World: Adaptations and Classification'' (2017, reprint 2022)","sourceUrl":"https://ebooks.ebalbharati.in/pdfs/703020012.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: General Science, Standard Seven (English medium), Balbharati, first edition 2017, fifth reprint 2022. Chapter 1, The Living World: Adaptations and Classification, pp. 1-9, with the Darwin box on p. 8; contents p. H; preface dated 28 March 2017.. Read the chapter text in the English-medium PDF. Balbharati reserves all rights, so the AI reader paraphrased. The adaptation section uses organism-level wording (changes in organs and life processes) and never mentions variation among individuals or inheritance. The Darwin box is two short paragraphs. The AI reader did not read the Class 3 to 5 books, so the AI reader cannot say what earlier classes teach about habitats or species. Under the 16 April 2025 GR, Class 7 moves to the new curriculum in 2027-28, so this 2017 book should be current for 2026-27. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"General Science, Standard Seven (English medium), Balbharati, first edition 2017, fifth reprint 2022. Chapter 1, The Living World: Adaptations and Classification, pp. 1-9, with the Darwin box on p. 8; contents p. H; preface dated 28 March 2017.","description":"A nine-page chapter for Class 7. It defines adaptation as gradual changes in the organs and behaviour of organisms that help them live in their habitat, gives examples from plants and animals, and has a short box on Darwin''s survival of the fittest and natural selection. The second half teaches the classification hierarchy and two-part scientific names.","verificationStatus":"primary-source-confirmed","issuingBody":"Maharashtra State Bureau of Textbook Production and Curriculum Research (Balbharati), Pune","mandateType":"curriculum-unit","adoptionDate":"2017-03","dateGranularity":"month","statementText":"A nine-page chapter for Class 7. It defines adaptation as gradual changes in the organs and behaviour of organisms that help them live in their habitat, gives examples from plants and animals, and has a short box on Darwin''s survival of the fittest and natural selection. The second half teaches the classification hierarchy and two-part scientific names.","subject":"science","gradeFrom":7,"gradeTo":7,"topicTags":["adaptation","diversity-of-life","classification","binomial-nomenclature","natural-selection","habitat"]}', ''),
  ('474b46cd-54a1-57dc-bfab-4ee32475c658', 'maharashtra-curriculum-repository', 'institutional-mandate-record', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-MANDATE-balbharati-class-6-2026-computational-thinking-and-scratch', 'Balbharati Std VI textbooks 2026: computational thinking in Mathematics and a Scratch project in Vocational Education', '{"id":"IN-MH-MANDATE-balbharati-class-6-2026-computational-thinking-and-scratch","label":"Balbharati Std VI textbooks 2026: computational thinking in Mathematics and a Scratch project in Vocational Education","sourceUrl":"https://ebooks.ebalbharati.in/pdfs/603060004.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: (1) Mathematics, Standard Six (English medium), Balbharati, first edition 2026, approved by the coordination committee on 19 May 2026: front-matter table of curricular goals and competencies, CG 8 and competency C8.1, which cites textbook pages 28-29, 125-126 and 143. (2) Vocational Education, Standard Six, Balbharati, first edition 2026, approved 1 June 2026 (https://ebooks.ebalbharati.in/pdfs/603000870.pdf): About the Book, index, and Project 4 Animation and Games, pp. 64-82 (Scratch checklist p. 75, bug check p. 76).. Read the English-medium PDFs of both books. The checker re-read the Mathematics front table and the cited pages (PDF pages 42, 43, 139, 140 and 157; page offset 14), and the Vocational About the Book, index, Project 4 pages and checklists. Balbharati reserves all rights, so the record paraphrases. The Mathematics book was approved on 19 May 2026 and the Vocational book on 1 June 2026, both for use from 2026-27; adoptionDate 2026-06 follows the later date. In the Vocational book, Class 6 students take one project from each of three forms of work, and finishing three projects is compulsory. Vocational Education is a core subject from Class 6. Its Scratch game stage has a checklist item on if-else conditions, loops and variables (p. 75) and a step on finding and removing bugs (p. 76). It also uses AI image generators to make pictures. One sentence calls JavaScript, Python and C visual programming languages, which is an error; please check. The Class 9 Science and Technology ICT chapter and the Class 3 Work Education computer pages mentioned in the draft were not rechecked. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"(1) Mathematics, Standard Six (English medium), Balbharati, first edition 2026, approved by the coordination committee on 19 May 2026: front-matter table of curricular goals and competencies, CG 8 and competency C8.1, which cites textbook pages 28-29, 125-126 and 143. (2) Vocational Education, Standard Six, Balbharati, first edition 2026, approved 1 June 2026 (https://ebooks.ebalbharati.in/pdfs/603000870.pdf): About the Book, index, and Project 4 Animation and Games, pp. 64-82 (Scratch checklist p. 75, bug check p. 76).","description":"The 2026 Class 6 Mathematics book lists a computational-thinking goal in its front table: breaking problems into parts, spotting patterns, showing data in tables and diagrams, and writing steps in order. The lessons it cites cover number patterns, a fractal drawing activity, the Baudhayana-Pythagoras theorem and an infographic. The 2026 Class 6 Vocational Education book has a Scratch animations and games project, one of two examples in its machines-and-materials group. Schools pick one project per group, so the Scratch project is optional.","verificationStatus":"primary-source-confirmed","issuingBody":"Maharashtra State Bureau of Textbook Production and Curriculum Research (Balbharati), Pune, for SCERT Maharashtra","mandateType":"other","adoptionDate":"2026-06","dateGranularity":"month","statementText":"The 2026 Class 6 Mathematics book lists a computational-thinking goal in its front table: breaking problems into parts, spotting patterns, showing data in tables and diagrams, and writing steps in order. The lessons it cites cover number patterns, a fractal drawing activity, the Baudhayana-Pythagoras theorem and an infographic. The 2026 Class 6 Vocational Education book has a Scratch animations and games project, one of two examples in its machines-and-materials group. Schools pick one project per group, so the Scratch project is optional.","subject":"computer-science","gradeFrom":6,"gradeTo":6,"topicTags":["computational-thinking","coding","scratch","algorithmic-thinking","vocational-education","class-6","ai-tools"]}', ''),
  ('0a0226e7-0823-56b0-afc5-5c10cdee53a1', 'maharashtra-curriculum-repository', 'policy-timeline-event', 'IN-MH', 'openlpm-starter-draft', 'IN-MH-EVENT-scert-circular-2026-07-15-ai-saathi-for-educators', 'SCERT Maharashtra circular of 15 July 2026: all Class 1 to 12 teachers to take the ''AI Saathi for Educators'' course', '{"id":"IN-MH-EVENT-scert-circular-2026-07-15-ai-saathi-for-educators","label":"SCERT Maharashtra circular of 15 July 2026: all Class 1 to 12 teachers to take the ''AI Saathi for Educators'' course","sourceUrl":"https://maa.ac.in/documents/forteachers.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: SCERT Maharashtra circular no. SCERT-28.0/32/2025-IT/BROADCAST MEDIA, I/2022467/2026 (Marathi), digitally signed 15 July 2026, pp. 1-2. Page 1 gives the purpose, content and deadlines; page 2 gives the steps for enrolling on DIKSHA. The circular says the course was opened at Mantralaya, Mumbai, on 14 July 2026 by the School Education Minister.. Read both pages of the circular (Marathi). It is about teacher training and gives no student syllabus. The AI reader found no Maharashtra state-board curriculum or GR that adds AI or coding as a student subject; the student-facing computing items the AI reader could confirm are in the Class 6 record. Secondary reports (CSR and news sites that the AI reader only skimmed) say the course is compulsory for about 7.5 lakh teachers and officers; the circular itself says teachers must complete it. A separate circular for other education staff is on the same SCERT page and the AI reader did not read it. The national AI and computational thinking curriculum for Classes 3 to 8 (CBSE and NCERT, 2026-27) is a national item; The AI reader found no Maharashtra notice adopting it. AI-drafted and not reviewed by a Maharashtra educator. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-MH","sourcePassage":"SCERT Maharashtra circular no. SCERT-28.0/32/2025-IT/BROADCAST MEDIA, I/2022467/2026 (Marathi), digitally signed 15 July 2026, pp. 1-2. Page 1 gives the purpose, content and deadlines; page 2 gives the steps for enrolling on DIKSHA. The circular says the course was opened at Mantralaya, Mumbai, on 14 July 2026 by the School Education Minister.","description":"SCERT asks every teacher of Classes 1 to 12 to finish ''AI Saathi for Educators'', an online DIKSHA course built with Kotak Education Foundation that covers basic ideas of AI and machine learning, uses of AI in teaching and school administration, and responsible, safe use. It counts for 4 of the 50 yearly training hours that NEP 2020 expects. Enrolment runs to 31 August 2026 and the course must be finished by 30 September 2026.","verificationStatus":"primary-source-confirmed","slug":"scert-circular-2026-07-15-ai-saathi-for-educators","dateStart":"2026-07-15","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["artificial-intelligence","teacher-training","diksha","cpd","responsible-ai"]}', '2026-07-15'),
  ('18226fdf-0f06-5a31-8670-c86beca40af0', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-maths-ct-competencies-by-stage', 'NCERT, NCF-SE 2023, Mathematics and Computational Thinking: goals and competencies, Classes 3 to 10', '{"id":"IN-MANDATE-ncf-se-2023-maths-ct-competencies-by-stage","label":"NCERT, NCF-SE 2023, Mathematics and Computational Thinking: goals and competencies, Classes 3 to 10","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023, Part C, Chapter 3 Mathematics Education: Section 3.4 Learning Standards (printed p. 252); 3.4.1.1 Preparatory Stage, CG-4 (p. 254); 3.4.1.2 Middle Stage, CG-5 and CG-8 (p. 256); 3.4.1.3 Secondary Stage, CG-8 and CG-9 (p. 259). Box 3.2 history note on Pingala (p. 263).. Read directly: the NCERT printed edition of the framework (first edition October 2024). The file name says August 2023, so the 2023-08 date comes from that name and from the AI reader''s general knowledge that the framework was released in August 2023. No release date is printed in the text the AI reader read. Page numbers are the printed ones, which are 14 lower than the PDF page numbers. The competency tables lost their layout in text extraction, so the AI reader matched competency numbers to sentences by order. A reviewer should check CG-8 (Middle Stage) and CG-9 (Secondary Stage) against the original tables. The Preparatory Stage has no data competency; data handling appears only in the stage overview on p. 252. The AI reader did not read the Classes 11 and 12 sections for this record (see the separate record on AI and computing subjects). AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023, Part C, Chapter 3 Mathematics Education: Section 3.4 Learning Standards (printed p. 252); 3.4.1.1 Preparatory Stage, CG-4 (p. 254); 3.4.1.2 Middle Stage, CG-5 and CG-8 (p. 256); 3.4.1.3 Secondary Stage, CG-8 and CG-9 (p. 259). Box 3.2 history note on Pingala (p. 263).","description":"The framework treats computational thinking as part of school mathematics. In Classes 3 to 5, problem solving and systematic counting are a step towards it. In Classes 6 to 8, one goal covers abstraction, algorithms, decomposition, pattern recognition, generalisation and data representation, and a separate goal covers collecting, graphing and interpreting data. In Classes 9 and 10, students split complex problems into simple ones and design algorithmic solutions.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT, for the Ministry of Education, Government of India","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"The framework treats computational thinking as part of school mathematics. In Classes 3 to 5, problem solving and systematic counting are a step towards it. In Classes 6 to 8, one goal covers abstraction, algorithms, decomposition, pattern recognition, generalisation and data representation, and a separate goal covers collecting, graphing and interpreting data. In Classes 9 and 10, students split complex problems into simple ones and design algorithmic solutions.","subject":"mathematics","gradeFrom":3,"gradeTo":10,"topicTags":["computational-thinking","algorithms","decomposition","data-handling","mathematical-modelling"]}', ''),
  ('de351228-2b8d-503f-b523-a8c860fadfb2', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-ai-and-computing-in-school', 'NCERT, NCF-SE 2023 on AI and machine learning in schools, and computer science and AI in Classes 11 and 12', '{"id":"IN-MANDATE-ncf-se-2023-ai-and-computing-in-school","label":"NCERT, NCF-SE 2023 on AI and machine learning in schools, and computer science and AI in Classes 11 and 12","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023, Part B, section 6.1.1 Evolving and Emerging Technology, including the Generative AI paragraphs (printed pp. 178-179); Part A, section 2.3.4.2 Curricular Structure, point on Grades 11 and 12 subjects (p. 64); Part C, section 10.3 Mathematics and Computational Thinking (p. 461).. Read directly. The generative AI paragraphs sit inside the technology-in-education section, so they speak about AI in teaching and learning more than about a school subject. The Classes 11 and 12 passages are short. Part A says the framework sets no learning standards for Class 11 and 12 subjects, and section 10.3 gives content areas only for core mathematics. The framework also lists coding and computational thinking among skills for all students (p. 4). No grade range is set on this record because the AI passage applies to all stages. A reviewer should check whether a later NCERT document gives Class 11 and 12 computer science standards. AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023, Part B, section 6.1.1 Evolving and Emerging Technology, including the Generative AI paragraphs (printed pp. 178-179); Part A, section 2.3.4.2 Curricular Structure, point on Grades 11 and 12 subjects (p. 64); Part C, section 10.3 Mathematics and Computational Thinking (p. 461).","description":"The framework says students and teachers should understand in basic terms how AI, machine learning and generative AI work, and how to judge their use. It names biased output, data privacy and students handing their thinking to AI as risks. For Classes 11 and 12 it lists computer science as an illustrative subject in the mathematics and computational thinking area and allows AI as a contemporary subject, with no learning standards for either.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT, for the Ministry of Education, Government of India","mandateType":"policy-statement","adoptionDate":"2023-08","dateGranularity":"month","statementText":"The framework says students and teachers should understand in basic terms how AI, machine learning and generative AI work, and how to judge their use. It names biased output, data privacy and students handing their thinking to AI as risks. For Classes 11 and 12 it lists computer science as an illustrative subject in the mathematics and computational thinking area and allows AI as a contemporary subject, with no learning standards for either.","subject":"computer-science","topicTags":["artificial-intelligence","machine-learning","generative-ai","computer-science","grades-11-12"]}', ''),
  ('4ed7e1a4-82e0-5e56-b76a-6b6723633d3a', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-coding-and-computational-thinking', 'Ministry of Education, NEP 2020: coding and computational thinking in school (paras 4.23 and 4.25)', '{"id":"IN-MANDATE-nep-2020-coding-and-computational-thinking","label":"Ministry of Education, NEP 2020: coding and computational thinking in school (paras 4.23 and 4.25)","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, chapter 4, paras 4.23 and 4.25 (printed p. 15; PDF page 16), in the copy hosted by the Press Information Bureau. NCERT, Guidelines for Position Papers for the Development of the National Curricular Framework, section 2.8 (printed p. 46) quotes the same paragraphs.. AI-drafted, and no subject expert has reviewed this record. Re-checked against the policy text in the PIB-hosted copy (printed numbers; the PDF page is one higher). The policy PDF prints no date. PIB release 1642061 of 29 July 2020 reports the Cabinet approval, so only the month is given. The Middle Stage is Classes 6 to 8 in the policy''s 5+3+3+4 structure (para 4.1). A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, chapter 4, paras 4.23 and 4.25 (printed p. 15; PDF page 16), in the copy hosted by the Press Information Bureau. NCERT, Guidelines for Position Papers for the Development of the National Curricular Framework, section 2.8 (printed p. 46) quotes the same paragraphs.","description":"NEP 2020 lists digital literacy, coding and computational thinking among skills every student should learn. It asks for more emphasis on mathematics and computational thinking through the school years, starting at the Foundational Stage and using puzzles and games, and says coding activities begin at the Middle Stage. It links this to India''s future role in AI, machine learning and data science.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (then Ministry of Human Resource Development), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"NEP 2020 lists digital literacy, coding and computational thinking among skills every student should learn. It asks for more emphasis on mathematics and computational thinking through the school years, starting at the Foundational Stage and using puzzles and games, and says coding activities begin at the Middle Stage. It links this to India''s future role in AI, machine learning and data science.","subject":"computational-thinking","topicTags":["coding","computational-thinking","digital-literacy","middle-stage"]}', ''),
  ('41cdf413-b61b-55c7-947d-7681886e2c53', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-cbse-ct-ai-curriculum-classes-3-5-2026', 'CBSE, Computational Thinking and AI Curriculum Classes 3 to 8, Classes 3 to 5 (Preparatory Stage), session 2026-27', '{"id":"IN-MANDATE-cbse-ct-ai-curriculum-classes-3-5-2026","label":"CBSE, Computational Thinking and AI Curriculum Classes 3 to 8, Classes 3 to 5 (Preparatory Stage), session 2026-27","sourceUrl":"https://cbseacademic.nic.in/web_material/CurriculumMain27/CTAI_Pri_2026-27.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CBSE, Computational Thinking and Artificial Intelligence, Classes 3-8 Curriculum (2026-27): section 2.1 Progression (p. 8), 3.4 Time Allocation (p. 10), 6.1 Curricular Goals and Competencies for Classes 3-5 (pp. 14-15), 10.1 Syllabus and Learning Outcomes for Classes 3-5 (pp. 19-21). Also CBSE Circular Acad-15/2026 of 1 April 2026, and the Class 3 Computational Thinking Teacher Handbook, First Edition March 2026, pp. 5-7.. Read directly: the curriculum document, Circular Acad-15/2026 (dated 1 April 2026, which launches it) and the Class 3 teacher handbook. The Ministry''s press release of 1 April 2026 (PIB release 2247963, read on pib.gov.in) reports the Education Minister launching it. The AI reader did not read the Class 4 and 5 handbooks. The documents do not say whether the course is compulsory for schools or how it is graded beyond suggested methods. One coaching website says it is compulsory with no board exam; The AI reader could not confirm that from CBSE. The curriculum says its standards derive from NCF-SE 2023, and its Classes 3-5 competencies C-3 and C-4 repeat NCF-SE preparatory-stage wording. AI-drafted, and no subject expert has reviewed this record. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"CBSE, Computational Thinking and Artificial Intelligence, Classes 3-8 Curriculum (2026-27): section 2.1 Progression (p. 8), 3.4 Time Allocation (p. 10), 6.1 Curricular Goals and Competencies for Classes 3-5 (pp. 14-15), 10.1 Syllabus and Learning Outcomes for Classes 3-5 (pp. 19-21). Also CBSE Circular Acad-15/2026 of 1 April 2026, and the Class 3 Computational Thinking Teacher Handbook, First Edition March 2026, pp. 5-7.","description":"CBSE asks schools to teach computational thinking in Classes 3 to 5 inside Mathematics and The World Around Us, with a suggested 50 hours a year and extra CT questions in resource books. Learning outcomes cover abstract thinking, pattern recognition, decomposition and algorithmic thinking, such as following step-by-step rules on grids and number sequences. One competency adds computer parts, file management, internet safety and block-based coding.","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education (CBSE), under the Ministry of Education","mandateType":"curriculum-framework","adoptionDate":"2026-04-01","dateGranularity":"day","statementText":"CBSE asks schools to teach computational thinking in Classes 3 to 5 inside Mathematics and The World Around Us, with a suggested 50 hours a year and extra CT questions in resource books. Learning outcomes cover abstract thinking, pattern recognition, decomposition and algorithmic thinking, such as following step-by-step rules on grids and number sequences. One competency adds computer parts, file management, internet safety and block-based coding.","subject":"computational-thinking","gradeFrom":3,"gradeTo":5,"topicTags":["computational-thinking","pattern-recognition","decomposition","algorithmic-thinking","block-based-coding","unplugged"]}', '2026-04-01'),
  ('a5098e79-ffb0-5f8a-b466-8af92092b62d', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-cbse-ct-ai-curriculum-classes-6-8-2026', 'CBSE, Computational Thinking and AI Curriculum Classes 3 to 8, Classes 6 to 8 (Middle Stage): advanced CT and early AI', '{"id":"IN-MANDATE-cbse-ct-ai-curriculum-classes-6-8-2026","label":"CBSE, Computational Thinking and AI Curriculum Classes 3 to 8, Classes 6 to 8 (Middle Stage): advanced CT and early AI","sourceUrl":"https://cbseacademic.nic.in/web_material/CurriculumMain27/CTAI_Pri_2026-27.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CBSE, Computational Thinking and Artificial Intelligence, Classes 3-8 Curriculum (2026-27): section 2.1 (p. 8), 3.4 Time Allocation (p. 10), 5 Aims (p. 13), 6.2 Curricular Goals and Competencies for Classes 6-8 (p. 15), 7.2 (p. 16), 8.1 Who Will Teach (p. 17), 10.2 Syllabus and Learning Outcomes by class (pp. 22-27), 10.2.3 Early AI syllabus (pp. 27-29). Also CBSE Circulars Acad-15/2026 (1 April 2026) and Acad-18/2026 (9 April 2026).. Read directly. The hours are a suggested allocation; the document says schools may go beyond them. CT is delivered through resource books that follow the Mathematics textbook. Computer teachers handle AI literacy and assess the projects (p. 17). The AI reader looked only at the front pages of the Class 6 and Class 8 teacher handbooks and did not check their chapters against the syllabus. The Classes 6-8 competencies C-1 and C-2 follow NCF-SE 2023 Middle Stage CG-8 closely. The syllabus text names no simulation or agent-based modelling topic; the Python modelling and simulating remark is in the aims (p. 13). Coding appears for Classes 6-8 only in the pedagogy paragraph (p. 10), which mentions foundational knowledge of coding, data analysis and AI tools, and no programming topic is listed. The Class 7 handbook and student handbooks were not read. AI-drafted, and no subject expert has reviewed this record. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"CBSE, Computational Thinking and Artificial Intelligence, Classes 3-8 Curriculum (2026-27): section 2.1 (p. 8), 3.4 Time Allocation (p. 10), 5 Aims (p. 13), 6.2 Curricular Goals and Competencies for Classes 6-8 (p. 15), 7.2 (p. 16), 8.1 Who Will Teach (p. 17), 10.2 Syllabus and Learning Outcomes by class (pp. 22-27), 10.2.3 Early AI syllabus (pp. 27-29). Also CBSE Circulars Acad-15/2026 (1 April 2026) and Acad-18/2026 (9 April 2026).","description":"For Classes 6 to 8 CBSE suggests 100 hours a year: 40 on advanced computational thinking, 20 on introductory AI and 40 on cross-subject projects. CT outcomes include conditional branching and pathfinding in Class 7, and generalising across number systems, binary among them, in Class 8. The AI syllabus moves from kinds of machine learning (Class 6) to classification, regression and clustering on small datasets (Class 7), and the AI project cycle, no-code tools and dataset bias (Class 8).","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education (CBSE), under the Ministry of Education","mandateType":"curriculum-framework","adoptionDate":"2026-04-01","dateGranularity":"day","statementText":"For Classes 6 to 8 CBSE suggests 100 hours a year: 40 on advanced computational thinking, 20 on introductory AI and 40 on cross-subject projects. CT outcomes include conditional branching and pathfinding in Class 7, and generalising across number systems, binary among them, in Class 8. The AI syllabus moves from kinds of machine learning (Class 6) to classification, regression and clustering on small datasets (Class 7), and the AI project cycle, no-code tools and dataset bias (Class 8).","subject":"computational-thinking","gradeFrom":6,"gradeTo":8,"topicTags":["computational-thinking","machine-learning","ai-ethics","data-representation","interdisciplinary-projects"]}', '2026-04-01'),
  ('b385e83e-a2a2-5c29-9183-1f9acdfcdd36', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-ct-ai-module-grades-9-12-2026', 'NCERT, Introductory Module on Computational Thinking and AI for the Secondary Stage (Classes 9 to 12), October 2026', '{"id":"IN-UNIT-ncert-ct-ai-module-grades-9-12-2026","label":"NCERT, Introductory Module on Computational Thinking and AI for the Secondary Stage (Classes 9 to 12), October 2026","sourceUrl":"https://ncert.nic.in/pdf/An_Introductory_Module_AI_CT_UN514.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: NCERT, An Introductory Module on Computational Thinking and Artificial Intelligence for the Secondary Stage (Grades 9-12), First Edition October 2026 (UN514): About the Module (p. v), Note for the Teacher with the 20-hour plan (pp. ix-xi), Unit 1 (p. 1), Unit 2 sections 2.2 and 2.7-2.8 (pp. 13-31, with k-nearest neighbours and the three kinds of learning on pp. 28-31), Unit 3 (p. 39), Unit 4 (p. 54), Unit 5 (p. 69). Also the NCERT press release dated 23-10-2026.. Read directly from NCERT''s own site: the module PDF (first edition October 2026, foreword dated August 2026, 108 pages) and the NCERT press release of 23-10-2026, both listed on the NCERT home page. The press release is a scanned image, so the AI reader read it by eye. Two page headers in the PDF carry the words ''NCERT DRAFT'', so a reviewer should ask NCERT whether the posted file is final. The AI reader read the front matter and Unit 2 sections 2.7 and 2.8 closely, and saw only the headings and opening pages of the other units. CBSE Circular Acad-18/2026 says NCERT will supply CT and AI modules for Classes 9 to 12 for internal assessment in 2026-27. The AI reader found no document that names this module in that circular, so linking the two is the AI reader''s inference. AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"NCERT, An Introductory Module on Computational Thinking and Artificial Intelligence for the Secondary Stage (Grades 9-12), First Edition October 2026 (UN514): About the Module (p. v), Note for the Teacher with the 20-hour plan (pp. ix-xi), Unit 1 (p. 1), Unit 2 sections 2.2 and 2.7-2.8 (pp. 13-31, with k-nearest neighbours and the three kinds of learning on pp. 28-31), Unit 3 (p. 39), Unit 4 (p. 54), Unit 5 (p. 69). Also the NCERT press release dated 23-10-2026.","description":"NCERT''s introductory module of 20 class hours serves Classes 9 to 12 together. Its five units cover spotting AI in daily life, how machines learn from examples, how AI goes wrong, protecting personal data, and using AI tools with care. Students tell fixed-rule automation from learning systems, meet supervised, unsupervised and reinforcement learning, train a simple image classifier and try to break it, and learn that recognising a pattern differs from understanding it.","verificationStatus":"primary-source-confirmed","issuingBody":"National Council of Educational Research and Training (NCERT), under the Ministry of Education","mandateType":"curriculum-unit","adoptionDate":"2026-10-23","dateGranularity":"day","statementText":"NCERT''s introductory module of 20 class hours serves Classes 9 to 12 together. Its five units cover spotting AI in daily life, how machines learn from examples, how AI goes wrong, protecting personal data, and using AI tools with care. Students tell fixed-rule automation from learning systems, meet supervised, unsupervised and reinforcement learning, train a simple image classifier and try to break it, and learn that recognising a pattern differs from understanding it.","subject":"computer-science","gradeFrom":9,"gradeTo":12,"topicTags":["artificial-intelligence","machine-learning","ai-ethics","data-privacy","verification","unplugged"]}', '2026-10-23'),
  ('3a3739f7-c943-5e42-90c3-331300ff07e4', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-cbse-computer-science-informatics-practices-classes-11-12-2026-27', 'CBSE, Computer Science (083) and Informatics Practices (065) syllabus for Classes 11 and 12, session 2026-27', '{"id":"IN-MANDATE-cbse-computer-science-informatics-practices-classes-11-12-2026-27","label":"CBSE, Computer Science (083) and Informatics Practices (065) syllabus for Classes 11 and 12, session 2026-27","sourceUrl":"https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Computer_Science_SecP2_2026-27.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CBSE, Computer Science (Subject Code 083), Class XI (2026-27) pp. 1-3 and Class XII (2026-27) pp. 5-7, PDF page numbers; and CBSE, Informatics Practices (Subject Code 065), Class XI (2026-27) pp. 1-2, Unit 4 Introduction to the Emerging Trends on p. 2, and Class XII (2026-27) pp. 5-7 (https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Informatics_Practices_SecP2_2026-27.pdf).. Read directly from the CBSE academic site (2026-27 curriculum page). These are CBSE syllabi. Both name NCERT textbooks as suggested reading, and the AI reader did not read those textbooks or find an NCERT-issued syllabus for these subjects. A secondary source says NCERT plans new Class 10 and 11 books from 2027-28; The AI reader did not confirm that. NCF-SE 2023 sets no learning standards for Classes 11 and 12 (see the separate record). The syllabus PDFs carry no issue date, so the date is given by year only. CBSE Computer Applications (165) for Classes 9 and 10 covers office tools, networking and HTML, and has no link that lines up, so the AI reader wrote no record for it. AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"CBSE, Computer Science (Subject Code 083), Class XI (2026-27) pp. 1-3 and Class XII (2026-27) pp. 5-7, PDF page numbers; and CBSE, Informatics Practices (Subject Code 065), Class XI (2026-27) pp. 1-2, Unit 4 Introduction to the Emerging Trends on p. 2, and Class XII (2026-27) pp. 5-7 (https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Informatics_Practices_SecP2_2026-27.pdf).","description":"CBSE''s Class 11 and 12 Computer Science course teaches Python, flow of control, strings, lists, functions, file handling, stacks, computer networks and SQL. Class 11 adds problem-solving steps with flowcharts and decomposition, number systems and character encodings. Informatics Practices teaches Python, SQL, Pandas and Matplotlib charts, and lists AI and machine learning among emerging trends in Class 11.","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education (CBSE)","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"CBSE''s Class 11 and 12 Computer Science course teaches Python, flow of control, strings, lists, functions, file handling, stacks, computer networks and SQL. Class 11 adds problem-solving steps with flowcharts and decomposition, number systems and character encodings. Informatics Practices teaches Python, SQL, Pandas and Matplotlib charts, and lists AI and machine learning among emerging trends in Class 11.","subject":"computer-science","gradeFrom":11,"gradeTo":12,"topicTags":["python","programming","number-systems","character-encoding","databases","data-visualisation"]}', ''),
  ('00042649-2749-5be2-9e6e-258eabe71e10', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-cbse-ai-417-class-10-and-class-9-ai-course-ended-2026-27', 'CBSE, Class 10 Artificial Intelligence (417) for 2026-27 and the end of the Class 9 AI course (Circular Acad-18/2026)', '{"id":"IN-MANDATE-cbse-ai-417-class-10-and-class-9-ai-course-ended-2026-27","label":"CBSE, Class 10 Artificial Intelligence (417) for 2026-27 and the end of the Class 9 AI course (Circular Acad-18/2026)","sourceUrl":"https://cbseacademic.nic.in/web_material/Circulars/2026/18_Circular_2026.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CBSE Circular Acad-18/2026, 9 April 2026, Students'' and Teachers'' Resource books for CT&AI classes 3rd to 8th (pp. 1-2, paragraph on discontinuing other AI courses for Class IX); CBSE, Artificial Intelligence (Sub. Code 417) Class X, curriculum for session 2026-27, pp. 1-6 of 13 (objectives, scheme of studies, Part B Units 1-3), at https://cbseacademic.nic.in/web_material/Curriculum27/Sec/417-AI-X.pdf.. Read directly: the circular and the Class 10 curriculum PDF. The circular says all other AI courses run until 2025-26 are discontinued for Class IX from 2026-27, and that Class X in 2026-27 continues the 2025-26 scheme. It does not say what replaces the Class 9 course beyond the NCERT modules. The Class 10 course is a skill subject that students opt into. The AI reader tried to read the Class 9 AI (417) syllabus for 2025-26 and the download failed, so the AI reader has not seen it. The AI reader read Units 1 to 3 of Part B and skimmed the other units by title. AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"CBSE Circular Acad-18/2026, 9 April 2026, Students'' and Teachers'' Resource books for CT&AI classes 3rd to 8th (pp. 1-2, paragraph on discontinuing other AI courses for Class IX); CBSE, Artificial Intelligence (Sub. Code 417) Class X, curriculum for session 2026-27, pp. 1-6 of 13 (objectives, scheme of studies, Part B Units 1-3), at https://cbseacademic.nic.in/web_material/Curriculum27/Sec/417-AI-X.pdf.","description":"From 2026-27 CBSE ends its earlier AI courses for Class 9, and Class 10 students keep the 2025-26 scheme. NCERT is to provide computational thinking and AI modules for Classes 9 to 12 for internal assessment. The Class 10 skill subject (210 hours, 100 marks) covers the AI project cycle, rule-based and learning-based models, classification and regression, neural networks, train-test splits, accuracy and F1 score, computer vision, language processing and Python.","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education (CBSE), Department of Skill Education","mandateType":"other","adoptionDate":"2026-04-09","dateGranularity":"day","statementText":"From 2026-27 CBSE ends its earlier AI courses for Class 9, and Class 10 students keep the 2025-26 scheme. NCERT is to provide computational thinking and AI modules for Classes 9 to 12 for internal assessment. The Class 10 skill subject (210 hours, 100 marks) covers the AI project cycle, rule-based and learning-based models, classification and regression, neural networks, train-test splits, accuracy and F1 score, computer vision, language processing and Python.","subject":"computer-science","gradeFrom":9,"gradeTo":10,"topicTags":["artificial-intelligence","machine-learning","model-evaluation","skill-subject","python"]}', '2026-04-09'),
  ('a670efe2-ed27-5952-b5f1-44687ca069cb', 'india-curriculum-repository', 'policy-timeline-event', 'IN', 'openlpm-starter-draft', 'IN-EVENT-moe-ai-and-ct-from-class-3-announced-2025-10-30', 'Ministry of Education announces AI and computational thinking from Class 3 from 2026-27 (PIB, 30 Oct 2025)', '{"id":"IN-EVENT-moe-ai-and-ct-from-class-3-announced-2025-10-30","label":"Ministry of Education announces AI and computational thinking from Class 3 from 2026-27 (PIB, 30 Oct 2025)","sourceUrl":"https://www.pib.gov.in/PressReleasePage.aspx?PRID=2184211","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Press Information Bureau, Ministry of Education, ''Curriculum on AI to be introduced in all schools from Class 3 onwards'', posted 30 Oct 2025 (release ID 2184211), whole release.. Read directly on pib.gov.in. The release gives intent and a timeline, with no syllabus content. The curriculum itself came later: CBSE Circular Acad-15/2026 and the Minister''s launch both date from 1 April 2026 (PIB release 2247963, also read), and the handbooks carry a March 2026 first edition, so the December 2025 target for materials was missed. AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Press Information Bureau, Ministry of Education, ''Curriculum on AI to be introduced in all schools from Class 3 onwards'', posted 30 Oct 2025 (release ID 2184211), whole release.","description":"After a stakeholder meeting on 29 October 2025, the Department said AI and computational thinking will be taught from Class 3 starting in the 2026-27 session, within NCF-SE 2023. CBSE set up an expert committee chaired by Prof. Karthik Raman of IIT Madras. The Department planned resource material and handbooks by December 2025 and teacher training through NISHTHA.","verificationStatus":"primary-source-confirmed","slug":"moe-ai-and-ct-from-class-3-announced-2025-10-30","dateStart":"2025-10-30","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["artificial-intelligence","computational-thinking","announcement","teacher-training"]}', '2025-10-30'),
  ('8b3ad1b9-9e77-5e10-8077-111e90f53e74', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncert-ganita-prakash-grades-6-8-ct-through-puzzles', 'NCERT, Ganita Prakash mathematics textbooks for Classes 6, 7 and 8: computational thinking through puzzles and games', '{"id":"IN-MANDATE-ncert-ganita-prakash-grades-6-8-ct-through-puzzles","label":"NCERT, Ganita Prakash mathematics textbooks for Classes 6, 7 and 8: computational thinking through puzzles and games","sourceUrl":"https://ncert.nic.in/textbook/pdf/fegp1ps.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: NCERT, Ganita Prakash, Grade 6 Part I, Foreword and About the Book (printed pp. iii-vii) and Contents (https://ncert.nic.in/textbook/pdf/fegp1ps.pdf); Grade 7 Part I, About the Book (https://ncert.nic.in/textbook/pdf/gegp1ps.pdf); Grade 8 Part I, About the Book (https://ncert.nic.in/textbook/pdf/hegp1ps.pdf). Grade 7 Part II and Grade 8 Part II prefaces carry the same sentence.. The AI reader read only the front matter of these books (foreword, About the Book, contents). The AI reader did not read any chapter, so whether the books teach algorithms, flowcharts or any programming idea is unchecked, and a web search found no such chapter in Class 7 (secondary-source only). First editions: Class 6 Part I August 2024, Class 7 Part I April 2025, Class 7 Part II October 2025, Class 8 Part I July 2025, Class 8 Part II December 2025. The date field uses the first of these. The Class 3 to 5 books were not read. AI-drafted, and no subject expert has reviewed this record. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"NCERT, Ganita Prakash, Grade 6 Part I, Foreword and About the Book (printed pp. iii-vii) and Contents (https://ncert.nic.in/textbook/pdf/fegp1ps.pdf); Grade 7 Part I, About the Book (https://ncert.nic.in/textbook/pdf/gegp1ps.pdf); Grade 8 Part I, About the Book (https://ncert.nic.in/textbook/pdf/hegp1ps.pdf). Grade 7 Part II and Grade 8 Part II prefaces carry the same sentence.","description":"The new NCERT mathematics books for Classes 6, 7 and 8 say they introduce computational thinking gently, through puzzles, games and interactive exercises. The Class 6 book says its puzzles prepare students for the emerging field of computational thinking and includes a chapter on collecting and presenting data. The Class 7 chapter Number Play covers aspects of computational thinking through parity, Virahanka-Fibonacci numbers and cryptarithms.","verificationStatus":"primary-source-confirmed","issuingBody":"National Council of Educational Research and Training (NCERT)","mandateType":"other","adoptionDate":"2024-08","dateGranularity":"month","statementText":"The new NCERT mathematics books for Classes 6, 7 and 8 say they introduce computational thinking gently, through puzzles, games and interactive exercises. The Class 6 book says its puzzles prepare students for the emerging field of computational thinking and includes a chapter on collecting and presenting data. The Class 7 chapter Number Play covers aspects of computational thinking through parity, Virahanka-Fibonacci numbers and cryptarithms.","subject":"mathematics","gradeFrom":6,"gradeTo":8,"topicTags":["computational-thinking","puzzles","textbook","data-handling"]}', ''),
  ('150b3153-5b08-5f46-a2d6-7a8cc4456da0', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-school-stages-5-3-3-4', 'National Education Policy 2020: new 5+3+3+4 school stages for ages 3 to 18', '{"id":"IN-MANDATE-nep-2020-school-stages-5-3-3-4","label":"National Education Policy 2020: new 5+3+3+4 school stages for ages 3 to 18","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020: Part I figure on the new structure (p. 6); chapter 1, paras 1.1 to 1.6 (pp. 7 to 8); chapter 2, para 2.2 (p. 8); chapter 4, paras 4.1 to 4.3 (pp. 11 to 12).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The PDF is the copy hosted by the Press Information Bureau, because the education.gov.in address returned a 404 error. Page numbers are the printed numbers; the PDF page is one higher. The document prints no date. The 29 July 2020 Cabinet approval comes from news reports, so only the month is given. The models'' bands start at K-2, while India''s Foundational Stage starts at age 3; the three pre-school years have no matching band, which partners may want to comment on. This record gives the structure used for the stage-to-band mapping and has no links, because no model part has matching content. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020: Part I figure on the new structure (p. 6); chapter 1, paras 1.1 to 1.6 (pp. 7 to 8); chapter 2, para 2.2 (p. 8); chapter 4, paras 4.1 to 4.3 (pp. 11 to 12).","description":"NEP 2020 replaces the 10+2 school structure with four stages. Foundational covers ages 3 to 8: three pre-school years plus Classes 1 and 2, taught through play and activity. Preparatory is Classes 3 to 5, with light textbooks. Middle is Classes 6 to 8, with subject teachers. Secondary is Classes 9 to 12, four years of multidisciplinary study. The top priority is that every child reads and does basic arithmetic by Class 3.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (then Ministry of Human Resource Development), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"NEP 2020 replaces the 10+2 school structure with four stages. Foundational covers ages 3 to 8: three pre-school years plus Classes 1 and 2, taught through play and activity. Preparatory is Classes 3 to 5, with light textbooks. Middle is Classes 6 to 8, with subject teachers. Secondary is Classes 9 to 12, four years of multidisciplinary study. The top priority is that every child reads and does basic arithmetic by Class 3.","subject":"general","topicTags":["5+3+3+4","school stages","early childhood care and education","foundational literacy and numeracy","play-based learning"]}', ''),
  ('8b49dac9-b084-58c6-85bf-66a93aece275', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-multidisciplinary-experiential-competency-based-learning', 'National Education Policy 2020: multidisciplinary, experiential and competency-based school learning', '{"id":"IN-MANDATE-nep-2020-multidisciplinary-experiential-competency-based-learning","label":"National Education Policy 2020: multidisciplinary, experiential and competency-based school learning","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020: Introduction (p. 3); guiding principles (pp. 5 to 6); chapter 4, paras 4.4 to 4.10 (pp. 12 to 13) and 4.23 to 4.25 (p. 15).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The PDF is the copy hosted by the Press Information Bureau, because the education.gov.in address returned a 404 error. Page numbers are the printed numbers; the PDF page is one higher. For schools the policy mostly says multidisciplinary and ''explorations of relations among different subjects''. The word interdisciplinary appears for higher education (para 11.6, p. 37). The coding sentence is para 4.25 (coding activities introduced in the Middle Stage, with computational thinking and puzzle games from the Foundational Stage); it is the basis of the contrast link to the Computational-Core Class 3 to 5 part. The AI reader did not check where NCF-SE 2023 places coding. The policy gives aims only; subject-level targets come from NCF-SE 2023. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020: Introduction (p. 3); guiding principles (pp. 5 to 6); chapter 4, paras 4.4 to 4.10 (pp. 12 to 13) and 4.23 to 4.25 (p. 15).","description":"NEP 2020 asks schools to trim each subject to its core ideas and make room for critical thinking, inquiry and discussion. Learning should be experiential inside each subject, with attention to how subjects relate, and should move toward competencies. It calls for no hard separation between arts, sciences and vocational streams, more subject choice at the Secondary Stage, and coding activities from the Middle Stage.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (then Ministry of Human Resource Development), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"NEP 2020 asks schools to trim each subject to its core ideas and make room for critical thinking, inquiry and discussion. Learning should be experiential inside each subject, with attention to how subjects relate, and should move toward competencies. It calls for no hard separation between arts, sciences and vocational streams, more subject choice at the Secondary Stage, and coding activities from the Middle Stage.","subject":"general","topicTags":["multidisciplinary","experiential learning","competency-based learning","critical thinking","subject choice","computational thinking"]}', ''),
  ('d617ad22-b225-543d-8e4a-1c83fd84764b', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-school-assessment-reform', 'National Education Policy 2020: school assessment to become formative and competency-based', '{"id":"IN-MANDATE-nep-2020-school-assessment-reform","label":"National Education Policy 2020: school assessment to become formative and competency-based","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020: chapter 4, paras 4.34 to 4.42 (pp. 17 to 19).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The PDF is the copy hosted by the Press Information Bureau, because the education.gov.in address returned a 404 error. Page numbers are the printed numbers; the PDF page is one higher. NCF-SE 2023 repeats and extends these points in Part A section 3.4 (pp. 97 to 111), including holistic progress cards (p. 105) and no detention in Classes 1 to 8 (p. 105). The AI reader did not check whether PARAKH was set up as the policy describes. The models describe what students should be able to do. They say nothing about how to assess it, so this record has no links. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020: chapter 4, paras 4.34 to 4.42 (pp. 17 to 19).","description":"NEP 2020 wants school assessment to become regular, formative and competency-based, testing analysis, critical thinking and conceptual clarity. Report cards become a fuller profile that includes self, peer and project assessment. Board exams for Classes 10 and 12 continue but test core competencies, and students may sit them twice in a year. All students take school exams in Classes 3, 5 and 8. A new national centre, PARAKH, is to set assessment norms.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (then Ministry of Human Resource Development), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"NEP 2020 wants school assessment to become regular, formative and competency-based, testing analysis, critical thinking and conceptual clarity. Report cards become a fuller profile that includes self, peer and project assessment. Board exams for Classes 10 and 12 continue but test core competencies, and students may sit them twice in a year. All students take school exams in Classes 3, 5 and 8. A new national centre, PARAKH, is to set assessment norms.","subject":"general","topicTags":["assessment","formative assessment","board examinations","holistic progress card","PARAKH"]}', ''),
  ('e14df0fa-8300-5b50-b0bb-e89bb9e15362', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-teachers-and-teacher-education', 'National Education Policy 2020: teachers, teacher education and the planned NCFTE 2021', '{"id":"IN-MANDATE-nep-2020-teachers-and-teacher-education","label":"National Education Policy 2020: teachers, teacher education and the planned NCFTE 2021","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020: chapter 5, paras 5.15 (p. 22), 5.20 (pp. 22 to 23), 5.22 to 5.24 (p. 23) and 5.28 (p. 24); chapter 15, paras 15.1 to 15.5 (pp. 42 to 43).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The PDF is the copy hosted by the Press Information Bureau, because the education.gov.in address returned a 404 error. Page numbers are the printed numbers; the PDF page is one higher. Included for the teacher-educator partners. The AI reader could not read NCFTE 2021 itself: ncte.gov.in returned a 403 error from the AI reader''s network and the AI reader found no copy elsewhere or any confirmation that a final document was published. NCF-SE 2023 (Foreword, pp. iii to iv, and Summary para 1.8.3, p. 28) says the teacher education framework would follow shortly, and Part E section 3.6 (p. 533) says the four-year programme will be detailed in it. Part E chapter 3 (pp. 529 to 534) also covers teacher autonomy and in-service training. Partners should say which teacher education framework their programmes follow today. No links: the models describe student learning. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020: chapter 5, paras 5.15 (p. 22), 5.20 (pp. 22 to 23), 5.22 to 5.24 (p. 23) and 5.28 (p. 24); chapter 15, paras 15.1 to 15.5 (pp. 42 to 43).","description":"NEP 2020 expects every teacher to do at least 50 hours of professional development a year, covering competency-based learning, experiential and arts-integrated methods, and formative assessment. By 2030 the minimum teaching degree becomes a four-year integrated B.Ed. offered inside multidisciplinary institutions. NCTE, with NCERT, was to produce a new teacher education framework (NCFTE 2021) and national professional standards for teachers.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (then Ministry of Human Resource Development), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"NEP 2020 expects every teacher to do at least 50 hours of professional development a year, covering competency-based learning, experiential and arts-integrated methods, and formative assessment. By 2030 the minimum teaching degree becomes a four-year integrated B.Ed. offered inside multidisciplinary institutions. NCTE, with NCERT, was to produce a new teacher education framework (NCFTE 2021) and national professional standards for teachers.","subject":"general","topicTags":["teacher education","professional development","integrated B.Ed.","NCFTE","teacher standards"]}', ''),
  ('6b3f7f67-7f7a-5bf9-a63b-9f17137cae35', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-multidisciplinary-higher-education', 'National Education Policy 2020: multidisciplinary universities and undergraduate education', '{"id":"IN-MANDATE-nep-2020-multidisciplinary-higher-education","label":"National Education Policy 2020: multidisciplinary universities and undergraduate education","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020: chapter 9, paras 9.2 to 9.3 (pp. 33 to 34); chapter 10, paras 10.1 and 10.14 (pp. 34 and 36); chapter 11, paras 11.1 to 11.9 (pp. 36 to 38); chapter 12, para 12.2 (p. 38).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The PDF is the copy hosted by the Press Information Bureau, because the education.gov.in address returned a 404 error. Page numbers are the printed numbers; the PDF page is one higher. Included for the CHRIST partners and kept to one record. CHRIST''s own public note dated 3 January 2023 says it follows the UGC undergraduate curriculum and credit framework dated 12 December 2022 from the 2023-24 year. The AI reader could not open the UGC document itself (ugc.gov.in was unreachable), so there is no separate record for it. This is higher-education policy, so the record has no links to the school-level models. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020: chapter 9, paras 9.2 to 9.3 (pp. 33 to 34); chapter 10, paras 10.1 and 10.14 (pp. 34 and 36); chapter 11, paras 11.1 to 11.9 (pp. 36 to 38); chapter 12, para 12.2 (p. 38).","description":"NEP 2020 wants higher education to move to large multidisciplinary universities and colleges with flexible programmes that let students combine disciplines. Undergraduate degrees run three or four years with exit points, and the four-year route is preferred. An Academic Bank of Credit stores credits. Courses in community service, environment and values are to carry credit. The label ''deemed to be university'' is to give way to plain ''university''.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education (then Ministry of Human Resource Development), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"NEP 2020 wants higher education to move to large multidisciplinary universities and colleges with flexible programmes that let students combine disciplines. Undergraduate degrees run three or four years with exit points, and the four-year route is preferred. An Academic Bank of Credit stores credits. Courses in community service, environment and values are to carry credit. The label ''deemed to be university'' is to give way to plain ''university''.","subject":"general","topicTags":["higher education","multidisciplinary","four-year undergraduate degree","academic bank of credit","deemed university"]}', ''),
  ('b0c2bdcf-4aac-5e85-b52f-65d034dcb978', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-aims-curricular-areas-and-learning-standards', 'National Curriculum Framework for School Education 2023: aims, curricular areas and learning standards', '{"id":"IN-MANDATE-ncf-se-2023-aims-curricular-areas-and-learning-standards","label":"National Curriculum Framework for School Education 2023: aims, curricular areas and learning standards","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023: Summary, sections 1.2 to 1.4 (pp. 9 to 18); Part A chapter 1, sections 1.1 to 1.4 (pp. 31 to 46; forms of knowledge pp. 38 to 42; curricular areas pp. 43 to 46); Part A chapter 3, section 3.1 (pp. 71 to 75) and section 3.4 on assessment (pp. 97 to 111).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. Page numbers are the printed numbers in the NCERT first-edition PDF (printed October 2024); the PDF page is 14 higher. The document says Grades where Indian usage is Class. The foreword is dated 29 July 2023. Press coverage and a Ministry press-release copy that the AI reader found through search give 23 August 2023 as the release date; The AI reader did not open that release in full, so the month is the safe date. The AI reader read the Summary, Part A chapters 1 and 2 and sections 3.1 and 3.4 of chapter 3, and Part C chapter 7. The AI reader did not read sections 3.2 and 3.3 or the subject chapters, which other records cover. The text counts eight curricular areas (pp. 44 to 45) but also says seven areas along with interdisciplinary areas (p. 11); that is the same set. The framework lists knowing through analogy and comparison (Upamana) as one accepted way of knowing in Indian thought (p. 41) and asks how people search for and build knowledge (p. 38); this is the basis of the single link. Assessment points in section 3.4: competency-based, three purposes (of, for and as learning), holistic progress cards (p. 105), no detention in Classes 1 to 8, and external exams in Classes 3, 5 and 8 (pp. 105 to 106). A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023: Summary, sections 1.2 to 1.4 (pp. 9 to 18); Part A chapter 1, sections 1.1 to 1.4 (pp. 31 to 46; forms of knowledge pp. 38 to 42; curricular areas pp. 43 to 46); Part A chapter 3, section 3.1 (pp. 71 to 75) and section 3.4 on assessment (pp. 97 to 111).","description":"NCF-SE 2023 sets five aims for schooling: rational thought and independence, health and well-being, and democratic, economic and cultural participation. School knowledge is grouped into eight curricular areas, one of them interdisciplinary areas. Learning standards run from aims to stage-level goals, to competencies, to small learning outcomes that curriculum developers and teachers define. End-of-stage assessment is to rest on the competencies, which are illustrative and may be adapted by curriculum developers.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education, Government of India (National Steering Committee for National Curriculum Frameworks; published by NCERT)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"NCF-SE 2023 sets five aims for schooling: rational thought and independence, health and well-being, and democratic, economic and cultural participation. School knowledge is grouped into eight curricular areas, one of them interdisciplinary areas. Learning standards run from aims to stage-level goals, to competencies, to small learning outcomes that curriculum developers and teachers define. End-of-stage assessment is to rest on the competencies, which are illustrative and may be adapted by curriculum developers.","subject":"general","topicTags":["aims of education","curricular areas","competencies","learning outcomes","learning standards","assessment"]}', ''),
  ('39e12627-9896-5d9c-892b-e7c26240a5e5', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-four-stage-design', 'National Curriculum Framework for School Education 2023: design of the four school stages', '{"id":"IN-MANDATE-ncf-se-2023-four-stage-design","label":"National Curriculum Framework for School Education 2023: design of the four school stages","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023: Summary, section 1.4 (pp. 13 to 18); Part A chapter 2 (pp. 47 to 62), including perceptual, practical and theoretical concepts (pp. 55 to 56) and stage design (pp. 58 to 62); Part A chapter 3, section 3.2.1 on content selection (p. 76) and section 3.4.9 on assessment by stage (pp. 103 to 104).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. Page numbers are the printed numbers in the NCERT first-edition PDF (printed October 2024); the PDF page is 14 higher. The document says Grades where Indian usage is Class. Key progression claim for the link: the framework describes the concepts children form in the first two stages as mostly perceptual (seen or sensed) and practical (tied to use), and expects the theory behind them to be explored in the Middle and Secondary Stages (pp. 55 to 56 and 76). The AI reader read the Secondary Stage only to the start of section 2.3.4.2 (p. 62) and the Summary (pp. 16 to 18). Foundational and Preparatory teachers are generalists (pp. 59 to 60); Middle Stage teachers are subject-specific (p. 61). A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023: Summary, section 1.4 (pp. 13 to 18); Part A chapter 2 (pp. 47 to 62), including perceptual, practical and theoretical concepts (pp. 55 to 56) and stage design (pp. 58 to 62); Part A chapter 3, section 3.2.1 on content selection (p. 76) and section 3.4.9 on assessment by stage (pp. 103 to 104).","description":"NCF-SE 2023 describes how each stage should look. Foundational (ages 3 to 8) is play-based, organised by developmental domains and assessed mainly by observation. Preparatory (Classes 3 to 5) adds textbooks and a combined subject, The World Around Us. Middle (Classes 6 to 8) brings subject teachers and the methods of inquiry of each subject. Secondary (Classes 9 to 12) widens subject choice. Theoretical concepts are expected from Class 6 onward.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education, Government of India (National Steering Committee for National Curriculum Frameworks; published by NCERT)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"NCF-SE 2023 describes how each stage should look. Foundational (ages 3 to 8) is play-based, organised by developmental domains and assessed mainly by observation. Preparatory (Classes 3 to 5) adds textbooks and a combined subject, The World Around Us. Middle (Classes 6 to 8) brings subject teachers and the methods of inquiry of each subject. Secondary (Classes 9 to 12) widens subject choice. Theoretical concepts are expected from Class 6 onward.","subject":"general","topicTags":["foundational stage","preparatory stage","middle stage","secondary stage","pedagogy by stage","assessment by stage"]}', ''),
  ('d1a852be-b4f0-51e0-a389-ac65b9d1e985', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-interdisciplinary-areas', 'National Curriculum Framework for School Education 2023: education in interdisciplinary areas', '{"id":"IN-MANDATE-ncf-se-2023-interdisciplinary-areas","label":"National Curriculum Framework for School Education 2023: education in interdisciplinary areas","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023: Part C chapter 7, Education in Interdisciplinary Areas (pp. 364 to 393): stage overview (pp. 364 to 365), aims (pp. 365 to 366), nature of knowledge (pp. 366 to 367), The World Around Us (pp. 367 to 374; goals and competencies pp. 368 to 370), Individuals in Society (from p. 375), Environmental Education (from p. 384), teacher preparation (pp. 392 to 393).. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. Page numbers are the printed numbers in the NCERT first-edition PDF (printed October 2024); the PDF page is 14 higher. The document says Grades where Indian usage is Class. Facts used by the links. The World Around Us has seven curricular goals. Competencies ask pupils to describe cultural diversity in their surroundings such as food, clothing and festivals (C-4.2, p. 369), connect changes in family and community life to elders'' stories about work and food (C-2.3, p. 369), and explain how local institutions such as school, market and Panchayat work and what roles they play (C-1.4, p. 368). Content is to widen from the local context through comparison and analogy across communities (p. 371). Class 10 Environmental Education asks pupils to describe the place of humans within ecosystems (C-2.1, p. 385). Its content lists conflicts such as sharing river waters and benefits for privileged versus vulnerable groups (p. 386). Class 9 Individuals in Society pedagogy asks pupils to reflect on how they chose a view (p. 379). The chapter names teacher preparation as the main risk (p. 367) and suggests a Social Science teacher for Individuals in Society and a Science teacher for Environmental Education (p. 392). The AI reader read these pages; The AI reader did not read every assessment example. The AI reader did not check which boards have started teaching these subjects. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023: Part C chapter 7, Education in Interdisciplinary Areas (pp. 364 to 393): stage overview (pp. 364 to 365), aims (pp. 365 to 366), nature of knowledge (pp. 366 to 367), The World Around Us (pp. 367 to 374; goals and competencies pp. 368 to 370), Individuals in Society (from p. 375), Environmental Education (from p. 384), teacher preparation (pp. 392 to 393).","description":"NCF-SE 2023 treats interdisciplinary learning stage by stage. Foundational goals follow developmental domains, so are interdisciplinary by design. Classes 3 to 5 study one combined subject, The World Around Us, on nature, society, local institutions and simple inquiry. In Classes 6 to 8 interdisciplinary goals sit inside the curricular areas themselves, with no separate area. Class 9 adds Individuals in Society (ethical reasoning on current issues) and Class 10 Environmental Education. Classes 11 and 12 offer electives.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education, Government of India (National Steering Committee for National Curriculum Frameworks; published by NCERT)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"NCF-SE 2023 treats interdisciplinary learning stage by stage. Foundational goals follow developmental domains, so are interdisciplinary by design. Classes 3 to 5 study one combined subject, The World Around Us, on nature, society, local institutions and simple inquiry. In Classes 6 to 8 interdisciplinary goals sit inside the curricular areas themselves, with no separate area. Class 9 adds Individuals in Society (ethical reasoning on current issues) and Class 10 Environmental Education. Classes 11 and 12 offer electives.","subject":"interdisciplinary","topicTags":["interdisciplinary","The World Around Us","environmental education","individuals in society","ethical reasoning"]}', ''),
  ('ab3e36d1-a051-5736-bc86-1e09b96a1705', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning', 'National Curriculum Framework for Foundational Stage 2022: play-based learning for ages 3 to 8', '{"id":"IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning","label":"National Curriculum Framework for Foundational Stage 2022: play-based learning for ages 3 to 8","sourceUrl":"https://ncert.nic.in/pdf/NCF_for_Foundational_Stage_20_October_2022.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for Foundational Stage 2022: guiding principles, para 1.3.4 (pp. 35 to 36); how children learn, section 1.4 (pp. 38 to 40); curricular goals, section 2.3 (p. 56); competencies, section 2.4 (pp. 59 to 61); ways of organising content, section 5.3 (pp. 144 to 149); assessment, sections 6.1 and 6.2 (pp. 171 to 174); links to the Preparatory Stage, chapter 9 (pp. 203 to 206). Page numbers match the printed numbers.. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The foreword is dated 20 October 2022, and NCF-SE 2023 gives that as the release date. The grade fields mark the Class 1 and 2 part; the three pre-school years have no model band. Facts used by the links: principle h (p. 35) says new content should start from experiences children already know; the play examples on p. 39 include retrying a block tower with a wider base and starting a picture puzzle from its border pieces; competency C-8.1 has children sort objects by more than one property into groups and sub-groups, and C-7.2 has them form simple hypotheses about cause and effect; C-4.1 starts to see self as belonging to a family and community, C-4.4 shows cooperative behaviour and C-4.5 responds to norms in the classroom and school (pp. 60 to 61); the observation example on p. 173 is a child sharing toys and taking turns; C-7.3 uses simple tools and technology in daily life (p. 61). Chapter 9 says the Preparatory Stage turns the domains into curricular areas including The World Around Us (p. 205). The AI reader did not read the language chapter, the pedagogy chapter (chapter 4), or the annexures of learning outcomes and NIPUN Bharat mapping. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for Foundational Stage 2022: guiding principles, para 1.3.4 (pp. 35 to 36); how children learn, section 1.4 (pp. 38 to 40); curricular goals, section 2.3 (p. 56); competencies, section 2.4 (pp. 59 to 61); ways of organising content, section 5.3 (pp. 144 to 149); assessment, sections 6.1 and 6.2 (pp. 171 to 174); links to the Preparatory Stage, chapter 9 (pp. 203 to 206). Page numbers match the printed numbers.","description":"NCF-FS 2022 covers ages 3 to 8, from pre-school to Class 2. Play is the main way of learning, with caring teachers and concrete materials. Thirteen curricular goals follow five domains of development plus learning habits. Competencies include sorting objects by more than one property, cooperating with peers, following classroom norms and forming simple guesses about cause and effect in nature. Assessment is by observation and children''s work. Explicit tests are ruled out.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Education, Government of India (National Steering Committee for National Curriculum Frameworks; hosted by NCERT)","mandateType":"curriculum-framework","adoptionDate":"2022-10-20","dateGranularity":"day","statementText":"NCF-FS 2022 covers ages 3 to 8, from pre-school to Class 2. Play is the main way of learning, with caring teachers and concrete materials. Thirteen curricular goals follow five domains of development plus learning habits. Competencies include sorting objects by more than one property, cooperating with peers, following classroom norms and forming simple guesses about cause and effect in nature. Assessment is by observation and children''s work. Explicit tests are ruled out.","subject":"general","gradeFrom":1,"gradeTo":2,"topicTags":["foundational stage","play-based learning","early childhood","curricular goals","observation-based assessment"]}', '2022-10-20'),
  ('18135f00-d5da-5337-833a-c11af7f48469', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncrf-2023-national-credit-framework', 'National Credit Framework 2023: one credit system for school, vocational and higher learning', '{"id":"IN-MANDATE-ncrf-2023-national-credit-framework","label":"National Credit Framework 2023: one credit system for school, vocational and higher learning","sourceUrl":"https://psscive.ac.in/storage/uploads/documents/1723225781_SOPs%20for%20implementation%20of%20NCrF%20Final.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Credit Framework (report of the High-Level Committee, April 2023), as reproduced in the UGC volume ''SOPs for Operationalization of NCrF'' (August 2024): executive summary (printed pp. 11 to 14), basic principles section 3.2.2 (pp. 31 to 33), learning hours sections 3.2.4 and 3.2.5 (pp. 35 to 38). School guidelines are in the school education SOP part of the same volume (printed pp. 70 to 80). The volume numbers each part separately; the numbers are those printed on the pages.. AI-drafted from a direct reading of the PDF; no subject expert has reviewed this record. The AI reader read the NCrF text as reproduced inside a UGC publication (August 2024) hosted by PSSCIVE, an NCERT institute. The UGC and education.gov.in copies of the standalone report could not be fetched. The UGC volume says the Government approved the framework and UGC notified it on 10 April 2023 (p. 5 of the volume). The school guidelines in the same volume are a CBSE document that pilots credits in Classes 6, 9 and 11 from 2024-25 (pp. 77 to 78); that is CBSE practice, so the state boards may differ. School credit levels run up to level 4 (p. 13). The framework counts any assessed learning toward hours and makes no change to what is taught, so the record has no links to the models. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Credit Framework (report of the High-Level Committee, April 2023), as reproduced in the UGC volume ''SOPs for Operationalization of NCrF'' (August 2024): executive summary (printed pp. 11 to 14), basic principles section 3.2.2 (pp. 31 to 33), learning hours sections 3.2.4 and 3.2.5 (pp. 35 to 38). School guidelines are in the school education SOP part of the same volume (printed pp. 70 to 80). The volume numbers each part separately; the numbers are those printed on the pages.","description":"The NCrF gives one credit system for school, higher and vocational learning. A year of learning is 1,200 notional hours worth 40 credits, with fewer hours in the early years (800 for the Foundational Stage and 1,000 for Classes 3 to 5). Credits are assigned only after assessment and do not depend on subject or stream. Project work, field visits, community work, sports, arts and bagless days can all count toward the hours.","verificationStatus":"primary-source-confirmed","issuingBody":"High-Level Committee on the National Credit Framework (Ministry of Skill Development and Entrepreneurship, with Ministry of Education, UGC, NCVET, NIOS, CBSE and NCERT); notified by UGC","mandateType":"other","adoptionDate":"2023-04-10","dateGranularity":"day","statementText":"The NCrF gives one credit system for school, higher and vocational learning. A year of learning is 1,200 notional hours worth 40 credits, with fewer hours in the early years (800 for the Foundational Stage and 1,000 for Classes 3 to 5). Credits are assigned only after assessment and do not depend on subject or stream. Project work, field visits, community work, sports, arts and bagless days can all count toward the hours.","subject":"general","topicTags":["credit framework","notional learning hours","academic bank of credit","experiential learning","no hard separation"]}', '2023-04-10'),
  ('cd3983ac-e708-5eb6-b998-c52177a574df', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-science-aims-and-inquiry', 'NCF-SE 2023 (NCERT), Science Education: aims, nature of knowledge and teaching for inquiry', '{"id":"IN-MANDATE-ncf-se-2023-science-aims-and-inquiry","label":"NCF-SE 2023 (NCERT), Science Education: aims, nature of knowledge and teaching for inquiry","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 4 ''Science Education'': Section 4.1 Aims (printed pp. 275-276), Section 4.2 Nature of Knowledge (pp. 276-277), Section 4.6 Pedagogic Principles (pp. 289-290). PDF pages 289-291 and 303-304.. AI-drafted from the primary PDF and not reviewed by a subject expert. A second AI reader re-checked the cited pages (printed pp. 275-277 and 289-290). All of Part C Chapter 4 was read up to the start of Section 4.6, then the pedagogic principles on printed p. 290. The assessment guidance was not read. PDF page = printed page + 14. The chapter says Science is a separate subject only from Class 6, and that Classes 11 and 12 are covered in Part C Chapter 10 (see the Biology record). Release date: the Ministry of Education press release dated 23 August 2023 (Press Information Bureau, release id 1951485) says the Minister released the framework that day, which supports the month 2023-08. NCERT''s own pages and the PDF give no release date. The PDF front matter says First Edition October 2024, and the foreword dated 29 July 2023 is the date the steering committee handed the framework to the Minister. NCERT''s home page now also links a May 2026 re-issue (NCFSE2023_May2026.pdf) with the same text on every page cited here. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 4 ''Science Education'': Section 4.1 Aims (printed pp. 275-276), Section 4.2 Nature of Knowledge (pp. 276-277), Section 4.6 Pedagogic Principles (pp. 289-290). PDF pages 289-291 and 303-304.","description":"The framework sets seven aims for school science, among them the ability to form and test hypotheses, scientific temper, and understanding how scientific knowledge developed over time. It adds that scientific knowledge can change when new evidence arrives. It calls science a creative activity and uses natural selection as one example of a creative idea. It asks teachers to let pupils go through the whole cycle of inquiry, from questions and hypotheses to testing, data and revised conclusions.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (framework prepared by the National Steering Committee for National Curriculum Frameworks, submitted to the Minister of Education)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"The framework sets seven aims for school science, among them the ability to form and test hypotheses, scientific temper, and understanding how scientific knowledge developed over time. It adds that scientific knowledge can change when new evidence arrives. It calls science a creative activity and uses natural selection as one example of a creative idea. It asks teachers to let pupils go through the whole cycle of inquiry, from questions and hypotheses to testing, data and revised conclusions.","subject":"science","gradeFrom":6,"gradeTo":10,"topicTags":["scientific temper","inquiry","testing hypotheses","evidence","nature of science","natural selection"]}', ''),
  ('aa640607-aac0-5eff-b8de-79b40c80fccf', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-science-preparatory-world-around-us', 'NCF-SE 2023 (NCERT), The World Around Us for Classes 3 to 5: goals on the natural world and simple inquiry', '{"id":"IN-MANDATE-ncf-se-2023-science-preparatory-world-around-us","label":"NCF-SE 2023 (NCERT), The World Around Us for Classes 3 to 5: goals on the natural world and simple inquiry","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 7 ''Education in Interdisciplinary Areas'', Section 7.4 Preparatory Stage: The World Around Us, 7.4.2.1 Curricular Goals and Competencies (CG-4 C-4.1 and C-4.5, CG-6 C-6.1, CG-7 C-7.1 and C-7.2), printed pp. 368-370; content principle 7.4.3.1(a), printed p. 370. PDF pages 382-384.. AI-drafted from the primary PDF and not reviewed by a subject expert. A second AI reader checked the competency codes against the page images of printed pp. 369-370: C-4.1, C-4.5, C-6.1, C-7.1 and C-7.2 are as stated. Science at this stage sits inside The World Around Us, which also covers social science, so the subject is given as general. Competency C-1.5 mentions a family tree only as a craft object. The whole goals table (CG-1 to CG-7) and the content principles were read, and a keyword search of PDF pages 380 to 389 found no inheritance, heredity, evolution, adaptation or variation content. The pedagogy and assessment part (Section 7.4.4) was not read. Release date: the Ministry of Education press release dated 23 August 2023 (Press Information Bureau, release id 1951485) says the Minister released the framework that day, which supports the month 2023-08. NCERT''s own pages and the PDF give no release date. The PDF front matter says First Edition October 2024, and the foreword dated 29 July 2023 is the date the steering committee handed the framework to the Minister. NCERT''s home page now also links a May 2026 re-issue (NCFSE2023_May2026.pdf) with the same text on every page cited here. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 7 ''Education in Interdisciplinary Areas'', Section 7.4 Preparatory Stage: The World Around Us, 7.4.2.1 Curricular Goals and Competencies (CG-4 C-4.1 and C-4.5, CG-6 C-6.1, CG-7 C-7.1 and C-7.2), printed pp. 368-370; content principle 7.4.3.1(a), printed p. 370. PDF pages 382-384.","description":"In Classes 3 to 5, science ideas are taught inside an interdisciplinary area called The World Around Us, whose goals ask pupils to observe and describe the diversity of plants, birds and animals nearby, to run simple inquiries, and to become familiar with the scientific method. The content advice suggests having pupils observe and record how seeds grow in different soils and amounts of sunlight. The goals name no inheritance or evolution content.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (framework prepared by the National Steering Committee for National Curriculum Frameworks, submitted to the Minister of Education)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"In Classes 3 to 5, science ideas are taught inside an interdisciplinary area called The World Around Us, whose goals ask pupils to observe and describe the diversity of plants, birds and animals nearby, to run simple inquiries, and to become familiar with the scientific method. The content advice suggests having pupils observe and record how seeds grow in different soils and amounts of sunlight. The goals name no inheritance or evolution content.","subject":"general","gradeFrom":3,"gradeTo":5,"topicTags":["preparatory stage","diversity of life","simple inquiry","scientific method","interdisciplinary"]}', ''),
  ('8e651343-0104-5ac9-be55-f35111ee681d', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-science-middle-stage-goals', 'NCF-SE 2023 (NCERT), Science for the Middle Stage (Classes 6 to 8): goals on the living world and the nature of science', '{"id":"IN-MANDATE-ncf-se-2023-science-middle-stage-goals","label":"NCF-SE 2023 (NCERT), Science for the Middle Stage (Classes 6 to 8): goals on the living world and the nature of science","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 4 ''Science Education'', 4.4.1.1 Middle Stage: CG-3 (C-3.1 to C-3.4), printed p. 279; CG-6 and CG-9 (C-6.1, C-6.2, C-9.1, C-9.2), printed p. 280; 4.4.2.1 essential concepts, printed p. 284. PDF pages 293-294 and 298.. AI-drafted from the primary PDF and not reviewed by a subject expert. A second AI reader checked the Middle Stage competency table against the page images of printed pp. 279-280: C-3.1 to C-3.4 (CG-3), C-6.1 and C-6.2 (CG-6) and C-9.1 and C-9.2 (CG-9) are as stated. The Middle Stage goals table and the Middle Stage essential-concepts paragraph (printed p. 284) were read. None of them names heredity, variation, natural selection or evolution, and the links that contrast the models with India rest on that absence. The Class 8 textbook does teach genes and variation (see the Class 8 record), so the textbooks go further than the competency wording. If a separate Middle Stage syllabus document exists, please check it. Release date: the Ministry of Education press release dated 23 August 2023 (Press Information Bureau, release id 1951485) says the Minister released the framework that day, which supports the month 2023-08. NCERT''s own pages and the PDF give no release date. The PDF front matter says First Edition October 2024, and the foreword dated 29 July 2023 is the date the steering committee handed the framework to the Minister. NCERT''s home page now also links a May 2026 re-issue (NCFSE2023_May2026.pdf) with the same text on every page cited here. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 4 ''Science Education'', 4.4.1.1 Middle Stage: CG-3 (C-3.1 to C-3.4), printed p. 279; CG-6 and CG-9 (C-6.1, C-6.2, C-9.1, C-9.2), printed p. 280; 4.4.2.1 essential concepts, printed p. 284. PDF pages 293-294 and 298.","description":"For Classes 6 to 8, science is one integrated subject, and the living-world goal asks pupils to describe the diversity of living things, tell living from non-living things, and analyse how organisms and their surroundings depend on each other. Other goals ask pupils to show how scientific ideas changed over time and to collect data as evidence. The competencies name no heredity, variation or evolution.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (framework prepared by the National Steering Committee for National Curriculum Frameworks, submitted to the Minister of Education)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"For Classes 6 to 8, science is one integrated subject, and the living-world goal asks pupils to describe the diversity of living things, tell living from non-living things, and analyse how organisms and their surroundings depend on each other. Other goals ask pupils to show how scientific ideas changed over time and to collect data as evidence. The competencies name no heredity, variation or evolution.","subject":"science","gradeFrom":6,"gradeTo":8,"topicTags":["middle stage","diversity of life","living world","nature of science","evidence"]}', ''),
  ('b3d5f817-36be-543b-9705-c19dbc4fdfcb', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-science-secondary-stage-grades-9-10-goals', 'NCF-SE 2023 (NCERT), Science for Classes 9 and 10: goals on heredity, inheritance and evolution', '{"id":"IN-MANDATE-ncf-se-2023-science-secondary-stage-grades-9-10-goals","label":"NCF-SE 2023 (NCERT), Science for Classes 9 and 10: goals on heredity, inheritance and evolution","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 4 ''Science Education'', 4.4.1.2 Secondary Stage: CG-3 C-3.3 and CG-4 C-4.1, C-4.4, C-4.5 (printed p. 282); CG-8 C-8.1 and C-8.2 (p. 283); 4.4.2.2 essential concepts (pp. 284-285); 4.5 content principle (i) (p. 288). PDF pages 296-299 and 302.. AI-drafted from the primary PDF and not reviewed by a subject expert. A second AI reader checked the page image of printed p. 282: C-3.3 (heredity and variation) sits under CG-3, and C-4.1, C-4.4 and C-4.5 sit under CG-4, whose title is about the interconnection of organisms and their environment. C-8.1 and C-8.2 (CG-8, printed p. 283) were read in the extracted text. Partners may still want to confirm the grouping of Mendel and evolution under CG-4. The CBSE Class 10 syllabus for 2026-27 copies the same competency text (PDF p. 3). Section 4.5 principle (i), printed p. 288, adds that teaching heredity, evolution and biodiversity can show how evidence overturned ideas of human superiority and of ''races''. Section 4.4.2.2 (printed p. 285) names Mendel''s laws, natural selection and evolution as the kind of generalisation pupils should reach at this stage. Release date: the Ministry of Education press release dated 23 August 2023 (Press Information Bureau, release id 1951485) says the Minister released the framework that day, which supports the month 2023-08. NCERT''s own pages and the PDF give no release date. The PDF front matter says First Edition October 2024, and the foreword dated 29 July 2023 is the date the steering committee handed the framework to the Minister. NCERT''s home page now also links a May 2026 re-issue (NCFSE2023_May2026.pdf) with the same text on every page cited here. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 4 ''Science Education'', 4.4.1.2 Secondary Stage: CG-3 C-3.3 and CG-4 C-4.1, C-4.4, C-4.5 (printed p. 282); CG-8 C-8.1 and C-8.2 (p. 283); 4.4.2.2 essential concepts (pp. 284-285); 4.5 content principle (i) (p. 288). PDF pages 296-299 and 302.","description":"For Classes 9 and 10, the framework asks pupils to describe heredity through DNA, genes and chromosomes, with variation as changes in DNA sequence. It asks them to analyse inheritance with Mendel''s laws and its effects on populations, and to analyse evidence for biological evolution by natural selection, seen in allele frequency and in organisms'' structure and function. A further goal asks pupils to plan and carry out scientific inquiries.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (framework prepared by the National Steering Committee for National Curriculum Frameworks, submitted to the Minister of Education)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"For Classes 9 and 10, the framework asks pupils to describe heredity through DNA, genes and chromosomes, with variation as changes in DNA sequence. It asks them to analyse inheritance with Mendel''s laws and its effects on populations, and to analyse evidence for biological evolution by natural selection, seen in allele frequency and in organisms'' structure and function. A further goal asks pupils to plan and carry out scientific inquiries.","subject":"science","gradeFrom":9,"gradeTo":10,"topicTags":["heredity","variation","mendel","natural selection","evolution","allele frequency","classification"]}', ''),
  ('74daaead-d7a3-5b57-9648-1609dbfef995', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-biology-grades-11-12-illustrative-content', 'NCF-SE 2023 (NCERT), Biology for Classes 11 and 12: illustrative content areas including genetics and evolution', '{"id":"IN-MANDATE-ncf-se-2023-biology-grades-11-12-illustrative-content","label":"NCF-SE 2023 (NCERT), Biology for Classes 11 and 12: illustrative content areas including genetics and evolution","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 10 ''Subjects in Grades 11 and 12'', Section 10.2.1 Biology: 10.2.1.1 design principles (printed p. 456) and 10.2.1.2 illustrative content areas 1 to 5 (printed pp. 457-458). PDF pages 470-472.. AI-drafted from the primary PDF and not reviewed by a subject expert. A second AI reader re-read Section 10.2.1 (printed pp. 456-458). NCF-SE labels these content areas illustrative, so they describe options for course designers and do not form a syllabus. NCERT''s textbook index (read from the page source on 30 October 2026) lists one Class 11 and one Class 12 Biology book. The Class 12 book is the revised edition of November 2022 with the 2026-27 reprint, and the Class 11 book (rationalised, 2026-27 reprint) has no Evolution chapter in its contents. No new textbook built on these areas was found. PDF page = printed page + 14. Release date: the Ministry of Education press release dated 23 August 2023 (Press Information Bureau, release id 1951485) says the Minister released the framework that day, which supports the month 2023-08. NCERT''s own pages and the PDF give no release date. The PDF front matter says First Edition October 2024, and the foreword dated 29 July 2023 is the date the steering committee handed the framework to the Minister. NCERT''s home page now also links a May 2026 re-issue (NCFSE2023_May2026.pdf) with the same text on every page cited here. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Curriculum Framework for School Education 2023 (NCERT first print, October 2024), Part C, Chapter 10 ''Subjects in Grades 11 and 12'', Section 10.2.1 Biology: 10.2.1.1 design principles (printed p. 456) and 10.2.1.2 illustrative content areas 1 to 5 (printed pp. 457-458). PDF pages 470-472.","description":"For Classes 11 and 12, the framework gives five illustrative Biology content areas instead of a syllabus. The area called The Unity of Life includes Mendel''s principles, how Darwin and Wallace developed the theory of evolution by natural selection, the modern synthesis, and phylogenetics through the Tree of Life. Another area studies organisms within an evolutionary framework, and the human biology area covers the evolutionary history of the genus Homo.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (framework prepared by the National Steering Committee for National Curriculum Frameworks, submitted to the Minister of Education)","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"For Classes 11 and 12, the framework gives five illustrative Biology content areas instead of a syllabus. The area called The Unity of Life includes Mendel''s principles, how Darwin and Wallace developed the theory of evolution by natural selection, the modern synthesis, and phylogenetics through the Tree of Life. Another area studies organisms within an evolutionary framework, and the human biology area covers the evolutionary history of the genus Homo.","subject":"science","gradeFrom":11,"gradeTo":12,"topicTags":["biology","evolution","natural selection","mendel","phylogenetics","history of science","human evolution"]}', ''),
  ('c25fd36e-e8af-5acd-b60a-d70b4e46e049', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-curiosity-class-6-science-scientific-method-and-adaptation', 'NCERT Curiosity (Science, Class 6), Chapters 1 and 2: scientific method, variation among living things, adaptation', '{"id":"IN-UNIT-ncert-curiosity-class-6-science-scientific-method-and-adaptation","label":"NCERT Curiosity (Science, Class 6), Chapters 1 and 2: scientific method, variation among living things, adaptation","sourceUrl":"https://ncert.nic.in/textbook/pdf/fecu102.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Curiosity: Textbook of Science for Grade 6 (NCERT, first edition July 2024, reprint 2026-27). Chapter 1 ''The Wonderful World of Science'' (https://ncert.nic.in/textbook/pdf/fecu101.pdf), printed pp. 5-7. Chapter 2 ''Diversity in the Living World'', sections 2.1 to 2.3, printed pp. 9-29; grouping activities pp. 14-23; adaptation pp. 23-27 (definition on p. 27).. AI-drafted from the primary PDFs and not reviewed by a subject expert. Read in full: Chapter 1, and Chapter 2 sections 2.1 to 2.3 with the summary. Searched by keyword only: every chapter of the Class 6, Class 7 and Class 8 Curiosity books, for natural selection, Darwin, Wallace, Mendel, heredity, inherit, extinct, fossil and evolution. Outside the Class 8 Chapter 13 passage the only hits were passing uses (Class 7 Chapter 1 says life has evolved over time; fossil appears only in fossil fuels). Class 7 Chapter 9 uses the word adapted for breathing in animals. The AI reader did not read teacher guidance or any NCERT syllabus document for Class 6. The Class 6 book is the 2026-27 reprint of the July 2024 first edition. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Curiosity: Textbook of Science for Grade 6 (NCERT, first edition July 2024, reprint 2026-27). Chapter 1 ''The Wonderful World of Science'' (https://ncert.nic.in/textbook/pdf/fecu101.pdf), printed pp. 5-7. Chapter 2 ''Diversity in the Living World'', sections 2.1 to 2.3, printed pp. 9-29; grouping activities pp. 14-23; adaptation pp. 23-27 (definition on p. 27).","description":"Chapter 1 presents the scientific method as observing, wondering, guessing a cause, testing the guess and analysing the result, using a pen that stops writing as the example. Chapter 2 has pupils record differences among plants and animals on a nature walk and group them by shared features. It calls features that help living things survive in a place, such as a camel''s humps, adaptations, without saying how they arise.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2024-07","dateGranularity":"month","statementText":"Chapter 1 presents the scientific method as observing, wondering, guessing a cause, testing the guess and analysing the result, using a pen that stops writing as the example. Chapter 2 has pupils record differences among plants and animals on a nature walk and group them by shared features. It calls features that help living things survive in a place, such as a camel''s humps, adaptations, without saying how they arise.","subject":"science","gradeFrom":6,"gradeTo":6,"topicTags":["class 6","scientific method","diversity of life","grouping","adaptation","habitat"]}', ''),
  ('1608e1dd-a750-5f9c-9bac-edb027df4454', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-curiosity-class-8-science-testing-ideas-and-genes-and-variation', 'NCERT Curiosity (Science, Class 8), Chapters 1, 3 and 13: testing ideas, antibiotic resistance, genes and variation', '{"id":"IN-UNIT-ncert-curiosity-class-8-science-testing-ideas-and-genes-and-variation","label":"NCERT Curiosity (Science, Class 8), Chapters 1, 3 and 13: testing ideas, antibiotic resistance, genes and variation","sourceUrl":"https://ncert.nic.in/textbook/pdf/hecu113.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Curiosity: Textbook of Science for Grade 8 (NCERT, first edition June 2025, reprinted January 2026, stamped Reprint 2026-27). Chapter 13 ''Our Home: Earth, a Unique Life Sustaining Planet'', section 13.5 ''What Keeps Life from Disappearing?'', printed pp. 219-222 (the passage on small changes adding up over generations is on pp. 219-220). Chapter 3 ''Health: The Ultimate Treasure'' (hecu103.pdf): ''Think like a scientist'' box on Jenner, p. 38; antibiotic resistance, pp. 40-41. Chapter 1 ''Exploring the Investigative World of Science'' (hecu101.pdf), printed pp. 6-7.. AI-drafted from the primary PDFs and not reviewed by a subject expert. A second AI reader re-read the cited pages. The Chapter 13 passage says genes carry instructions, that reproduction allows small changes in them, and that over many generations such changes can lead to new features or completely new types of living beings. It also says ''Even microbes evolve'', so the word evolve appears, but the phrase natural selection does not appear in any of the 13 chapters. The wording that camels ''developed humps'' is brief and a reviewer may want to check how teacher guidance frames it. The chapter names no alleles, mutation or natural selection. Chapter 3 shows the antibiotic resistance story as an infographic on p. 41: a few bacteria resist, the antibiotic kills others, and the resistant ones take over, which is selection described without the word. Class 9 Exploration Chapter 11 points back to Chapter 13 in a margin note. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Curiosity: Textbook of Science for Grade 8 (NCERT, first edition June 2025, reprinted January 2026, stamped Reprint 2026-27). Chapter 13 ''Our Home: Earth, a Unique Life Sustaining Planet'', section 13.5 ''What Keeps Life from Disappearing?'', printed pp. 219-222 (the passage on small changes adding up over generations is on pp. 219-220). Chapter 3 ''Health: The Ultimate Treasure'' (hecu103.pdf): ''Think like a scientist'' box on Jenner, p. 38; antibiotic resistance, pp. 40-41. Chapter 1 ''Exploring the Investigative World of Science'' (hecu101.pdf), printed pp. 6-7.","description":"Chapter 13 tells pupils that genes pass instructions from parents to offspring, that reproduction can change those instructions slightly, and that over many generations such changes can add up to new kinds of living things. Camels and antibiotic-resistant bacteria are the examples. Chapter 1 teaches changing one factor at a time in an investigation, and Chapter 3 sets out Jenner''s smallpox work as observation, hypothesis, test and result.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2025-06","dateGranularity":"month","statementText":"Chapter 13 tells pupils that genes pass instructions from parents to offspring, that reproduction can change those instructions slightly, and that over many generations such changes can add up to new kinds of living things. Camels and antibiotic-resistant bacteria are the examples. Chapter 1 teaches changing one factor at a time in an investigation, and Chapter 3 sets out Jenner''s smallpox work as observation, hypothesis, test and result.","subject":"science","gradeFrom":8,"gradeTo":8,"topicTags":["class 8","genes","variation","reproduction","antibiotic resistance","controlled investigation","hypothesis"]}', ''),
  ('970343f4-57d9-58dc-bc08-79f011daa305', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-exploration-class-9-science-variation-and-biodiversity', 'NCERT Exploration (Science, Class 9), Chapters 11 and 12: variation, adaptation and how biodiversity evolved', '{"id":"IN-UNIT-ncert-exploration-class-9-science-variation-and-biodiversity","label":"NCERT Exploration (Science, Class 9), Chapters 11 and 12: variation, adaptation and how biodiversity evolved","sourceUrl":"https://ncert.nic.in/textbook/pdf/iesc112.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Exploration: Textbook of Science for Grade 9 (NCERT, first edition April 2026). Chapter 12 ''Patterns in Life: Diversity and Classification'': section 12.2 ''How has the Biodiversity Evolved?'' (printed p. 229), section 12.3.1 (p. 231), section 12.7 (p. 244), three-domain box (p. 246). Chapter 11 ''Reproduction: How Life Continues'' (iesc111.pdf): introduction (pp. 208-209), section 11.2.1 (pp. 213-214).. AI-drafted from the primary PDFs and not reviewed by a subject expert. A second AI reader re-read the cited pages. Section 12.2 (printed p. 229, running into p. 230) speaks of small differences among individuals and does not use the word inherited. The link to inheritance is in the Chapter 11 introduction (printed p. 208), which says offspring inherit a mix of characteristics and that such differences, accumulated over many generations, can give rise to new kinds of species. The phrase natural selection and the words allele and mutation appear in none of the 13 chapters. Darwin is named once, as the author of a book in a library example (section 12.4, p. 232). Section 12.9 ''Fossils as Evidence'' (p. 247) says rock layers and fossils show how life changed over millions of years. Chapter 11 p. 214 gives the examples of digesting milk in adulthood and tolerating low oxygen at altitude. These resemble the models'' lactase persistence human-example parts, but only short ids were available for those parts, so no link was made. CBSE''s 2026-27 Class 9 Science syllabus (PDF p. 7) lists a learning outcome on how sexual reproduction introduces variation and one on five-kingdom classification, with no learning outcome on evolution or adaptation, although competency C 4.5 is listed (PDF p. 3). The foreword of this book is dated February 2026 and the first edition is April 2026. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Exploration: Textbook of Science for Grade 9 (NCERT, first edition April 2026). Chapter 12 ''Patterns in Life: Diversity and Classification'': section 12.2 ''How has the Biodiversity Evolved?'' (printed p. 229), section 12.3.1 (p. 231), section 12.7 (p. 244), three-domain box (p. 246). Chapter 11 ''Reproduction: How Life Continues'' (iesc111.pdf): introduction (pp. 208-209), section 11.2.1 (pp. 213-214).","description":"Section 12.2 says that slight differences between individuals changed how well each one survived and reproduced, and that these differences built up across many generations to produce new forms of life. Section 12.3 says similar features suggest descent from common ancestors, and section 12.7 links animal adaptations to changes in body structure. Chapter 11 says meiosis creates variation that helps some individuals adapt and, over time, contributes to evolution.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2026-04","dateGranularity":"month","statementText":"Section 12.2 says that slight differences between individuals changed how well each one survived and reproduced, and that these differences built up across many generations to produce new forms of life. Section 12.3 says similar features suggest descent from common ancestors, and section 12.7 links animal adaptations to changes in body structure. Chapter 11 says meiosis creates variation that helps some individuals adapt and, over time, contributes to evolution.","subject":"science","gradeFrom":9,"gradeTo":9,"topicTags":["class 9","variation","meiosis","adaptation","common ancestry","classification","biodiversity"]}', ''),
  ('169ec663-7ad8-56f1-8896-98c9157907ce', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics', 'NCERT Class 10 Science, Chapter 8 Heredity, and the CBSE Class 10 Science syllabus 2026-27: where evolution stands', '{"id":"IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics","label":"NCERT Class 10 Science, Chapter 8 Heredity, and the CBSE Class 10 Science syllabus 2026-27: where evolution stands","sourceUrl":"https://ncert.nic.in/textbook/pdf/jesc108.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Science: Textbook for Class X (NCERT, revised edition October 2022, reprint 2026-27), Chapter 8 ''Heredity'', printed pp. 128-133 (section 8.1, the sentence on selection of variants, p. 129; summary, p. 133) and Chapter 7 ''How do Organisms Reproduce?'', section 7.1, printed pp. 113-115 (variation and heat-resistant bacteria, p. 114). CBSE Science (086) Class X 2026-27 (https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart1/Science_SecP1_2026-27.pdf), PDF p. 3 (competency C 4.5), p. 5 (Unit II: Heredity and Evolution lines), p. 6 (note 1 for teachers).. AI-drafted from the primary PDFs and not reviewed by a subject expert. A second AI reader re-read all the cited pages. Dates: the NCERT book is the revised edition of October 2022 (first edition December 2006), reprinted March 2024, June 2024, December 2024 and January 2026, and every page is stamped Reprint 2026-27. The CBSE syllabus date comes from CBSE circular Acad-14/2026 of 1 April 2026, which gives 2 April 2026 as the release date of the Classes IX and X curriculum. Chapter 8 Heredity covers printed pp. 128-133 and has no evolution section. The contents list has no Evolution chapter (Chapters 1 to 13, ending with Our Environment). The book says on p. 129 that evolution is discussed in later sections, and Chapter 7 p. 114 says it will be discussed in the next chapter. Neither exists in this edition. The pre-2022 edition was not read, so the record can say what the present edition contains but not what was removed. In the CBSE syllabus the Heredity line (Mendel, sex determination) sits in the main topic list, and the Evolution line (acquired and inherited traits, speciation, evolution and classification, tracing evolutionary relationships, fossils, evolution by stages, human evolution) is marked formative only. Note 1 for teachers then says Heredity and Evolution will not be assessed in the year-end examination. CBSE says relevant NCERT text is enclosed for reference. That text was not found on CBSE''s curriculum page, which lists no Class 10 science reading material. NCERT''s textbook index lists one Class 10 Science book. The existing project record on the 2023-24 rationalisation should be reconciled with this record and with the Class 12 record. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Science: Textbook for Class X (NCERT, revised edition October 2022, reprint 2026-27), Chapter 8 ''Heredity'', printed pp. 128-133 (section 8.1, the sentence on selection of variants, p. 129; summary, p. 133) and Chapter 7 ''How do Organisms Reproduce?'', section 7.1, printed pp. 113-115 (variation and heat-resistant bacteria, p. 114). CBSE Science (086) Class X 2026-27 (https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart1/Science_SecP1_2026-27.pdf), PDF p. 3 (competency C 4.5), p. 5 (Unit II: Heredity and Evolution lines), p. 6 (note 1 for teachers).","description":"NCERT''s Class 10 chapter Heredity covers variation arising in reproduction, Mendel''s rules, how traits are expressed and sex determination. It says selection of variants by the environment is the basis of evolution, then points to later sections that this edition does not have. CBSE''s 2026-27 Class 10 syllabus lists evolution topics such as speciation, fossils and human evolution as formatively assessed only.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (textbook) and CBSE (syllabus)","mandateType":"curriculum-unit","adoptionDate":"2026-04","dateGranularity":"month","statementText":"NCERT''s Class 10 chapter Heredity covers variation arising in reproduction, Mendel''s rules, how traits are expressed and sex determination. It says selection of variants by the environment is the basis of evolution, then points to later sections that this edition does not have. CBSE''s 2026-27 Class 10 syllabus lists evolution topics such as speciation, fossils and human evolution as formatively assessed only.","subject":"science","gradeFrom":10,"gradeTo":10,"topicTags":["class 10","heredity","mendel","evolution","rationalisation","formative assessment"]}', ''),
  ('0cf81538-c87d-518a-a391-8c0a2cd7cd22', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'NCERT Class 12 Biology, Chapter 6 Evolution, and the CBSE Class 12 Biology syllabus 2026-27, Unit VII', '{"id":"IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii","label":"NCERT Class 12 Biology, Chapter 6 Evolution, and the CBSE Class 12 Biology syllabus 2026-27, Unit VII","sourceUrl":"https://ncert.nic.in/textbook/pdf/lebo106.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Biology: Textbook for Class XII (NCERT, revised edition November 2022, reprint 2026-27), Chapter 6 ''Evolution'', printed pp. 110-126: section 6.2 (pp. 112-113), breeding argument in 6.3 (p. 115), adaptive radiation (p. 116), sections 6.5 to 6.7 (pp. 118-121), summary (p. 126). CBSE Biology (044) Classes XI-XII 2026-27 (https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Biology_SecP2_2026-27.pdf), Class XII course structure (PDF p. 9) and Unit VII Chapter 6 (PDF p. 10).. AI-drafted from the primary PDFs and not reviewed by a subject expert. A second AI reader re-read the cited pages. Dates: the NCERT book is the revised edition of November 2022 (first edition December 2006), reprinted March 2024, December 2024 and January 2026, and every page is stamped Reprint 2026-27. Chapter 6 Evolution runs from printed p. 110 to p. 126, which is 17 pages. The CBSE syllabus date comes from circular Acad-14/2026 of 1 April 2026. The 20-mark figure is for the whole of Unit VII (Chapters 4, 5 and 6) and was checked on the page image of CBSE PDF p. 9 (Unit VI 16, VII 20, VIII 12, IX 12, X 10, total 70). The existing project record says the 2023-24 rationalisation deleted evolution nationally. What was read does not support that for Class 12: the full chapter is in the book NCERT hosts for 2026-27 and in CBSE''s Unit VII. Please reconcile the two records. The Class 12 preface (text from 2006) still says the book relates genes to evolution. NCERT''s textbook index lists one edition of Class 12 Biology, and the rationalised Class 11 Biology book has no Evolution chapter. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Biology: Textbook for Class XII (NCERT, revised edition November 2022, reprint 2026-27), Chapter 6 ''Evolution'', printed pp. 110-126: section 6.2 (pp. 112-113), breeding argument in 6.3 (p. 115), adaptive radiation (p. 116), sections 6.5 to 6.7 (pp. 118-121), summary (p. 126). CBSE Biology (044) Classes XI-XII 2026-27 (https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Biology_SecP2_2026-27.pdf), Class XII course structure (PDF p. 9) and Unit VII Chapter 6 (PDF p. 10).","description":"The NCERT Class 12 Biology book hosted for 2026-27 still has a 17-page Evolution chapter. It covers Darwin and Wallace, natural selection, adaptive radiation, the Hardy-Weinberg principle, gene flow, genetic drift, the founder effect, speciation and human evolution. CBSE''s 2026-27 Class 12 syllabus lists the chapter in Unit VII, Genetics and Evolution, which also holds the inheritance and molecular-basis chapters and is worth 20 of 70 theory marks.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT (textbook) and CBSE (syllabus)","mandateType":"curriculum-unit","adoptionDate":"2026-04","dateGranularity":"month","statementText":"The NCERT Class 12 Biology book hosted for 2026-27 still has a 17-page Evolution chapter. It covers Darwin and Wallace, natural selection, adaptive radiation, the Hardy-Weinberg principle, gene flow, genetic drift, the founder effect, speciation and human evolution. CBSE''s 2026-27 Class 12 syllabus lists the chapter in Unit VII, Genetics and Evolution, which also holds the inheritance and molecular-basis chapters and is worth 20 of 70 theory marks.","subject":"science","gradeFrom":12,"gradeTo":12,"topicTags":["class 12","evolution","natural selection","hardy-weinberg","genetic drift","speciation","darwin"]}', ''),
  ('3ecb02ec-c594-5ea8-9f3c-47f207033690', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-ncf-se-2023-social-science-aims-and-goals', 'National Curriculum Framework for School Education 2023, Part C Chapter 5: Social Science Education', '{"id":"IN-MANDATE-ncf-se-2023-social-science-aims-and-goals","label":"National Curriculum Framework for School Education 2023, Part C Chapter 5: Social Science Education","sourceUrl":"https://ncert.nic.in/pdf/NCFSE-2023-August_2023.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: NCF-SE 2023, Part C, Chapter 5 Social Science Education, printed pp. 298-331: 5.1 Aims (p. 299), 5.2 Nature of Knowledge (pp. 301-302), 5.3 Current Challenges (p. 302), 5.4 Learning Standards with Middle Stage goals (pp. 303-305) and Secondary Stage goals (pp. 306-309), 5.5 Content from p. 310, including the local-to-global proportions (pp. 314-315) and the four Middle Stage themes (pp. 315-319).. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked it against NCERT''s PDF of the framework. Printed page = PDF page minus 14. Goals are described in own words with no competency codes, because the goal tables are laid out in columns; please check pp. 303-309 against the printed tables. Dates: the foreword is signed 29 July 2023 and the printed first edition says October 2024. The Ministry of Education press release on PIB (posted 23 August 2023) records the release of the framework by the Education Minister that day, so 2023-08 is the release month. The framework calls its theme list illustrative and gives a directional split of content: local 20 percent, regional 30, national 30, global 20 (pp. 314-315). The four Middle Stage themes are people and cultures, livelihoods, links between people and environment, and democracy and governance (pp. 315-319). The drafter also read Part B Chapter 2 on values (pp. 141-146), the Class 9 course Individuals in Society and the Classes 11-12 sociology outline, and wrote no separate records for them; those page numbers were not re-checked. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"NCF-SE 2023, Part C, Chapter 5 Social Science Education, printed pp. 298-331: 5.1 Aims (p. 299), 5.2 Nature of Knowledge (pp. 301-302), 5.3 Current Challenges (p. 302), 5.4 Learning Standards with Middle Stage goals (pp. 303-305) and Secondary Stage goals (pp. 306-309), 5.5 Content from p. 310, including the local-to-global proportions (pp. 314-315) and the four Middle Stage themes (pp. 315-319).","description":"The framework says social science should help students understand how societies work, build habits of inquiry from evidence, and act as responsible citizens. It is one integrated, theme-based subject in Classes 6 to 8, studied locally, regionally, nationally and globally, and is split by discipline in Classes 9 and 10. Goals cover institutions, harmony and conflict among groups, inequality, local self-government and the Constitution. It adds that the subject is interpretive, so students should meet several well-evidenced readings.","verificationStatus":"primary-source-confirmed","issuingBody":"National Steering Committee for National Curriculum Frameworks, submitted to the Ministry of Education; published by NCERT","mandateType":"curriculum-framework","adoptionDate":"2023-08","dateGranularity":"month","statementText":"The framework says social science should help students understand how societies work, build habits of inquiry from evidence, and act as responsible citizens. It is one integrated, theme-based subject in Classes 6 to 8, studied locally, regionally, nationally and globally, and is split by discipline in Classes 9 and 10. Goals cover institutions, harmony and conflict among groups, inequality, local self-government and the Constitution. It adds that the subject is interpretive, so students should meet several well-evidenced readings.","subject":"social-science","gradeFrom":6,"gradeTo":10,"topicTags":["social science","institutions","constitution","unity in diversity","local self-government","inequality","interdisciplinary","plural interpretations"]}', ''),
  ('931c9dbe-b7e4-55c8-8e91-f5c243bf4ce7', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-nep-2020-constitutional-values-citizenship-and-ethical-reasoning', 'National Education Policy 2020: constitutional values, citizenship skills and ethical reasoning for all students', '{"id":"IN-MANDATE-nep-2020-constitutional-values-citizenship-and-ethical-reasoning","label":"National Education Policy 2020: constitutional values, citizenship skills and ethical reasoning for all students","sourceUrl":"https://static.pib.gov.in/WriteReadData/userfiles/NEP_Final_English_0.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: National Education Policy 2020, Principles of this Policy (printed pp. 4-5), The Vision of this Policy (p. 6), Section 4.23 (p. 15) and Sections 4.27-4.28 (p. 16).. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked the cited passages in the copy hosted by the Press Information Bureau (printed pp. 4-6, 15-16); they match. Date: the copy has no printed date. The Union Cabinet approved the policy on 29 July 2020 (Ministry of Education press release on PIB, posted 29 July 2020) and the PDF was created on 30 July 2020, so July 2020 is confirmed. The Ministry of Education''s own file paths returned 404, so this copy has not been compared with the Ministry''s copy. The front page names the Ministry of Human Resource Development. NCF-SE 2023, Part B Chapter 2 (pp. 141-146) turns these passages into a plan: values are taught directly (a Class 9 course) and through subjects, school culture is central, and Bal Sabhas and Bal Panchayats are given as examples. The framework also notes that values encouraged at school may differ from what students see outside school (p. 145). The policy sets no stage-by-stage progression, so links to the models are weak. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"National Education Policy 2020, Principles of this Policy (printed pp. 4-5), The Vision of this Policy (p. 6), Section 4.23 (p. 15) and Sections 4.27-4.28 (p. 16).","description":"The policy says schools should build ethics and constitutional values such as empathy, democratic spirit, pluralism and justice, and lists cooperation and teamwork among the life skills to teach. It names citizenship skills, Fundamental Duties, knowledge of India, ethical reasoning and current affairs as learning for every student, wants children taught early to reason about right and wrong, and makes excerpts of the Constitution essential reading.","verificationStatus":"primary-source-confirmed","issuingBody":"Ministry of Human Resource Development (now Ministry of Education), Government of India","mandateType":"policy-statement","adoptionDate":"2020-07","dateGranularity":"month","statementText":"The policy says schools should build ethics and constitutional values such as empathy, democratic spirit, pluralism and justice, and lists cooperation and teamwork among the life skills to teach. It names citizenship skills, Fundamental Duties, knowledge of India, ethical reasoning and current affairs as learning for every student, wants children taught early to reason about right and wrong, and makes excerpts of the Constitution essential reading.","subject":"general","topicTags":["constitutional values","citizenship","ethical reasoning","cooperation","fundamental duties","pluralism"]}', ''),
  ('0511044c-a4e7-5350-81ce-42b824b41eb0', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class6-family-and-community', 'NCERT, Exploring Society: India and Beyond (Class 6), Chapter 9 Family and Community', '{"id":"IN-UNIT-ncert-class6-family-and-community","label":"NCERT, Exploring Society: India and Beyond (Class 6), Chapter 9 Family and Community","sourceUrl":"https://ncert.nic.in/textbook/pdf/fees109.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Exploring Society: India and Beyond, Social Science Textbook for Grade 6 (NCERT; first edition June 2024, reprints February 2025 and February 2026), Theme D Governance and Democracy, Chapter 9 Family and Community, printed pp. 137-148.. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked the chapter in NCERT''s online file (printed pp. 137-148). Chapter number, title and page range match the book''s contents page. The statements in this record match the chapter, including the unwritten community rules on shared water, grazing land and forest produce, the residents'' welfare association example and the question on unfair rules. NCERT''s online print of this chapter from December 2024 has the same text as the current print. The chapter uses stories from Kerala and Meghalaya, the Bhil halma tradition in Madhya Pradesh, the 2015 Chennai floods and a tuition class in Ahmedabad. Date: the current file gives first edition June 2024 and reprints in February 2025 and February 2026. NCERT''s copy of the front pages archived on 5 August 2024 gives first edition July 2024. The record therefore gives the year only. Earlier classes: NCF-SE Part C section 7.4 (printed pp. 368-371) sets a Classes 3 to 5 subject called The World Around Us. Its competencies include explaining the functioning of local institutions such as the family, school and panchayat and analysing their roles. Its sample content includes relationships within family and community. A reviewer should compare that subject with this chapter before anyone says Class 6 introduces family and community rules. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Exploring Society: India and Beyond, Social Science Textbook for Grade 6 (NCERT; first edition June 2024, reprints February 2025 and February 2026), Theme D Governance and Democracy, Chapter 9 Family and Community, printed pp. 137-148.","description":"Students study the family as a unit where members have roles and duties, cooperate and depend on each other, and compare family types near them. They then meet communities: groups of families that share festivals and, in many villages and tribal communities, long-standing unwritten rules on water, grazing land and forest produce that give each family duties. Residents'' welfare associations show people making their own rules. Questions ask which rules may be unfair.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"Students study the family as a unit where members have roles and duties, cooperate and depend on each other, and compare family types near them. They then meet communities: groups of families that share festivals and, in many villages and tribal communities, long-standing unwritten rules on water, grazing land and forest produce that give each family duties. Residents'' welfare associations show people making their own rules. Questions ask which rules may be unfair.","subject":"social-science","gradeFrom":6,"gradeTo":6,"topicTags":["family","community","roles","rules","cooperation","shared resources","interdependence"]}', ''),
  ('ae8791ba-f5ac-58b7-9a94-b320dd8798c5', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class6-unity-in-diversity', 'NCERT, Exploring Society: India and Beyond (Class 6), Chapter 8 on unity in diversity', '{"id":"IN-UNIT-ncert-class6-unity-in-diversity","label":"NCERT, Exploring Society: India and Beyond (Class 6), Chapter 8 on unity in diversity","sourceUrl":"https://ncert.nic.in/textbook/pdf/fees108.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Exploring Society: India and Beyond, Grade 6 (NCERT, first edition June 2024), Theme C Our Cultural Heritage and Knowledge Traditions, Chapter 8 Unity in Diversity, or ''Many in the One'', printed pp. 125-136.. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked the whole chapter in NCERT''s online file (printed pp. 125-136). Chapter number, title and page range match the book''s contents page. The chapter cites the Anthropological Survey of India''s People of India project (4,635 communities, 325 languages, 25 scripts) and says about 200 adaptations of the Panchatantra exist in more than 50 languages. The chapter''s examples are food grains, the sari, Makara Sankranti and its regional names, the Panchatantra, and the Ramayana and Mahabharata with their tribal retellings. NCF-SE lists unity in diversity as a Middle Stage goal (p. 304). NCERT''s online print of this chapter from December 2024 differs from the current print in a few words only. Date: the current file gives first edition June 2024; NCERT''s copy of the front pages archived on 5 August 2024 gives July 2024. The record therefore gives the year only. The drafter also read the Class 7 Part 2 chapter ''India, a Home to Many'' (pp. 125-142) and wrote no record for it; that chapter was not re-checked. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Exploring Society: India and Beyond, Grade 6 (NCERT, first edition June 2024), Theme C Our Cultural Heritage and Knowledge Traditions, Chapter 8 Unity in Diversity, or ''Many in the One'', printed pp. 125-136.","description":"The chapter asks what holds India together despite visible differences. Students list classmates'' birthplaces and languages, then look at shared threads in food grains, the sari in many forms, a harvest festival with different regional names, and the Panchatantra and the two epics retold in many languages and tribal traditions. It closes by saying diversity enriches the shared culture.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"The chapter asks what holds India together despite visible differences. Students list classmates'' birthplaces and languages, then look at shared threads in food grains, the sari in many forms, a harvest festival with different regional names, and the Panchatantra and the two epics retold in many languages and tribal traditions. It closes by saying diversity enriches the shared culture.","subject":"social-science","gradeFrom":6,"gradeTo":6,"topicTags":["unity in diversity","culture","languages","festivals","literature","communities"]}', ''),
  ('80eac1e6-e376-5d40-b210-5644179b1d43', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class6-grassroots-democracy-governance-and-local-government', 'NCERT, Exploring Society: India and Beyond (Class 6), Chapters 10-12 Grassroots Democracy: governance and local government', '{"id":"IN-UNIT-ncert-class6-grassroots-democracy-governance-and-local-government","label":"NCERT, Exploring Society: India and Beyond (Class 6), Chapters 10-12 Grassroots Democracy: governance and local government","sourceUrl":"https://ncert.nic.in/textbook/pdf/fees110.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Exploring Society: India and Beyond, Grade 6 (NCERT, first edition June 2024), Theme D Governance and Democracy, Chapter 10 Grassroots Democracy Part 1: Governance (pp. 149-162), Chapter 11 Part 2: Local Government in Rural Areas (pp. 163-172), Chapter 12 Part 3: Local Government in Urban Areas (pp. 173-182).. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked chapters 10 and 11 (most of each), and the urban local bodies and citizen-action passages of chapter 12; the statements match. Chapter 11 is fees111.pdf and chapter 12 is fees112.pdf at the same address as the sourceUrl (chapter 10). NCF-SE lists local self-government among the Middle Stage goals (p. 305). NCERT''s online print of chapter 10 from December 2024 differs from the current print in a few words only. Date: the current file gives first edition June 2024; NCERT''s copy of the front pages archived on 5 August 2024 gives July 2024. The record therefore gives the year only. PREAMBLE REPORTS (secondary-source-only): news reports of 5 to 8 August 2024 (Careers360, Scroll) said several new Class 6 books, including this social science book, do not print the Preamble. NCERT''s reply, posted on its X account on 5 August 2024 and reported in the press, said that fundamental rights, fundamental duties and the national anthem also teach constitutional values. No NCERT notice on its website was found, so these points rest on news coverage. WHAT NCERT''S OWN FILES SHOW (primary): the front pages archived on 5 August 2024 (imprint: first edition July 2024) have the Fundamental Rights on page xii and the Fundamental Duties on page xiii, and no Preamble page was found. The current online file (imprint: first edition June 2024, reprints February 2025 and February 2026) has the Preamble as a picture on page xiii and no Fundamental Duties page. The files do not say when or why the change was made. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Exploring Society: India and Beyond, Grade 6 (NCERT, first edition June 2024), Theme D Governance and Democracy, Chapter 10 Grassroots Democracy Part 1: Governance (pp. 149-162), Chapter 11 Part 2: Local Government in Rural Areas (pp. 163-172), Chapter 12 Part 3: Local Government in Urban Areas (pp. 173-182).","description":"Three chapters explain why larger groups need rules and who makes them. Students learn governance, government and laws, the three organs that make, carry out and judge laws, and the three levels of government. They then study village councils (Gram Sabha, Gram Panchayat, block and district bodies, one-third of seats reserved for women, children''s Bal Panchayats) and urban local bodies, and are asked how citizens can help them work.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2024","dateGranularity":"year","statementText":"Three chapters explain why larger groups need rules and who makes them. Students learn governance, government and laws, the three organs that make, carry out and judge laws, and the three levels of government. They then study village councils (Gram Sabha, Gram Panchayat, block and district bodies, one-third of seats reserved for women, children''s Bal Panchayats) and urban local bodies, and are asked how citizens can help them work.","subject":"social-science","gradeFrom":6,"gradeTo":6,"topicTags":["governance","democracy","rules and laws","separation of powers","panchayati raj","local government","citizen participation"]}', ''),
  ('75264bba-64b2-5b57-a5b7-6dbd81fece2e', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class9-governance-and-public-policy', 'NCERT, Understanding Society: India and Beyond (Class 9 Part 2), Chapter 4 Governance and Public Policy', '{"id":"IN-UNIT-ncert-class9-governance-and-public-policy","label":"NCERT, Understanding Society: India and Beyond (Class 9 Part 2), Chapter 4 Governance and Public Policy","sourceUrl":"https://ncert.nic.in/textbook/pdf/iest204.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Understanding Society: India and Beyond, Social Science Textbook for Grade 9 Part 2 (NCERT, first edition September 2026), Political Science, Chapter 4 Governance and Public Policy, printed pp. 81-106.. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked the chapter in NCERT''s online file (printed pp. 81-106); chapter number, title and page range match the contents page, and the statements in the record match. The drafter read the first two thirds of the chapter and skimmed the rest; the second reader skimmed the pages on policy stages and citizens'' roles. The drafter also read the first half of Class 9 Part 1 Chapter 6 Democracy (June 2026 edition) and wrote no separate record. The Class 9 book is new, so no teacher feedback or news coverage was available. The chapter draws on Indian governance traditions, including Rajadharma and Ram Rajya (introduced as Gandhi''s ideal model), and names specific government initiatives. Class 9 Part 1 and this Part 2 are the first secondary-stage books the drafter found written to NCF-SE 2023; the statement that Classes 10 to 12 still use older books was not re-checked. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Understanding Society: India and Beyond, Social Science Textbook for Grade 9 Part 2 (NCERT, first edition September 2026), Political Science, Chapter 4 Governance and Public Policy, printed pp. 81-106.","description":"The chapter separates government (the institutions) from governance (how decisions are made, carried out and checked). Students analyse a flood response in which municipal staff, police, health workers, schools and neighbours act together, learn features of good governance, study e-governance, and learn how public policy is made, with citizens, media, civil society and private bodies named as contributors. It also traces governance ideas from the Vedic period to the Constitution.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2026-09","dateGranularity":"month","statementText":"The chapter separates government (the institutions) from governance (how decisions are made, carried out and checked). Students analyse a flood response in which municipal staff, police, health workers, schools and neighbours act together, learn features of good governance, study e-governance, and learn how public policy is made, with citizens, media, civil society and private bodies named as contributors. It also traces governance ideas from the Vedic period to the Constitution.","subject":"social-science","gradeFrom":9,"gradeTo":9,"topicTags":["governance","public policy","good governance","e-governance","citizen participation","collective response"]}', ''),
  ('505f2fcd-48ad-5786-ac81-a8267f2cb448', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-cbse-2026-27-sociology-classes-11-12', 'CBSE Curriculum 2026-27: Sociology (Subject Code 039), Classes 11 and 12', '{"id":"IN-MANDATE-cbse-2026-27-sociology-classes-11-12","label":"CBSE Curriculum 2026-27: Sociology (Subject Code 039), Classes 11 and 12","sourceUrl":"https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/Sociology_SecP2_2026-27.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CBSE, Curriculum for the Academic Year 2026-27, Sociology (Subject Code 039), Classes XI and XII: rationale and objectives, course structure and course content for both classes, document pp. 1-8.. AI-drafted summary. No subject expert has reviewed it. This syllabus comes from CBSE, a different body from NCERT. A second reader re-checked the whole syllabus (document pp. 1-8). The unit numbers in it skip (Class 11 has units 1-4, 7, 9 and 10; Class 12 has units 1-3, 5-9, 11, 12 and 15); the meaning of the gaps is not known. Date: CBSE circular Acad-14/2026, dated 1 April 2026, announces the release of the 2026-27 curriculum for Classes XI and XII on that day. The heading of this file shows the labels 2025-26 and 2026-27 printed over each other and the PDF was created on 19 March 2025, so the content may be unchanged from 2025-26; no earlier syllabus was compared. NCF-SE 2023 gives an illustrative Classes 11-12 sociology outline (Part C section 10.1.3, pp. 454-456); the drafter read it and wrote no separate record. The statement that NCERT''s online list still shows older Class 11 and 12 sociology books was not re-checked. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"CBSE, Curriculum for the Academic Year 2026-27, Sociology (Subject Code 039), Classes XI and XII: rationale and objectives, course structure and course content for both classes, document pp. 1-8.","description":"Class 11 covers social groups, status and role, social control, stratification, institutions such as family, work, politics, religion and education, culture, social change and social order, and classic thinkers. Class 12 covers caste, tribe, inequality and exclusion, cultural diversity and the nation state, structural and cultural change, rural and industrial change, and social movements including environmental, workers'', peasants'' and Dalit movements. Project work carries 20 marks.","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education (CBSE)","mandateType":"curriculum-framework","adoptionDate":"2026-04-01","dateGranularity":"day","statementText":"Class 11 covers social groups, status and role, social control, stratification, institutions such as family, work, politics, religion and education, culture, social change and social order, and classic thinkers. Class 12 covers caste, tribe, inequality and exclusion, cultural diversity and the nation state, structural and cultural change, rural and industrial change, and social movements including environmental, workers'', peasants'' and Dalit movements. Project work carries 20 marks.","subject":"social-science","gradeFrom":11,"gradeTo":12,"topicTags":["sociology","social groups","social control","institutions","social change","social movements","inequality","diversity"]}', '2026-04-01'),
  ('22008e1b-93ec-5561-81a9-c856940736ee', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-MANDATE-cbse-2026-27-political-science-classes-11-12', 'CBSE Curriculum 2026-27: Political Science (Subject Code 028), Classes 11 and 12', '{"id":"IN-MANDATE-cbse-2026-27-political-science-classes-11-12","label":"CBSE Curriculum 2026-27: Political Science (Subject Code 028), Classes 11 and 12","sourceUrl":"https://cbseacademic.nic.in/web_material/CurriculumMain27/SecPart2/PoliticalScience_SecP2_2026-27.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: CBSE, Curriculum for the Academic Year 2026-27, Political Science (Subject Code 028), Classes XI and XII: aims and objectives (pp. 1-2), Class XI structure and content including Local Governments and Social Justice (pp. 3-9), Class XII structure (p. 10) and Part A chapter 6 Environment and Natural Resources (p. 12).. AI-drafted summary. No subject expert has reviewed it. This syllabus comes from CBSE, a different body from NCERT. A second reader re-checked the aims, the course structures, Class XII chapters 1 to 8 and the learning-outcome tables for them; the statements in the record match. The file has 34 pages; the later pages hold assessment guidance and annexures that were not read. Date: CBSE circular Acad-14/2026, dated 1 April 2026, announces the release of the 2026-27 curriculum for Classes XI and XII on that day, and the PDF was created on 1 April 2026. The Class XII list includes Era of One-Party Dominance, Regional Aspirations and Recent Developments in Indian Politics. NCERT''s own lists of rationalised content (see the separate event record) mark parts of the older Class 12 politics book as dropped. The syllabus and the lists were not compared, so a reviewer should check what the 2026-27 syllabus contains for those topics. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"CBSE, Curriculum for the Academic Year 2026-27, Political Science (Subject Code 028), Classes XI and XII: aims and objectives (pp. 1-2), Class XI structure and content including Local Governments and Social Justice (pp. 3-9), Class XII structure (p. 10) and Part A chapter 6 Environment and Natural Resources (p. 12).","description":"Class 11 covers the Constitution at work (how it was made, rights, elections, executive, legislature, judiciary, federalism, local governments) and political theory: freedom, equality, social justice, rights, citizenship, nationalism and secularism. Class 12 covers contemporary world politics, including environment and natural resources with global commons and environmental movements, and politics in India since Independence.","verificationStatus":"primary-source-confirmed","issuingBody":"Central Board of Secondary Education (CBSE)","mandateType":"curriculum-framework","adoptionDate":"2026-04-01","dateGranularity":"day","statementText":"Class 11 covers the Constitution at work (how it was made, rights, elections, executive, legislature, judiciary, federalism, local governments) and political theory: freedom, equality, social justice, rights, citizenship, nationalism and secularism. Class 12 covers contemporary world politics, including environment and natural resources with global commons and environmental movements, and politics in India since Independence.","subject":"social-science","gradeFrom":11,"gradeTo":12,"topicTags":["political science","constitution","local governments","social justice","citizenship","global commons","environmental movements"]}', '2026-04-01'),
  ('11e2ac86-0612-5c42-98c9-616abb48c4ef', 'india-curriculum-repository', 'policy-timeline-event', 'IN', 'openlpm-starter-draft', 'IN-EVENT-ncert-2022-rationalised-content-democracy-movements-and-group-conflict-topics', 'NCERT lists of rationalised content (2022-23): topics marked as dropped in social science books for Classes 10 to 12', '{"id":"IN-EVENT-ncert-2022-rationalised-content-democracy-movements-and-group-conflict-topics","label":"NCERT lists of rationalised content (2022-23): topics marked as dropped in social science books for Classes 10 to 12","sourceUrl":"https://ncert.nic.in/rationalised-content.php","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: NCERT, List of Rationalised Content in Textbooks for Class X (booklet, https://ncert.nic.in/pdf/BookletClass10.pdf, imprint May 2022), entry 1072 Democratic Politics-II, printed p. 21; for Class XII (https://ncert.nic.in/pdf/BookletClass12.pdf), entries 12119 Politics in India Since Independence (printed pp. 70-71) and 12123 Psychology (printed p. 71). Notes page of each booklet for the stated reasons. NCERT, Rationalised Textbooks (https://ncert.nic.in/textbook/pdf/Rationalised.pdf), and NCERT press brief Rationalisation of NCERT Textbooks During the Pandemic.. AI-drafted summary. No subject expert has reviewed it. A second reader re-checked the entries in NCERT''s own booklets named above, plus the Class XI entry for Political Theory (chapters 9 Peace and 10 Development marked as dropped). The booklets say the exercise was done because of the pandemic and NEP 2020''s call for lighter content, and list five reasons: overlap with other subjects in the same class, similar content in lower or higher classes, difficulty, content students can learn by themselves or from peers, and content judged irrelevant in the present context. The same lists mark topics in many other subjects as dropped; this record covers only the social science items that bear on the Social-Core model. DATES AND SOURCES: both booklets carry the imprint May 2022. NCERT''s own page Rationalised Textbooks says the content was rationalised for 2022-23 and the same books continue in 2023-24. NCERT''s own press brief on rationalisation says the same and gives the reasons above. None of these NCERT documents prints a date (the PDFs were created in April 2023). NCERT''s response on the periodic table and evolution says the exercise was attempted ''in 2021''. The news coverage the drafter opened (PTI via Onmanorama, 18 June 2022; Outlook India, 1 June 2023; Free Press Journal, 2 June 2023) is secondary and is no longer needed for the date or the reasons. The drafter did not read the dropped chapters. Social movements still appear in the CBSE 2026-27 Class 12 sociology syllabus (see its record). Commentary on the exercise from several viewpoints exists and is not summarised here. A second AI reader corrected this record against the source (6 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"NCERT, List of Rationalised Content in Textbooks for Class X (booklet, https://ncert.nic.in/pdf/BookletClass10.pdf, imprint May 2022), entry 1072 Democratic Politics-II, printed p. 21; for Class XII (https://ncert.nic.in/pdf/BookletClass12.pdf), entries 12119 Politics in India Since Independence (printed pp. 70-71) and 12123 Psychology (printed p. 71). Notes page of each booklet for the stated reasons. NCERT, Rationalised Textbooks (https://ncert.nic.in/textbook/pdf/Rationalised.pdf), and NCERT press brief Rationalisation of NCERT Textbooks During the Pandemic.","description":"NCERT''s lists of rationalised content mark topics in its textbooks for Classes 6 to 12 as dropped and not to be assessed. Among them are, in Class 10 Democratic Politics II, the chapters on democracy and diversity, popular struggles and movements, and challenges to democracy. In Class 12 they are the politics chapter on popular movements and the psychology topics on cooperation and competition, inter-group conflict and conflict resolution. NCERT states its reasons as the pandemic, the NEP 2020 call to reduce content load, and overlap.","verificationStatus":"primary-source-confirmed","slug":"ncert-2022-rationalised-content-democracy-movements-and-group-conflict-topics","dateStart":"2022","dateGranularity":"year","eventType":"other","temporalStatus":"past-completed","topicTags":["rationalisation","democratic politics","popular movements","conflict resolution","cooperation and competition","psychology"]}', ''),
  ('b572f2b4-a470-5b78-ab72-d9bc8922bf81', 'india-curriculum-repository', 'institutional-mandate-record', 'IN', 'openlpm-starter-draft', 'IN-UNIT-ncert-class8-part2-judiciary-and-citizenship-rights-and-duties', 'NCERT, Exploring Society: India and Beyond (Class 8 Part 2), Chapters 4 and 5: Judiciary; Citizenship, Rights and Duties', '{"id":"IN-UNIT-ncert-class8-part2-judiciary-and-citizenship-rights-and-duties","label":"NCERT, Exploring Society: India and Beyond (Class 8 Part 2), Chapters 4 and 5: Judiciary; Citizenship, Rights and Duties","sourceUrl":"https://ncert.nic.in/textbook/pdf/hees205.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: Exploring Society: India and Beyond, Social Science Textbook for Grade 8 Part 2 (NCERT; revised edition, imprint first edition June 2026), Theme D Governance and Democracy, Chapter 4 The Role of the Judiciary in Our Society (printed pp. 125-142) and Chapter 5 Citizenship: Rights and Duties (pp. 143-166); Acknowledgements (p. xv). Timeline: NCERT press release of 25 February 2026 and NCERT media advisory on recall (both on ncert.nic.in).. AI-drafted summary. No subject expert has reviewed it. This record describes the revised edition of the book (imprint: first edition June 2026). A second reader re-checked Chapter 5 in full and Chapter 4 (revised text) in its main sections. TIMELINE FROM NCERT''S OWN DOCUMENTS: NCERT brought out Part 2 on 24 February 2026. In a press release dated 25 February 2026, NCERT said Chapter 4 contained inappropriate textual material and an error of judgement, that the Department of School Education and Literacy had put distribution on hold, and that the chapter would be rewritten for the 2026-27 session; NCERT apologised in that release. A media advisory (PDF created 27 February 2026) asked holders to return the book, quoted para 20 of the Supreme Court order of 26 February 2026 banning further printing and digital circulation, and said NCERT had withdrawn the textbook. The revised book''s acknowledgements (p. xv) say it was published after a review carried out in compliance with the Supreme Court''s directions in Suo Motu Writ Petition (Civil) No. 1/2026, and that Chapter 4 was rewritten by a committee constituted by the Ministry of Education following para 10 of the court''s order. The Supreme Court''s record of proceedings of 11 March 2026 (copy hosted by SC Observer) records an affidavit from NCERT''s Director with an unconditional apology, the recall of 82,440 copies, and a direction that the Government constitute a committee of domain experts to approve any rewritten chapter. NEWS ONLY (secondary-source-only): the closing of the court proceedings on 1 September 2026, and the later history of the court''s other directions. News outlets give 10 or 11 March 2026 for the apology affidavit; the court''s record of 11 March records it as already filed. The AI reader did not see the withdrawn text, so the AI reader cannot say what changed between versions, and this record takes no view on the merits of the first version, the court''s order or NCERT''s response. The revised Chapter 4 mentions case backlog in its passage on Lok Adalats. Chapter 5 also mentions the Citizenship Act of 1955 and its 2019 amendment, and a ruling that overturned an Uttarakhand High Court order on river rights; this record summarises neither. A second AI reader corrected this record against the source (5 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN","sourcePassage":"Exploring Society: India and Beyond, Social Science Textbook for Grade 8 Part 2 (NCERT; revised edition, imprint first edition June 2026), Theme D Governance and Democracy, Chapter 4 The Role of the Judiciary in Our Society (printed pp. 125-142) and Chapter 5 Citizenship: Rights and Duties (pp. 143-166); Acknowledgements (p. xv). Timeline: NCERT press release of 25 February 2026 and NCERT media advisory on recall (both on ncert.nic.in).","description":"In the revised June 2026 edition, Chapter 4 explains justice, how courts are organised and other ways to settle disputes, such as mediation. Chapter 5 defines citizen, rights, duties, discrimination and inclusion, covers the six groups of Fundamental Rights, lists the Fundamental Duties with school examples, and uses a festival story and an equality versus equity picture to show why support may differ between people. It says rights are protected by law while duties are moral and social responsibilities.","verificationStatus":"primary-source-confirmed","issuingBody":"NCERT","mandateType":"curriculum-unit","adoptionDate":"2026-06","dateGranularity":"month","statementText":"In the revised June 2026 edition, Chapter 4 explains justice, how courts are organised and other ways to settle disputes, such as mediation. Chapter 5 defines citizen, rights, duties, discrimination and inclusion, covers the six groups of Fundamental Rights, lists the Fundamental Duties with school examples, and uses a festival story and an equality versus equity picture to show why support may differ between people. It says rights are protected by law while duties are moral and social responsibilities.","subject":"social-science","gradeFrom":8,"gradeTo":8,"topicTags":["judiciary","citizenship","rights and duties","discrimination","inclusion","equity","dispute resolution"]}', ''),
  ('45ecbcef-b4c2-5d17-95ac-16c9bdc76245', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-school-governance-two-boards', 'UP Board of 1921 and Basic Shiksha Parishad of 1972: the two bodies that organise school education in Uttar Pradesh', '{"id":"IN-UP-MANDATE-school-governance-two-boards","label":"UP Board of 1921 and Basic Shiksha Parishad of 1972: the two bodies that organise school education in Uttar Pradesh","sourceUrl":"https://upmsp.edu.in/AboutUs.aspx","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: UPMSP website, ''Board ka itihas'' (Board history) page, sections Historical Over View, Main Functions, Number of Schools, Administrative Setup. Also the Uttar Pradesh Basic Shiksha Adhiniyam 1972 (Act 34 of 1972), sections 2, 3 and 4, PDF pages 2 to 3 (printed pages 1 to 2) of the PRS Legislative Research scan (https://prsindia.org/files/bills_acts/acts_states/uttar-pradesh/1972/1972UP34.pdf).. Read directly: the Board''s own history page (English) and a scanned Hindi copy of the 1972 Act on the PRS Legislative Research site (the cover says amendments of 2000 and 2018 are appended). The India Code copy of the Act returned an error page, so the PRS scan is a convenience copy. The authoritative text is the gazette. The Act''s definition of basic education (section 2, education up to Class 8 in schools other than high schools and intermediate colleges) and the setting up of the Parishad (section 3) read clearly in the scan. Section 4(1) (organising and coordinating basic education and teacher training) reads clearly. The list of powers in section 4(2) is partly illegible, so please check it against the gazette text. The date field holds 1921, the year the UP Board was set up. The Basic Shiksha Parishad dates from the 1972 Act. The Board''s letters of 31 Jan, 4 Apr and 3 Jul 2026 also name the chain of officers: Secretary of the Board, District Inspector of Schools, Deputy and Joint Directors of Education, the Director General of School Education, and the state Secondary Education department. Not read: any page of the State Council of Educational Research and Training (SCERT) Uttar Pradesh, the Basic Education Department or the Directorate of Secondary Education, because those sites would not open from the drafter''s network. News (Free Press Journal, 13 Jan 2024) quotes an SCERT joint director on adapting NCERT books for Classes 1 and 2, so SCERT has a primary-class textbook role, but it was not confirmed from an official page. The Board''s history page lists four regional offices (Meerut 1973, Varanasi 1978, Bareilly 1981, Prayagraj 1987); a Board notice dated 11 Feb 2026 is said to name five (it adds Gorakhpur). The checker did not re-check that notice. Which regional office covers Ghaziabad was not confirmed. The history page says a few secondary schools in the state follow CBSE or ICSE; how many in Ghaziabad was not checked. Classes 6 to 8 taught inside a high school or intermediate college seem to fall outside the Act''s definition of basic education; a reviewer from UP should confirm which body sets the syllabus there. This record is AI-drafted and has not been checked by a subject expert. A second AI reader corrected this record against the source (3 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"UPMSP website, ''Board ka itihas'' (Board history) page, sections Historical Over View, Main Functions, Number of Schools, Administrative Setup. Also the Uttar Pradesh Basic Shiksha Adhiniyam 1972 (Act 34 of 1972), sections 2, 3 and 4, PDF pages 2 to 3 (printed pages 1 to 2) of the PRS Legislative Research scan (https://prsindia.org/files/bills_acts/acts_states/uttar-pradesh/1972/1972UP34.pdf).","description":"School education in Uttar Pradesh runs through two main bodies. The Basic Shiksha Parishad, created by a 1972 Act, organises basic education up to Class 8 in schools other than high schools and intermediate colleges. The UP Board (Madhyamik Shiksha Parishad), set up in 1921 at Prayagraj, recognises schools, prescribes courses and textbooks, and runs the Class 10 and Class 12 examinations. The Board says over 22,000 schools hold its recognition.","verificationStatus":"primary-source-confirmed","issuingBody":"Government of Uttar Pradesh (Basic Shiksha Parishad under the 1972 Act; Madhyamik Shiksha Parishad under the Intermediate Education Act 1921)","mandateType":"other","adoptionDate":"1921","dateGranularity":"year","statementText":"School education in Uttar Pradesh runs through two main bodies. The Basic Shiksha Parishad, created by a 1972 Act, organises basic education up to Class 8 in schools other than high schools and intermediate colleges. The UP Board (Madhyamik Shiksha Parishad), set up in 1921 at Prayagraj, recognises schools, prescribes courses and textbooks, and runs the Class 10 and Class 12 examinations. The Board says over 22,000 schools hold its recognition.","subject":"general","gradeFrom":1,"gradeTo":12,"topicTags":["school governance","basic shiksha parishad","up board","recognition","textbooks","uttar pradesh"]}', ''),
  ('ea0a6f92-c450-5fff-8393-73d77b705817', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-upmsp-ncert-textbooks-classes-9-12-2026-27', 'UP Board (UPMSP) letters of 2026: 70 NCERT textbooks adopted for Classes 9 to 12, session 2026-27', '{"id":"IN-UP-MANDATE-upmsp-ncert-textbooks-classes-9-12-2026-27","label":"UP Board (UPMSP) letters of 2026: 70 NCERT textbooks adopted for Classes 9 to 12, session 2026-27","sourceUrl":"https://upmsp.edu.in/Downloads/Notification_textbooks.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: UPMSP letter no. 316 of 31.01.2026 (headed ''revised''), pages 3 to 5 of the PDF; letter no. 04 of 04.04.2026, pages 6 to 8; letter no. 79 of 03.07.2026, pages 1 to 2. Price list: ''Shaikshik satra 2026-27 ki NCERT evam Parishad dwara vikasit pathyapustakon ke mulya'', 3 pages, https://upmsp.edu.in/Downloads/NCERT_and_Non_NCERT_Books_price_list.pdf (listed on the Board''s home page with the date 31-03-2026).. Both PDFs are scans of Hindi letters, so the drafter and the checker read them as page images. The 8-page file holds three letters: no. 79 of 3 July 2026 (pages 1 to 2), no. 316 of 31 January 2026 headed ''revised'' (pages 3 to 5) and no. 04 of 4 April 2026 (pages 6 to 8). The Board''s home page lists the file as a notice dated 03-07-2026. An earlier version of letter 316 probably exists and was not found. The ''36 subjects'' in the letters fits a count of class-by-subject pairs (4 subjects in Classes 9 and 10, 14 in Classes 11 and 12, so 4 times 2 plus 14 times 2). The 12 other books fit Hindi, Sanskrit and Urdu for Classes 9 to 12. The price list has 70 NCERT-titled books by the checker''s count. The letters do not state this, so please ask the Board to confirm. The letters name these subjects: Class 9 and 10 English, Science, Mathematics, Social Science; Class 11 and 12 English, Physics, Chemistry, Biology, Mathematics, History, Geography, Civics, Sociology, Economics, Business Studies, Accountancy, Psychology, Home Science. Computer is not in the price list, so the Board''s Computer syllabus has no NCERT book in this list. Class 9 editions: the price list names older Class 9 titles (Beehive, Moments, India and the Contemporary World-I, Contemporary India-I, Economics, Democratic Politics-I, and a science book listed only as ''Vigyan''). NCERT''s textbook page, read on 30 October 2026, lists new Class 9 books built on NCF-SE 2023 (Science ''Exploration'' and ''Anveshan'', Social Science ''Understanding Society: India and Beyond'' Parts I and II, Mathematics ''Ganita Manjari'', English ''Kaveri'', Hindi ''Ganga'') and no longer lists the older titles. NCERT''s advisory F.No.Secy/1-1/2026 of 17 March 2026 says the new Class 9 books are available from 2026-27 and that the existing Class 10 and 11 books stay in use in 2026-27. It does not mention Class 12. The Board''s price list is dated 31 March 2026, after that advisory, and still names the older Class 9 titles. The Board''s 2026-27 Class 9 syllabi also follow the older books (for example the four-book Social Science set). No document found shows which Class 9 edition UP schools receive in 2026-27, so that stays unverified. The Class 10 and 11 titles in the list agree with the advisory. The letters say copyright in the textbooks vests in the Board and warn of action under the Copyright Act and NCERT''s copyright conditions. This bears on the project''s open question about copyright in curriculum documents. History from news only: a PTI report of 6 June 2017 said the Board planned to move to NCERT books from 2018-19, Classes 10 and 12 first; the order was not found, and a web search summary of other reports suggests Classes 9 to 12 from 2018-19, which the checker could not open, so the 2018 start and the class split are unconfirmed. This record is AI-drafted and has not been checked by a subject expert. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"UPMSP letter no. 316 of 31.01.2026 (headed ''revised''), pages 3 to 5 of the PDF; letter no. 04 of 04.04.2026, pages 6 to 8; letter no. 79 of 03.07.2026, pages 1 to 2. Price list: ''Shaikshik satra 2026-27 ki NCERT evam Parishad dwara vikasit pathyapustakon ke mulya'', 3 pages, https://upmsp.edu.in/Downloads/NCERT_and_Non_NCERT_Books_price_list.pdf (listed on the Board''s home page with the date 31-03-2026).","description":"For the 2026-27 session the UP Board adopted 70 NCERT textbooks for Classes 9 to 12, along with 12 selected Hindi, Sanskrit and Urdu books. Government, aided and self-financed schools must teach from these Board-authorised books at fixed prices and may not push other books or guides, and the Board says it holds copyright in them. A letter of 4 April 2026 repeats the order, and one of 3 July 2026 refers back to both and adds book sale camps and online sales.","verificationStatus":"primary-source-confirmed","issuingBody":"Madhyamik Shiksha Parishad, Uttar Pradesh (UP Board), Prayagraj","mandateType":"standards-adoption","adoptionDate":"2026-01-31","dateGranularity":"day","statementText":"For the 2026-27 session the UP Board adopted 70 NCERT textbooks for Classes 9 to 12, along with 12 selected Hindi, Sanskrit and Urdu books. Government, aided and self-financed schools must teach from these Board-authorised books at fixed prices and may not push other books or guides, and the Board says it holds copyright in them. A letter of 4 April 2026 repeats the order, and one of 3 July 2026 refers back to both and adds book sale camps and online sales.","subject":"general","gradeFrom":9,"gradeTo":12,"topicTags":["ncert textbooks","textbook adoption","up board","classes 9 to 12","copyright","2026-27"]}', '2026-01-31'),
  ('924ec8a4-51bb-5499-b0bb-4694e0f1a707', 'uttar-pradesh-curriculum-repository', 'policy-timeline-event', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-EVENT-ncert-revised-textbooks-adopted-2023-24', 'Uttar Pradesh government: state schools to use NCERT''s revised, trimmed textbooks from 2023-24 (news report)', '{"id":"IN-UP-EVENT-ncert-revised-textbooks-adopted-2023-24","label":"Uttar Pradesh government: state schools to use NCERT''s revised, trimmed textbooks from 2023-24 (news report)","sourceUrl":"https://tribuneindia.com/news/up-schools-adopt-ncerts-revised-textbooks-minus-portions-about-mughal-courts-from-current-session-493853","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Tribune India and Careers360 reports of 3 to 4 April 2023 (PTI). NCERT, List of Rationalised Content in Textbooks for Class X, Science, Chapter 9, booklet page 19 (https://ncert.nic.in/pdf/BookletClass10.pdf). UPMSP home page link to https://ncert.nic.in/rationalised-content.php.. The adoption rests on news. The checker read the Tribune India report (PTI, Lucknow, 3 April 2023, updated 4 April): Deputy Chief Minister Brajesh Pathak said the state teaches from NCERT books and will follow the revised edition, and Additional Chief Secretary Deepak Kumar (basic and secondary education) confirmed the decision to PTI. It gives Class 12 history and political science examples only. It does not name the UP Board, any order or science. No official order was found. The Quint (3 April 2023) reports a denial by the state''s minister of state for secondary education, Gulab Devi, of plans to remove Mughal-history chapters, and quotes an unnamed senior education official saying the state is implementing the NCERT syllabus, so the reports of that week conflict on what the state changed. The evolution detail comes from NCERT''s own booklet ''List of Rationalised Content in Textbooks for Class X'', printed page 19 (PDF page 21). Science Chapter 9 ''Heredity and Evolution'' is renamed ''Heredity''. The listed drops are sections 9.3 (Evolution, including acquired and inherited traits), 9.4 (Speciation), 9.5 (Evolution and classification, including fossils and evolution by stages) and 9.6 (Evolution should not be equated with progress, including human evolution), plus four box items (Charles Darwin, origin of life on earth, how fossils form layer by layer, molecular phylogeny). The imprint page says May 2022, but that date does not date this entry. The copy archived on 17 June 2022 lists only Chapter 5 as dropped from Class X Science. The copy now on NCERT''s site (first archived 16 February 2023) adds Chapter 9, and its page footers carry a layout stamp of 27 December 2022. The Class VI, IX, XI and XII booklets carry May 2022 stamps. So the entry was added after June 2022, probably in December 2022, ahead of the 2023-24 session. Class XII: the Biology entry (printed pages 46 to 47) lists Chapters 1, 9, parts of 13 and 14, and 16 as dropped and has no entry for the Evolution chapter, which NCERT''s current Class 12 Biology book (12083, revised edition November 2022, reprinted January 2026) still carries as Chapter 6. A text search of the Class VI to XII booklets found no other organic-evolution entry (Class XI Geography drops part of ''Evolution of the Earth'', which is geology). NCERT''s current Class 10 Science book (1064, revised edition October 2022) has Chapter 8 ''Heredity'' with sections on variation and inheritance only. The UP Board''s 2026-27 syllabus (see the science record) matches. Reviewer: please compare this with the national record on NCERT''s rationalisation, which says evolution content was deleted nationally. The booklets show the deletion in Class 10 Science only. The UP Board home page links to NCERT''s rationalised-content page. This record is AI-drafted and has not been checked by a subject expert. A second AI reader corrected this record against the source (4 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"Tribune India and Careers360 reports of 3 to 4 April 2023 (PTI). NCERT, List of Rationalised Content in Textbooks for Class X, Science, Chapter 9, booklet page 19 (https://ncert.nic.in/pdf/BookletClass10.pdf). UPMSP home page link to https://ncert.nic.in/rationalised-content.php.","description":"PTI reported on 3 April 2023 that the Uttar Pradesh deputy chief minister and an additional chief secretary said state schools would follow NCERT''s revised, trimmed textbooks from the 2023-24 session. The reports give Class 12 history and political science as examples, and a state minister denied plans to remove history chapters from the state syllabus. NCERT''s own list for Class 10 Science drops the evolution sections from its heredity chapter.","verificationStatus":"secondary-source-only","slug":"ncert-revised-textbooks-adopted-2023-24","dateStart":"2023-04-03","dateGranularity":"day","eventType":"other","temporalStatus":"past-completed","topicTags":["ncert","rationalisation","evolution","heredity","textbook adoption","2023-24"]}', '2023-04-03'),
  ('f2623c05-53f0-5a84-a2f8-979628591986', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-upmsp-science-biology-classes-9-12-2026-27', 'UP Board (UPMSP) Science and Biology syllabus, Classes 9 to 12, session 2026-27: heredity and evolution', '{"id":"IN-UP-MANDATE-upmsp-science-biology-classes-9-12-2026-27","label":"UP Board (UPMSP) Science and Biology syllabus, Classes 9 to 12, session 2026-27: heredity and evolution","sourceUrl":"https://upmsp.edu.in/Downloads/Syllabus/Class12/153-Biology-Class-12.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: UPMSP Biology syllabus Class 12, session 2026-27, page 1, Unit 7 ''Genetics and Evolution'' (18 marks), items 4 to 6 (item 6 is Evolution). Also Science Class 10, page 1, Unit 2 item (viii) Heredity; Science Class 9, pages 1 to 2; Biology Class 11, page 1, Unit 1 Diversity in the Living World.. Read directly from the Board''s syllabus PDFs, which use an old Hindi font, so the AI reader read them as page images. Other files: https://upmsp.edu.in/Downloads/Syllabus/Class10/931-Science-Class-10.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class09/931-Science-Class-9.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class11/153-Biology-Class-11.pdf. The Class 12 evolution item lists origin of life, evidence from fossils, comparative anatomy, embryology and molecules, Darwin''s contribution, the modern synthetic theory, variation by mutation and recombination, natural selection and its types, gene flow and drift, the Hardy-Weinberg principle, adaptive radiation and human evolution. The AI reader could not open the state''s Class 6 to 8 science syllabus (see not_found), so the AI reader makes no claim about earlier classes. The syllabus gives topics only. The AI reader did not read the textbook the Board prescribes, so please check whether the Class 12 Biology book carries an evolution chapter. PDF file properties mention a gazette extra copy dated 07.12.2024 (High School) and 22.01.2025 (Intermediate); The AI reader did not find those gazettes, so the date of the revision is unconfirmed. Whether Biology is compulsory or an elective in Class 11 and 12 was not checked. This record is AI-drafted and has not been checked by a subject expert. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"UPMSP Biology syllabus Class 12, session 2026-27, page 1, Unit 7 ''Genetics and Evolution'' (18 marks), items 4 to 6 (item 6 is Evolution). Also Science Class 10, page 1, Unit 2 item (viii) Heredity; Science Class 9, pages 1 to 2; Biology Class 11, page 1, Unit 1 Diversity in the Living World.","description":"In the Board''s 2026-27 syllabi, Class 9 Science has no heredity or evolution content. Class 10 Science teaches heredity (Mendel''s work, inheritance of traits, a brief note on sex determination) and has no evolution unit. Class 11 Biology covers classification of living things. Class 12 Biology has a Genetics and Evolution unit worth 18 of 70 marks. It includes evidence for evolution, natural selection, drift, gene flow, the Hardy-Weinberg principle and human evolution.","verificationStatus":"primary-source-confirmed","issuingBody":"Madhyamik Shiksha Parishad, Uttar Pradesh (UP Board), Prayagraj","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"In the Board''s 2026-27 syllabi, Class 9 Science has no heredity or evolution content. Class 10 Science teaches heredity (Mendel''s work, inheritance of traits, a brief note on sex determination) and has no evolution unit. Class 11 Biology covers classification of living things. Class 12 Biology has a Genetics and Evolution unit worth 18 of 70 marks. It includes evidence for evolution, natural selection, drift, gene flow, the Hardy-Weinberg principle and human evolution.","subject":"science","gradeFrom":9,"gradeTo":12,"topicTags":["heredity","variation","evolution","natural selection","adaptive radiation","classification","biology syllabus"]}', ''),
  ('7e113713-0cd8-5137-a5e4-11298d2c5630', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-upmsp-social-science-civics-moral-education-2026-27', 'UP Board (UPMSP) Social Science, Civics and Moral Education syllabus, Classes 9 to 12, session 2026-27', '{"id":"IN-UP-MANDATE-upmsp-social-science-civics-moral-education-2026-27","label":"UP Board (UPMSP) Social Science, Civics and Moral Education syllabus, Classes 9 to 12, session 2026-27","sourceUrl":"https://upmsp.edu.in/Downloads/Syllabus/Class10/932-Social-Science-Class-10.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: UPMSP Social Science Class 10, 2026-27, pages 1 and 3 (Democratic Politics 2: power sharing, federalism, political parties); Social Science Class 9, page 3 (Democratic Politics 1: democracy, constitutional design, institutions, rights); Civics Class 11, pages 1 to 3 (Constitution at Work, Political Theory); Civics Class 12, pages 1 to 3; Moral, Yoga, Sports and Physical Education, Classes 9 and 10, page 1.. Read directly as page images. Other files: https://upmsp.edu.in/Downloads/Syllabus/Class09/932-Social-Science-Class-09.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class11/130-Civics-Class-11.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class12/130-Civis-Class-12.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class09/944-Moral-Sports-and-Physical-Education-Class-9.pdf and the Class 10 equivalent. The Class 9 and 10 courses follow the structure of the older NCERT four-book set (India and the Contemporary World, Contemporary India, Democratic Politics, Economics). Class 12 Civics covers world politics and politics in independent India, including the Emergency and regional movements. The Moral Education course for Class 10 also names inspiring figures such as Vivekananda, Gandhi and Nehru. A Class 9 objective speaks of respect and tolerance for all religions. News of June 2023 (not read in full) says eleven leaders'' biographies were added to Moral Education for Classes 9 to 12; The AI reader did not confirm that. The Class 6 to 8 social science syllabus was not found. News of 30 Nov 2023 describes an Anubhuti values curriculum for Classes 6 to 8, developed by a unit of SCERT; it is not part of this record. This record is AI-drafted and has not been checked by a subject expert. A second AI reader corrected this record against the source (1 point). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"UPMSP Social Science Class 10, 2026-27, pages 1 and 3 (Democratic Politics 2: power sharing, federalism, political parties); Social Science Class 9, page 3 (Democratic Politics 1: democracy, constitutional design, institutions, rights); Civics Class 11, pages 1 to 3 (Constitution at Work, Political Theory); Civics Class 12, pages 1 to 3; Moral, Yoga, Sports and Physical Education, Classes 9 and 10, page 1.","description":"The Board''s 2026-27 syllabi give Classes 9 and 10 a Social Science course in four parts (history, geography, democratic politics, economics), and democratic politics covers why democracy, how the Constitution was made, rights, power sharing and federalism. Class 11 Civics covers how the Constitution works and political ideas such as liberty, equality, justice and secularism, and Class 12 Civics covers world politics and politics in independent India. Moral education in Classes 9 and 10 adds human rights, child rights and respect for all religions.","verificationStatus":"primary-source-confirmed","issuingBody":"Madhyamik Shiksha Parishad, Uttar Pradesh (UP Board), Prayagraj","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"The Board''s 2026-27 syllabi give Classes 9 and 10 a Social Science course in four parts (history, geography, democratic politics, economics), and democratic politics covers why democracy, how the Constitution was made, rights, power sharing and federalism. Class 11 Civics covers how the Constitution works and political ideas such as liberty, equality, justice and secularism, and Class 12 Civics covers world politics and politics in independent India. Moral education in Classes 9 and 10 adds human rights, child rights and respect for all religions.","subject":"social-science","gradeFrom":9,"gradeTo":12,"topicTags":["democracy","constitution","rights","federalism","secularism","moral education","civics"]}', ''),
  ('2fdfa515-b8c0-51fa-aa7a-cdd29c5c548a', 'uttar-pradesh-curriculum-repository', 'institutional-mandate-record', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-MANDATE-upmsp-computer-syllabus-classes-9-12-2026-27', 'UP Board (UPMSP) Computer syllabus, Classes 9 to 12, session 2026-27: programming, AI, robotics and drones', '{"id":"IN-UP-MANDATE-upmsp-computer-syllabus-classes-9-12-2026-27","label":"UP Board (UPMSP) Computer syllabus, Classes 9 to 12, session 2026-27: programming, AI, robotics and drones","sourceUrl":"https://upmsp.edu.in/Downloads/Syllabus/Class10/941-Computer-Class-10.pdf","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Read in the primary document: UPMSP Computer syllabus, 2026-27: Class 10 page 1 (units 1 to 5); Class 9 page 1 (units 1 to 5); Class 11 page 1 (units 1 to 5); Class 12 page 1 (units 1 to 5).. Read directly as page images. Other files: https://upmsp.edu.in/Downloads/Syllabus/Class09/941-Computer-Class-9.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class11/144-Computer-Class-11.pdf, https://upmsp.edu.in/Downloads/Syllabus/Class12/144-Computer-Class-12.pdf. The Class 9 syllabus lists algorithms, flowcharts and pseudocode. The Class 10 file lists searching and sorting (linear and binary search, bubble and selection sort). The Class 11 AI unit names agents, natural language processing, robotics, expert systems, and classification and regression. The syllabus lists no modelling or simulation topic. The AI reader found no official statement on whether Computer is compulsory or an elective; the subject has its own code in the Board''s list, and education websites call it optional. Computer has no NCERT book in the Board''s 2026-27 price list. A news report of 8 May 2023 (Organiser, which the AI reader read through a fetch tool) says the Board revised the Class 9 to 12 computer syllabus then, dropping C++ and HTML and adding AI, drones and cryptocurrency; The AI reader did not confirm the revision date from an official page. This record is AI-drafted and has not been checked by a subject expert. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"UPMSP Computer syllabus, 2026-27: Class 10 page 1 (units 1 to 5); Class 9 page 1 (units 1 to 5); Class 11 page 1 (units 1 to 5); Class 12 page 1 (units 1 to 5).","description":"The UP Board''s 2026-27 Computer syllabus runs from Class 9 to 12. Class 9 covers number systems, logical operators, Linux, office tools, flowcharts and networks. Class 10 covers C programming with loops, arrays, strings, functions and pointers, plus units on artificial intelligence, drones and cyber security. Class 11 teaches Python, introductory AI, blockchain, the Internet of Things and cloud computing. Class 12 teaches Java, robotics and drone technology.","verificationStatus":"primary-source-confirmed","issuingBody":"Madhyamik Shiksha Parishad, Uttar Pradesh (UP Board), Prayagraj","mandateType":"curriculum-framework","adoptionDate":"2026","dateGranularity":"year","statementText":"The UP Board''s 2026-27 Computer syllabus runs from Class 9 to 12. Class 9 covers number systems, logical operators, Linux, office tools, flowcharts and networks. Class 10 covers C programming with loops, arrays, strings, functions and pointers, plus units on artificial intelligence, drones and cyber security. Class 11 teaches Python, introductory AI, blockchain, the Internet of Things and cloud computing. Class 12 teaches Java, robotics and drone technology.","subject":"computer-science","gradeFrom":9,"gradeTo":12,"topicTags":["programming","python","artificial intelligence","robotics","drones","cyber security","binary numbers"]}', ''),
  ('a136ec1a-a774-56ab-aa9a-fe42f626ef2d', 'uttar-pradesh-curriculum-repository', 'policy-timeline-event', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-EVENT-nep-2020-review-state-curriculum-framework-2023-08', 'Uttar Pradesh Chief Minister''s NEP 2020 review: composite schools and a state curriculum framework requested (August 2023)', '{"id":"IN-UP-EVENT-nep-2020-review-state-curriculum-framework-2023-08","label":"Uttar Pradesh Chief Minister''s NEP 2020 review: composite schools and a state curriculum framework requested (August 2023)","sourceUrl":"https://outlookindia.com/education/up-cm-adityanath-reviews-implementation-of-nep-2020-in-schools-news-307391","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Outlook India (PTI), 2 August 2023, updated 18 January 2024, full short article.. Rests on one PTI report that the AI reader read through a fetch tool; The AI reader found no order or press note from the state. The AI reader could not find any Uttar Pradesh state curriculum framework, any state statement on adopting NCF-SE 2023, or any SCERT Uttar Pradesh page on either (SCERT''s site would not open). Later items, all from news and none read in an official source: on 30 Nov 2023 the state announced an Anubhuti values curriculum for Classes 6 to 8 in about 45,000 upper primary schools, built by a unit of SCERT and described as in line with NEP 2020 (Free Press Journal, IANS); on 11 Aug 2024 PTI quoted the Chief Minister saying NCERT''s curriculum was in place for Classes 1 and 2; Free Press Journal of 13 Jan 2024 and a news item of 24 Oct 2025 report NCERT books adapted by SCERT and state institutes for Classes 1 and 2 (2024-25), Class 3 (2025-26) and Class 4 (2026-27); a minor outlet reported on 19 Jul 2026 that learning targets for Classes 3 to 5 would follow NCF, NCERT books and PARAKH. DNA India of 3 Nov 2022 (which the AI reader read) gave an earlier phased plan that would reach Classes 6 to 8 after 2024-25. The later reports show a slower pace, and nothing the AI reader found confirms NCERT books in Classes 5 to 8. One article on NCF-2023 training that came up in search is about Madhya Pradesh, so the AI reader did not use it. This record is AI-drafted and has not been checked by a subject expert. A second AI reader re-opened the source and confirmed it. Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"Outlook India (PTI), 2 August 2023, updated 18 January 2024, full short article.","description":"A PTI report of 2 August 2023 says Chief Minister Yogi Adityanath reviewed NEP 2020 work in schools with the basic, secondary and higher education departments. He asked for composite school complexes built from upgraded government schools, teacher awareness workshops in every district, vocational courses, and a state curriculum framework that includes Indian knowledge, local practices and history.","verificationStatus":"secondary-source-only","slug":"nep-2020-review-state-curriculum-framework-2023-08","dateStart":"2023-08","dateGranularity":"month","eventType":"other","temporalStatus":"past-completed","topicTags":["nep 2020","state curriculum framework","composite schools","vocational education","teacher workshops"]}', ''),
  ('35bd6a75-fd25-53cf-9583-e1f8260f8159', 'uttar-pradesh-curriculum-repository', 'policy-timeline-event', 'IN-UP', 'openlpm-starter-draft', 'IN-UP-EVENT-ai-for-all-vocational-classes-9-12-2026-03', 'Uttar Pradesh skill development mission: ''AI for All'' course announced for vocational Classes 9 to 12 (March 2026)', '{"id":"IN-UP-EVENT-ai-for-all-vocational-classes-9-12-2026-03","label":"Uttar Pradesh skill development mission: ''AI for All'' course announced for vocational Classes 9 to 12 (March 2026)","sourceUrl":"https://www.oneindia.com/lucknow/uttar-pradesh-to-introduce-mandatory-ai-training-for-class-9-12-students-in-vocational-schools-8039013.html","provenance":{"date":"2026-10-30","added_by":"claude-session","extracted_by":"llm","review_status":"author-draft","contributor_notes":"Not confirmed against a primary copy: Oneindia, 27 March 2026 (names the minister of state for vocational education and the mission director); Elets digitalLEARNING, 6 April 2026 (https://digitallearning.eletsonline.com/2026/04/over-2-lakh-up-students-to-receive-ai-training-under-skill-development-mission/).. Three news reports agree on the scale, the classes and the 2026-27 start: Oneindia (27 March 2026, naming Minister of State Kapil Dev Agarwal and Mission Director Pulkit Khare), Hindusthan Samachar (26 March 2026) and Elets digitalLEARNING (6 April 2026, which names no official and does not say the course is compulsory). The reports describe the course content only in general terms. The announcement rests on news. The UP Skill Development Mission''s own Project Praveen presentation (upsdm.gov.in, PDF properties dated 23 July 2026) has an ''AI for All'' slide saying 38,510 students completed an AI course in 2026-27, and the Mission''s home page has an ''AI For All'' button. These confirm that the course ran. They do not confirm that it is compulsory, that it lasts four hours, or the 2 lakh and 1,200 figures. No government order or press note was found. A May 2026 report found by search describes a separate free public ''AI for All'' online course announced by the Chief Minister on 13 April 2026; the checker did not open it, so please keep the two apart. Other items from news that were not made into records: on 19 Jan 2026 PTI-based coverage said the UP Board would make vocational education (including information technology) compulsory in Classes 9 and 11 from 2026; a report dated 17 Sep 2026 says the cabinet approved Rs 300 crore for smart classes and ICT labs in 14,429 primary schools run by the Basic Education Council, with no mention of coding or AI; a May 2026 item about industry-built robotics and AI labs in 600 secondary schools came only from a low-quality aggregator and was left out. These items were not re-checked. This record has no links to the models because the course content is not described. This record is AI-drafted and has not been checked by a subject expert. A second AI reader corrected this record against the source (2 points). Written in our own words. Not reviewed by an Indian curriculum expert."},"jurisdiction":"IN-UP","sourcePassage":"Oneindia, 27 March 2026 (names the minister of state for vocational education and the mission director); Elets digitalLEARNING, 6 April 2026 (https://digitallearning.eletsonline.com/2026/04/over-2-lakh-up-students-to-receive-ai-training-under-skill-development-mission/).","description":"In March 2026 the Uttar Pradesh government said a four-hour course called AI for All would be compulsory from the 2026-27 session for about 2 lakh students in Classes 9 to 12 in vocational courses at nearly 1,200 government secondary schools. It runs under the state skill development mission''s Project Praveen, and instructors take it first. The reports describe the content only in general terms, as customised modules for job roles such as IT, customer care, healthcare and tailoring.","verificationStatus":"secondary-source-only","slug":"ai-for-all-vocational-classes-9-12-2026-03","dateStart":"2026-03","dateGranularity":"month","eventType":"other","temporalStatus":"past-completed","topicTags":["artificial intelligence","vocational education","project praveen","skill development","2026-27"]}', '')
) AS v(id, repo_slug, record_type, jurisdiction, source_repo, source_record_id, title, content, event_date)
JOIN projects p ON p.slug = v.repo_slug
ON CONFLICT (source_repo, source_record_id) DO NOTHING;

-- ============================================================================
-- 2b. Corrections to earlier India records, found when the primary documents were read
-- ============================================================================

-- INLP-EVENT-ncert-rationalisation-evolution-deletion: the first version, written from news coverage, said evolution content was deleted nationally. NCERT's own lists and current books show a narrower change.
UPDATE curriculum_repository_records SET
  title = 'NCERT''s 2022-23 rationalisation removes the evolution sections from Class 10 Science; the Class 12 Biology Evolution chapter stays',
  content = content || jsonb_build_object('label', 'NCERT''s 2022-23 rationalisation removes the evolution sections from Class 10 Science; the Class 12 Biology Evolution chapter stays'::text, 'description', 'NCERT''s own list of rationalised content shows that the Class 10 Science chapter on heredity and evolution was renamed Heredity and lost its sections on evolution, speciation, evolution and classification (fossils) and human evolution. The Class 12 list has no entry for the Evolution chapter, and NCERT''s Class 12 Biology book (2026-27 reprint) still has Chapter 6, Evolution, on pages 110 to 126. Press coverage at the time described the removals more broadly. NCERT''s list was updated after June 2022 and the changes reached the textbooks in 2023-24.'::text, 'correctionNote', 'Corrected on 2026-10-30. The first version said NCERT deleted evolution and Darwin content nationally. Two AI readers compared that summary with NCERT''s own rationalisation lists and the current Class 10 and Class 12 books and found the change was narrower. No Indian curriculum expert has reviewed this correction.'::text, 'correctedOn', '2026-10-30')
WHERE source_repo = 'india-lpm' AND source_record_id = 'INLP-EVENT-ncert-rationalisation-evolution-deletion';

-- INLP-FINDING-karnataka-heredity-open-license-vs-ncert-default: the first version said the Class 10 Heredity chapter is openly licensed. The Creative Commons notice found covers KOER's own wiki pages, and the textbook chapter text is NCERT's.
UPDATE curriculum_repository_records SET
  title = 'KOER''s pages on Karnataka''s Class 10 Heredity chapter are CC BY-SA; no open licence was found for the textbook chapter text',
  content = content || jsonb_build_object('label', 'KOER''s pages on Karnataka''s Class 10 Heredity chapter are CC BY-SA; no open licence was found for the textbook chapter text'::text, 'summary', 'KOER, Karnataka''s open education wiki, publishes its own pages and uploads under CC BY-SA 4.0 unless a page says otherwise. Its page on the Class 10 Heredity chapter holds no chapter text. It links to a state textbook PDF whose licence is not stated, and to a teacher unit plan that falls under the wiki''s CC BY-SA default. The Class 10 Science book used in recent years carries NCERT''s chapter text, and NCERT''s books say all rights are reserved. The 2022 file also carries a ''Not to be republished'' mark. The openly licensed part is therefore KOER''s own material, and no open licence was found for the textbook text itself.'::text, 'correctionNote', 'Corrected on 2026-10-30. The first version said Karnataka''s Class 10 Heredity chapter is openly licensed. A second AI reader checked KOER''s pages, the state textbook publisher''s copyright page and the 2018 and 2022 Class 10 files, and found that the CC BY-SA notice covers KOER''s own wiki pages. Karnataka government sites refused connections, so the textbook publisher''s own copies could not be opened. No lawyer has reviewed this.'::text, 'correctedOn', '2026-10-30')
WHERE source_repo = 'india-lpm' AND source_record_id = 'INLP-FINDING-karnataka-heredity-open-license-vs-ncert-default';

-- INLP-EVENT-karnataka-koer-cc-by-sa-license: the first version said KOER hosts the state textbooks in full under CC BY-SA 4.0. The notice found is the footer of KOER's wiki pages and uploads.
UPDATE curriculum_repository_records SET
  content = content || jsonb_build_object('description', 'Karnataka Open Educational Resources (KOER), run with teachers of the Department of State Educational Research and Training, publishes its wiki pages and uploads under CC BY-SA 4.0 unless a page says otherwise. A 2021 legal-scholarship review (SpicyIP, Dhonchak) found this more permissive than NCERT''s own National Repository of Open Educational Resources. KOER links to textbook files hosted by the state textbook publisher and does not state a licence for them.'::text, 'correctionNote', 'Corrected on 2026-10-30. The first version said KOER hosts the state''s textbooks in full under CC BY-SA 4.0. A second AI reader found that the licence notice is the footer of KOER''s wiki pages and uploads. No lawyer has reviewed this.'::text, 'correctedOn', '2026-10-30')
WHERE source_repo = 'india-lpm' AND source_record_id = 'INLP-EVENT-karnataka-koer-cc-by-sa-license';

