-- ============================================================================
-- 4. Proposed links
-- ============================================================================
-- Rows are skipped when the part or the record is missing, or when the pair is already linked in any way.

-- bio-core-lpm-synth: 50 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-KA-UNIT-class10-science-heredity-and-evolution', 'proposed_relates_to', 'The chapter explains that a trait becomes common in a population when the frequency of the genes behind it changes across generations, and it separates survival advantage from chance (genetic drift). That matches this part''s focus on population-level change and on telling selection from drift.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-KA-UNIT-class10-science-heredity-and-evolution', 'proposed_relates_to', 'The Class 10 beetle story builds the whole mechanism: inherited colour variation, predation, unequal survival and a change in how common each colour is, with genetic drift added. Karnataka''s Class 8 chapter also teaches natural selection, so the state covers the idea inside the model''s Class 6 to 8 band and returns to it in Class 10.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'IN-KA-UNIT-class10-science-heredity-and-evolution', 'proposed_contrasts_with', 'Section 9.4 explains how beetle sub-populations separated by distance or a river drift apart through reduced gene flow, genetic drift and different selection until they cannot interbreed. In the Class 6, 8 and 10 science books checked, this appears only in Class 10. The model places it in Class 6 to 8. Classes 7 and 9 were not checked.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-KA-UNIT-class10-science-heredity-and-evolution', 'proposed_relates_to', 'Sections 9.5 and 9.6 trace relationships from shared features, use fossils and fossil dating, contrast a ladder with a branching tree, and say humans and chimpanzees share a common ancestor. A short box on molecular phylogeny compares DNA between species. This overlaps the part''s ancestry and fossil evidence. Students do not build a phylogeny, and extinction rates are not discussed.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-KA-UNIT-class8-science-evolution-of-life', 'proposed_relates_to', 'Darwin''s principles in the chapter cover variation among the young, overproduction, competition, survival of the better adapted and natural selection, in the same grade band as this part. The chapter does not describe a change in how common a trait is across a population, and it keeps the phrase survival of the fittest without defining fitness.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-KA-UNIT-class8-science-evolution-of-life', 'proposed_relates_to', 'The chapter names sudden genetic changes (mutation, from de Vries) as the source of variation that Darwin could not explain, and defers Mendel''s heredity to higher classes. This touches the part''s mutation point but does not introduce genes or alleles.'),
  ('70cf40f5-cb5d-508a-95dc-d18eaa465e94', 'IN-KA-UNIT-class8-science-evolution-of-life', 'proposed_relates_to', 'Weismann''s experiment on tailless rats shows that acquired characters are not inherited, and Class 10 repeats the point with starved beetles and tailless mice. The model asks children to tell inherited from acquired traits in Class 3 to 5. Whether Karnataka teaches this before Class 8 has not been checked.'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'IN-KA-UNIT-class6-science-habitats-and-adaptation', 'proposed_relates_to', 'The camel and fish examples show body features that help an organism live in its habitat, which matches the example in this part for Classes 1 and 2. Karnataka''s Class 6 chapter names the idea adaptation and separates it from short-term acclimatisation. Whether Classes 1 to 5 teach it first has not been checked.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-MH-MANDATE-scert-scf-school-education-2024-science', 'proposed_relates_to', 'Class 9 and 10 competencies ask students to analyse population-level effects of Mendel''s rules (C-4.4) and to look at allele frequency in a population when analysing natural selection (C-4.5). The model''s 9-12 part describes populations by allele frequencies and how they change. The framework gives one line each and does not mention drift.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-MH-MANDATE-scert-scf-school-education-2024-science', 'proposed_contrasts_with', 'DNA, genes and chromosomes first appear in the framework''s Class 9 and 10 competencies. None of the Class 6 to 8 science competencies mention them. The model teaches genes and alleles in the 6-8 band, so Maharashtra''s framework places this topic one stage later.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-MH-MANDATE-scert-scf-school-education-2024-science', 'proposed_contrasts_with', 'Natural selection appears in the framework only in the Class 9 and 10 competencies. The Class 6 to 8 science goals cover how scientific ideas change but name no mechanism of selection. The model builds a four-part selection mechanism in the 6-8 band.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution', 'proposed_contrasts_with', 'This Class 10 chapter gives natural selection its full treatment: survival of the fittest through competition, then three objections. It does not set out heritable variation and differential reproduction as separate steps. Class 7 has only a short Darwin box. The model builds a four-part mechanism in Classes 6 to 8.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution', 'proposed_relates_to', 'The chapter defines a species as organisms that produce fertile offspring and says geographical or reproductive isolation leads to new species. The model''s 6-8 part explains speciation as separated populations diverging until they cannot interbreed. This chapter is Class 10 and gives no example or mention of different selection pressures on separated populations.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution', 'proposed_relates_to', 'The chapter lists six kinds of evidence for evolution, including fossils dated with carbon-14 and shared bone structure, and gives a human evolution timeline. The model''s 9-12 part asks for phylogenies built from body and molecular evidence, and for extinction patterns. The chapter builds no family tree and has no molecular evidence.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-MH-UNIT-balbharati-science-technology-class-10-part-2-heredity-and-evolution', 'proposed_contrasts_with', 'The chapter covers DNA, genes, protein-making and mutation as a sudden change in a gene, in Class 10. It never uses the word allele and does not say mutations are undirected. The model covers genes, alleles and mutation as a random source of variation in Classes 6 to 8.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-MH-UNIT-balbharati-general-science-class-7-living-world-adaptations-and-classification', 'proposed_contrasts_with', 'The adaptation section describes slow changes in organs and life processes and never mentions variation among individuals. A short Darwin box says a new helpful trait that lets an organism survive is kept in the next generation, with nothing on populations or differential reproduction. The model teaches selection as a four-part population mechanism.'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'IN-MH-UNIT-balbharati-general-science-class-7-living-world-adaptations-and-classification', 'proposed_relates_to', 'The chapter''s examples link body features to habitat: fleshy stems in deserts, conical trees in snow, scales and fins on fish. The model''s K-2 part has children describe a feature that helps a familiar organism survive in its habitat. The content matches; this book teaches it in Class 7, and the AI reader did not read Classes 3 to 5.'),
  ('a4cd9b9e-d3a1-52bd-b76f-eb6173ab7259', 'IN-MH-UNIT-balbharati-general-science-class-7-living-world-adaptations-and-classification', 'proposed_relates_to', 'The chapter''s classification section says organisms of one species resemble each other and can reproduce among themselves, and teaches the groups from kingdom to species with two-part names. The model''s 3-5 part defines a species as organisms that can reproduce with one another. Maharashtra''s chapter sits in Class 7.'),
  ('ae85f5be-aead-5819-99df-8b3d431f79d1', 'IN-MANDATE-ncf-se-2023-four-stage-design', 'proposed_contrasts_with', 'The framework says concepts at Class 3 to 5 are mostly perceptual and practical, and that theory behind them waits for Class 6 onward. The model asks Class 3 to 5 children to explain a predicted shift in a population using inherited variation and differential survival, which is a theory-based explanation. Partners should say if this is too early.'),
  ('70cf40f5-cb5d-508a-95dc-d18eaa465e94', 'IN-MANDATE-ncf-se-2023-science-preparatory-world-around-us', 'proposed_contrasts_with', 'India''s Preparatory goals ask pupils to observe and describe differences among nearby plants, birds and animals (shape, sounds, food, growth, habitat). They mention no inherited versus acquired traits and no populations. The model''s 3-5 part teaches heritable traits and populations, so it asks for more than these goals.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-MANDATE-ncf-se-2023-science-middle-stage-goals', 'proposed_contrasts_with', 'NCF-SE''s Class 6 to 8 living-world goals cover diversity of living things, living versus non-living, and how organisms and surroundings depend on each other. They name no genes or inheritance. The model teaches genes, alleles and mutation here. NCF-SE first names heredity in its Class 9 and 10 competencies, though the Class 8 textbook already introduces genes.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-MANDATE-ncf-se-2023-science-middle-stage-goals', 'proposed_contrasts_with', 'The model builds the four-part natural selection mechanism at Classes 6 to 8. NCF-SE''s Middle Stage competencies contain no selection, fitness or evolution idea. Natural selection first appears as a competency for Classes 9 and 10, so India places it one stage later than the model.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-MANDATE-ncf-se-2023-science-secondary-stage-grades-9-10-goals', 'proposed_relates_to', 'A Class 9 and 10 competency asks pupils to analyse inheritance with Mendel''s laws and its effects at population level, using models or simulations. Another links natural selection to changes in allele frequency. The model''s 9-12 part also describes populations by allele frequency and how it changes.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', 'IN-MANDATE-ncf-se-2023-science-secondary-stage-grades-9-10-goals', 'proposed_relates_to', 'NCF-SE asks pupils to analyse evidence for biological evolution as a result of natural selection, in allele frequency and in organisms'' structure and function. The model''s 9-12 part asks pupils to weigh adaptation claims against alternatives such as drift. NCF-SE''s wording names neither drift nor alternative explanations.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-MANDATE-ncf-se-2023-science-secondary-stage-grades-9-10-goals', 'proposed_contrasts_with', 'India sets natural selection and its effect on allele frequency as a Class 9 and 10 competency, and lists natural selection among the generalisations for that stage. The model builds the full mechanism at Classes 6 to 8, so India places it a stage later.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-MANDATE-ncf-se-2023-science-secondary-stage-grades-9-10-goals', 'proposed_contrasts_with', 'NCF-SE''s Class 9 and 10 competency list describes heredity through DNA, genes and chromosomes, with variation as changes in DNA sequence. The model teaches genes and mutation at Classes 6 to 8. In the framework wording India places this a stage later, but the Class 8 textbook already introduces genes.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', 'IN-MANDATE-ncf-se-2023-biology-grades-11-12-illustrative-content', 'proposed_relates_to', 'NCF-SE''s Class 11 and 12 Biology content areas include how Darwin and Wallace developed the theory of evolution by natural selection, the modern synthesis, and an evolutionary framework for studying organisms. They are illustrative topics only. The model''s 9-12 part adds weighing adaptation claims against alternatives, which the framework does not list.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-MANDATE-ncf-se-2023-biology-grades-11-12-illustrative-content', 'proposed_relates_to', 'NCF-SE has Class 11 and 12 pupils study phylogenetics through the Tree of Life and the evolutionary history of the genus Homo. The model''s 9-12 part has pupils build a phylogeny from morphological and molecular evidence and tell background from mass extinction. NCF-SE lists topics and describes neither activity.'),
  ('aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'IN-UNIT-ncert-curiosity-class-6-science-scientific-method-and-adaptation', 'proposed_relates_to', 'Class 6 pupils learn that a camel''s humps and a deodar''s sloping branches are features that help living things survive in their habitat, and the book names these adaptations. The model has this idea at K-2. The Classes 3 to 5 framework goals already have pupils describe animals by habitat, and Classes 1 to 5 textbooks were not checked.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-UNIT-ncert-curiosity-class-6-science-scientific-method-and-adaptation', 'proposed_contrasts_with', 'The Class 6 chapter defines adaptation as a feature that helps survival in a place. It does not say features are inherited or that survivors leave more offspring. The model''s 6-8 part builds natural selection from variation, heritability and differential reproduction, and defines fitness by reproductive success.'),
  ('76c205d2-33d4-5532-ba5a-cab715380b5e', 'IN-UNIT-ncert-curiosity-class-6-science-scientific-method-and-adaptation', 'proposed_relates_to', 'Class 6 pupils collect plants and animals on a nature walk, group them by shared features, and compare their grouping criteria with other groups. The model has a similar sorting task at K-2. The Classes 3 to 5 framework goals already ask pupils to describe plant and animal diversity, and Classes 1 to 5 textbooks were not checked.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-UNIT-ncert-curiosity-class-8-science-testing-ideas-and-genes-and-variation', 'proposed_relates_to', 'Class 8 Chapter 13 says genes carry instructions from parents to offspring, that two parents'' instructions mix in sexual reproduction, and that small changes in the instructions can arise. The model''s 6-8 part teaches genes, alleles and mutation as a random source of variation. The chapter names no alleles or mutation.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-UNIT-ncert-curiosity-class-8-science-testing-ideas-and-genes-and-variation', 'proposed_contrasts_with', 'The chapter says small changes can help an organism survive in a new environment and add up over generations, citing camels and antibiotic-resistant bacteria. It gives no steps for differential reproduction, and ''developed humps'' can read as need-driven. Chapter 3 shows resistant bacteria taking over in an infographic. The model avoids need-based wording.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-UNIT-ncert-exploration-class-9-science-variation-and-biodiversity', 'proposed_contrasts_with', 'Section 12.2 of the Class 9 book says small differences between individuals changed survival and reproduction and, over many generations, produced new forms of life. That covers variation, differential survival and change over time in two sentences, without the term natural selection. The model builds this at 6-8; India places it at Class 9.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-UNIT-ncert-exploration-class-9-science-variation-and-biodiversity', 'proposed_relates_to', 'Chapter 12 says organisms with similar features or similar DNA are considered to share ancestors, groups organisms into kingdoms, and notes ancient cyanobacteria fossils as early evidence of life. The model''s 9-12 part builds a phylogeny from morphological and molecular evidence. The chapter states the principle but sets no tree-building task.'),
  ('ae85f5be-aead-5819-99df-8b3d431f79d1', 'IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics', 'proposed_relates_to', 'Class 10 Chapter 7 uses a warming-water example in which heat-resistant bacteria survive and grow while most die. The model asks pupils to predict which variant becomes more common in a simple scenario at 3-5. The Class 8 book has a similar resistant-bacteria picture, and neither textbook asks pupils to predict.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics', 'proposed_contrasts_with', 'Class 10 Chapter 8 says the environment selects among variants and that this underlies evolution, then refers to later sections this edition lacks, so the book gives only part of the mechanism. The model teaches all four components at 6-8. India''s version is partial and comes at Class 10.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics', 'proposed_contrasts_with', 'CBSE''s Class 10 syllabus repeats the NCF-SE competency on allele frequency in populations, but its topic list and the textbook chapter contain no population genetics. The model''s 9-12 part has pupils describe populations by allele frequency.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-UNIT-ncert-class-10-science-heredity-and-cbse-class-10-evolution-topics', 'proposed_contrasts_with', 'CBSE lists fossils, speciation, tracing evolutionary relationships and human evolution as Class 10 topics assessed only formatively, and says Heredity and Evolution is not assessed in the year-end exam. The textbook chapter has no section on them. The model''s 9-12 part builds evidence and deep time into its core content.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'proposed_relates_to', 'The chapter explains the Hardy-Weinberg principle, names gene flow, genetic drift, mutation, recombination and selection as factors that change allele frequencies, and reads departures from equilibrium as evolutionary change. The model''s 9-12 part has pupils describe populations by allele frequency and tell selection from drift.'),
  ('b8bf5ec4-fe31-593a-8177-15b8109517b4', 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'proposed_relates_to', 'The chapter sets natural selection beside gene flow, genetic drift and the founder effect as causes of change, and asks pupils to explain antibiotic resistance with Darwinian selection. The model''s 9-12 part has pupils weigh adaptation claims against drift and other alternatives. The chapter has no exercise comparing them for one trait.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'proposed_contrasts_with', 'Chapter 6 lays out Darwin''s argument in full: limited resources, heritable variation among individuals, competition, and more offspring for those better suited, so the population changes. The model builds the same four-part mechanism at 6-8. India teaches the full argument at Class 12.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'proposed_relates_to', 'The chapter covers evidence for evolution from fossils, comparative anatomy and comparative biochemistry, adaptive radiation, convergent evolution and human evolution. The model''s 9-12 part builds phylogenies from morphological and molecular evidence. The chapter has no tree-building task and does not separate background from mass extinction.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'IN-UNIT-ncert-class-12-biology-evolution-chapter-and-cbse-unit-vii', 'proposed_contrasts_with', 'Class 12 explains that a drifted or founder population can differ enough to become a different species, and that selected mutations over generations can result in speciation. The model teaches how separated populations become new species at 6-8. CBSE also lists Speciation among Class 10 formative-only topics, with no Class 10 textbook section behind it.'),
  ('4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'IN-UP-MANDATE-upmsp-science-biology-classes-9-12-2026-27', 'proposed_contrasts_with', 'In the Board''s Class 9 to 12 syllabi, natural selection first appears in Class 12 Biology, inside the Genetics and Evolution unit. Class 10 has heredity but no evolution unit. The model builds the four-part selection mechanism at Class 6 to 8. UP''s Class 6 to 8 syllabus was not found.'),
  ('6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'IN-UP-MANDATE-upmsp-science-biology-classes-9-12-2026-27', 'proposed_relates_to', 'The Class 12 evolution item lists the Hardy-Weinberg principle, gene flow and genetic drift next to natural selection. The model''s Class 9 to 12 part asks students to describe populations by allele frequency and to tell selection from drift. The topics line up closely. The syllabus gives topics only.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'IN-UP-MANDATE-upmsp-science-biology-classes-9-12-2026-27', 'proposed_relates_to', 'The Class 12 evolution item names four kinds of evidence (fossils, comparative anatomy, embryology, molecules) and human evolution. The model''s part uses morphological and molecular evidence to build a phylogeny and also covers mass extinction. The UP syllabus lists no phylogeny task and no extinction topic.'),
  ('8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'IN-UP-MANDATE-upmsp-science-biology-classes-9-12-2026-27', 'proposed_contrasts_with', 'In the Board''s syllabi, Mendel and sex determination come in Class 10, and mutation and recombination as sources of variation come in Class 12. The model introduces genes, alleles and mutation at Class 6 to 8. UP''s own Class 6 to 8 syllabus was not found.'),
  ('ca152c60-d9a5-509f-afdb-e2e7bdf983b4', 'INLP-EVENT-ncert-rationalisation-evolution-deletion', 'proposed_contrasts_with', 'NCERT''s own list of dropped content removes the speciation section from Class 10 Science. This part teaches speciation at Classes 6 to 8. The Class 12 Biology book still has a full Evolution chapter, so speciation remains in NCERT''s books only at that later stage.'),
  ('60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'INLP-EVENT-ncert-rationalisation-evolution-deletion', 'proposed_relates_to', 'NCERT''s list drops the Class 10 sections on fossils and on human evolution. The Class 12 Biology book keeps its Evolution chapter. This part expects fossil and molecular evidence at Classes 9 to 12, so the age range overlaps and the difference is which classes keep the topic.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- interdisciplinary-lpm-synth: 14 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-KA-UNIT-class8-social-science-sociology-social-institutions', 'proposed_relates_to', 'The chapter treats institutions as lasting structures with rules that carry knowledge, customs and values from one generation to the next, and it separates written from unwritten rules. This fits the part''s aim of seeing culture as transmitted and institutions as stable structures. It folds customs into institutions and does not contrast an institution with a norm.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-MH-MANDATE-scert-scf-school-education-2024-social-science', 'proposed_relates_to', 'Class 6 to 8 goals ask students to study how social, cultural and political institutions work and to value India''s cultural heritage and traditions. The model''s 6-8 part presents culture as transmitted practice and institutions as stable rule-based structures. The two overlap on institutions and on cultural continuity.'),
  ('5e4cdc6e-5c25-5f21-a833-4c0859a609da', 'IN-MANDATE-ncf-se-2023-interdisciplinary-areas', 'proposed_relates_to', 'The framework adds a dedicated interdisciplinary area at Class 9 and wants students to use methods from more than one discipline on the same problem. This strand has students meet biological and cultural cases early and reserves the full multi-disciplinary comparison for Class 9 to 12. The two share the stage at which integration becomes explicit; their topics differ.'),
  ('6315aad7-35b7-52dc-9dd2-1b82d707a768', 'IN-MANDATE-ncf-se-2023-interdisciplinary-areas', 'proposed_contrasts_with', 'For Classes 6 to 8 the framework builds interdisciplinary goals into the curricular areas and sets no separate area (p. 365). This model part gives Class 6 to 8 students an explicit cross-system task: apply one general pattern to a biological and a cultural case side by side. Partners can say whether this fits Indian timetables.'),
  ('a1bc92d8-3730-53b8-a059-f3999e4387cf', 'IN-MANDATE-ncf-se-2023-interdisciplinary-areas', 'proposed_relates_to', 'The World Around Us asks Class 3 to 5 pupils to describe cultural diversity around them, such as food, clothing and festivals, and to link changes in family life to elders'' stories about work and food. Its content principles add comparison across communities. The model part has pupils compare the practices of two communities and tools that change over time.'),
  ('8363df74-ecd8-54e9-82f1-e93623f9995c', 'IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning', 'proposed_relates_to', 'The framework says new content should start from experiences children already know, and its play examples include retrying a block tower with a wider base and starting a puzzle from its border pieces. The model part has children use something known, such as a story or game, to work out something new, including with building blocks.'),
  ('9fc65a59-5de1-51ad-ad30-a9c0faca177a', 'IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning', 'proposed_relates_to', 'Foundational competencies ask children to respond to norms in the classroom and school, cooperate with other children, and use simple tools in daily life. The model part asks them to describe a shared rule of a family or class and name a tool and what it helps people do. The framework asks for the behaviour; the model adds description.'),
  ('06af1b7b-19bb-5d77-87ac-52f34650f556', 'IN-MANDATE-ncf-se-2023-science-aims-and-inquiry', 'proposed_relates_to', 'NCF-SE names testing hypotheses, using evidence and accepting that scientific knowledge changes with new evidence among its aims, and asks teaching to follow the full cycle from question to revised conclusion. This matches the strand''s theme of improving ideas by testing them. NCF-SE does not mention analogy or starting from similar known cases.'),
  ('a64224d1-ac36-5b1c-b475-3c5af3aa4656', 'IN-MANDATE-ncf-se-2023-science-preparatory-world-around-us', 'proposed_relates_to', 'For Classes 3 to 5, India''s goals ask pupils to run simple inquiries and become familiar with the scientific method. The content advice suggests growing seeds in different soils and sunlight and comparing results. This is a hands-on form of testing a guess, which the model''s 3-5 part also targets, without its breeder example.'),
  ('ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 'IN-MANDATE-ncf-se-2023-biology-grades-11-12-illustrative-content', 'proposed_relates_to', 'NCF-SE says Class 11 and 12 pupils should see that scientific theories take time to develop and that their historical context matters, and it cites Darwin and Wallace''s work as a case. The model''s 9-12 part uses Darwin''s notebooks as a history-of-science case. NCF-SE names no analogy-based discovery.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-MANDATE-ncf-se-2023-social-science-aims-and-goals', 'proposed_relates_to', 'A Middle Stage goal asks students to spot beliefs, relationships and practices that continue despite large social change, and another asks how institutions affect groups. This matches the model''s view of culture as shared practice that outlasts any one person and of institutions as stable structures.'),
  ('a1bc92d8-3730-53b8-a059-f3999e4387cf', 'IN-UNIT-ncert-class6-unity-in-diversity', 'proposed_relates_to', 'Students compare food, clothing and festivals across regions and say what is shared and what differs, for example staple grains cooked in many ways. This matches the model''s task of comparing the practices of two communities and naming a similarity and a difference. The textbook is for Class 6. NCF-SE lists differing community practices for Classes 3 to 5.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-UNIT-ncert-class6-unity-in-diversity', 'proposed_relates_to', 'The chapter shows stories, festivals and dress passed on across regions for centuries, including tribal versions of the epics that are told orally. This fits the model''s description of culture as socially transmitted knowledge and practice that outlasts any one person. The chapter does not discuss institutions.'),
  ('ad0173a4-5c64-5d05-96ac-2b61810c4153', 'IN-UNIT-ncert-class6-grassroots-democracy-governance-and-local-government', 'proposed_relates_to', 'The chapter moves from household and school rules to laws and a government with three organs and three levels. This supports the model''s difference between an institution, a stable rule-based structure, and an informal norm. The chapter does not name informal norms as a separate group.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- social-core-lpm-synth: 23 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('9ef944f3-b11a-5327-9082-b53ba736a834', 'IN-KA-UNIT-class8-social-science-sociology-social-institutions', 'proposed_relates_to', 'The chapter says members who break an institution''s rules can be excluded, and that schools correct behaviour through reprimand, punishment or legal action. This overlaps the part''s contrast between norms kept up by peers and rules enforced by an authority, though the chapter does not name peer approval.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-KA-UNIT-class8-social-science-sociology-social-institutions', 'proposed_contrasts_with', 'The chapter already sorts rules into written ones (courts, schools, governments) and unwritten ones (customs, traditions) in Class 8. The model asks students to sort constraints into formal institutions and informal norms in Class 9 to 12 and to trace incentives, which the chapter does not do.'),
  ('c4836b7e-c2ac-5eda-9368-08e410453278', 'IN-MH-MANDATE-scert-scf-foundational-stage-2024', 'proposed_relates_to', 'The framework asks children aged 3 to 8 to understand the social rules of their school and class and to behave by them, and to work with other children. The model''s K-2 part has children name their groups and say what a rule asks of people. Both treat rules as something learned in class.'),
  ('fd772a6a-0dd8-5410-96c5-79f75443183c', 'IN-MH-MANDATE-scert-scf-school-education-2024-social-science', 'proposed_relates_to', 'Class 6 to 8 goals ask students to study how geography, climate and resources differ across regions, how diverse cultures coexist, and where inequality and prejudice come from. The model''s 6-8 part has students explain why two societies differ using geography, history and institutions. The competencies the AI reader read do not set two societies side by side.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-MH-MANDATE-scert-scf-school-education-2024-social-science', 'proposed_relates_to', 'Class 9 and 10 goals have students study the Constitution, democratic government and the work of non-government groups in a democracy. The model''s 9-12 part sorts constraints into formal institutions and informal norms. The framework goals cover the formal side in detail and say little about informal norms.'),
  ('c4836b7e-c2ac-5eda-9368-08e410453278', 'IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning', 'proposed_relates_to', 'A Foundational competency has children start to see themselves as belonging to a family and community, and another has them respond to norms in the classroom and school. The model part asks children to name groups they belong to and say what a rule asks. The framework stops at recognising and following; the model adds saying.'),
  ('f7608bc0-18ff-52e5-8238-ac0220214ec9', 'IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning', 'proposed_relates_to', 'The framework lists cooperative behaviour with other children as a competency, and its example of what a teacher can observe is a child sharing toys and taking turns. The model part asks children to take turns in a game and say why turns are fair. The framework does not ask for the explanation.'),
  ('fd772a6a-0dd8-5410-96c5-79f75443183c', 'IN-MANDATE-ncf-se-2023-social-science-aims-and-goals', 'proposed_relates_to', 'NCF-SE says social life arises from historical, geographical, cultural, economic and political factors together. Middle Stage goals ask students to link livelihood patterns to landforms, resources and climate, and to analyse past changes and what continued. This is near the model''s task of explaining why societies differ from several causes. The framework does not ask students to compare two societies.'),
  ('504c7645-bc71-5a81-a114-cd2d598d1621', 'IN-MANDATE-ncf-se-2023-social-science-aims-and-goals', 'proposed_relates_to', 'The framework says social science is interpretive: the same evidence can support different readings, and students should meet several well-evidenced accounts. Secondary goals include tracing continuity and change across world history. This lines up with the model''s task of judging two explanations of a large-scale change against the same evidence.'),
  ('f21b382b-ed4a-5e4e-b69b-d603834fbbe9', 'IN-UNIT-ncert-class6-family-and-community', 'proposed_relates_to', 'In Chapter 9, each family member has a role and duty, students compare who does which task at home, and they ask whether any rule is unfair to some members. This matches the model''s tasks on roles in groups and why rules differ. The textbook is for Class 6, and NCF-SE also covers family roles in Classes 3 to 5.'),
  ('2de4fac1-1590-5260-a501-d040c57c2acf', 'IN-UNIT-ncert-class6-family-and-community', 'proposed_relates_to', 'The chapter says communities in many villages and tribal areas agreed rules on shared water, grazing land and forest produce, and that each family then has duties or the community cannot run smoothly. This is a shared-resource arrangement. The chapter does not discuss people who take without contributing.'),
  ('3d964122-338c-548e-882b-d833d2ec4209', 'IN-UNIT-ncert-class6-family-and-community', 'proposed_relates_to', 'The chapter defines cooperation as working together and gives unpaid help as examples, such as the Bhil halma tree planting and food given out during the 2015 Chennai floods. It explains giving through duty and care, which fits the model''s question of why people cooperate, though it names no incentive or trust.'),
  ('aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', 'IN-UNIT-ncert-class6-unity-in-diversity', 'proposed_relates_to', 'The chapter follows the Panchatantra from its Sanskrit origin to about 200 adaptations in more than 50 languages, reaching Southeast Asia, the Arab world and Europe, and maps one harvest festival under different regional names. This matches tracing a practice from where it began to where it is now. The chapter does not name who carried the stories.'),
  ('9ef944f3-b11a-5327-9082-b53ba736a834', 'IN-UNIT-ncert-class6-grassroots-democracy-governance-and-local-government', 'proposed_relates_to', 'The chapter starts with rules at home, in school and on the road, then shows that a society needs laws made by an assembly, carried out by officials and judged by courts. This gives students a case of rules enforced by an authority. It does not set these against norms enforced by peers.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-UNIT-ncert-class6-grassroots-democracy-governance-and-local-government', 'proposed_contrasts_with', 'The Class 6 textbook describes three organs of government, three levels of government and local bodies. The model puts formal institutions at 9-12 and asks students to sort formal and informal constraints and trace changed incentives, which this chapter does not ask. NCF-SE names the Panchayat for Classes 3 to 5, so the stage difference is partial.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-UNIT-ncert-class9-governance-and-public-policy', 'proposed_relates_to', 'The chapter separates government, the institutions that hold authority, from governance, which also includes citizens, media, civil society and private bodies. This gives Class 9 students material for contrasting formal institutions with wider participation, which is near the model''s 9-12 part. The chapter does not discuss informal norms.'),
  ('504c7645-bc71-5a81-a114-cd2d598d1621', 'IN-MANDATE-cbse-2026-27-sociology-classes-11-12', 'proposed_relates_to', 'Class 11 has a unit on social change covering types, causes and consequences. Class 12 has units on structural and cultural change that name colonialism, industrialisation, urbanisation and reform movements. The syllabus also lists three classical thinkers: Marx, Durkheim and Weber. It gives topics only, so the fit with weighing explanations against one body of evidence is partial.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-MANDATE-cbse-2026-27-sociology-classes-11-12', 'proposed_relates_to', 'Class 11 units on status and role, social control and social institutions (family, politics, religion, education) give the vocabulary for sorting constraints into formal institutions and informal norms. The syllabus lists topics only and does not say how incentives change when an institution changes.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-MANDATE-cbse-2026-27-political-science-classes-11-12', 'proposed_relates_to', 'Class 11 covers the executive, legislature, judiciary, federalism and local governments as working institutions, with a chapter on the Constitution''s philosophy. This gives students the formal-institution side of the model''s 9-12 part. The syllabus does not mention informal norms.'),
  ('1d8ecb11-c3b4-57b0-9a0f-b32667147fea', 'IN-EVENT-ncert-2022-rationalised-content-democracy-movements-and-group-conflict-topics', 'proposed_contrasts_with', 'NCERT''s Class 12 psychology list drops cooperation and competition, inter-group conflict and conflict resolution strategies. The model''s central strand teaches cooperation and conflict at every grade band. So this list removes one place where India''s national textbooks taught the same topics in senior school.'),
  ('9ef944f3-b11a-5327-9082-b53ba736a834', 'IN-UNIT-ncert-class8-part2-judiciary-and-citizenship-rights-and-duties', 'proposed_relates_to', 'Chapter 5 sets a case where classmates threaten to exclude a student who skips a march, and says rights are protected by law while duties are moral and social responsibilities. This relates to the model''s task of telling peer-enforced norms from rules enforced by an authority. The chapter asks which right or duty applies. It does not ask who enforces.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-UNIT-ncert-class8-part2-judiciary-and-citizenship-rights-and-duties', 'proposed_relates_to', 'Chapter 4 describes courts and ways to settle disputes. Chapter 5 says rights are protected by law while duties are moral and social responsibilities that may bring no legal action. This gives material for separating legally backed rules from social expectations. The textbook is for Class 8, one band below the model''s 9-12 part.'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', 'IN-UP-MANDATE-upmsp-social-science-civics-moral-education-2026-27', 'proposed_relates_to', 'Class 11 Civics covers the executive, legislature, judiciary, federalism and local government, and Class 9 covers how institutions work. These are formal institutions. The syllabus lists no informal norms, which the model''s Class 9 to 12 part sets against them.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- computational-core-lpm-synth: 21 proposals
INSERT INTO curriculum_repository_links (project_id, data_object_id, repository_record_id, relation_type, rationale)
SELECT o.project_id, o.id, r.id, v.relation_type, v.rationale
FROM (VALUES
  ('528aba11-45e9-5ec4-b5da-4ddf071ff6a2', 'IN-MH-MANDATE-scert-scf-foundational-stage-2024', 'proposed_relates_to', 'One framework competency (C-8.1) has children separate objects into groups and subgroups using more than one property. Another (C-7.1) has them observe differences between objects in different groups and how the objects relate. The model''s K-2 part has children sort by a property. The pages read say nothing about labelling groups with a word or picture.'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', 'IN-MH-MANDATE-scert-scf-school-education-2024-stages-and-subjects', 'proposed_contrasts_with', 'The framework''s subject tables for Classes 3 to 10 list no separate computing subject. The model assumes algorithms and programs are taught as a strand across K-12. In Maharashtra the related content the AI reader found sits inside Mathematics and Vocational Education from Class 6 (see the Class 6 record).'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 'IN-MH-MANDATE-balbharati-class-6-2026-computational-thinking-and-scratch', 'proposed_relates_to', 'The Class 6 Mathematics book lists a goal naming decomposition and algorithms, with a competency on restating problems as ordered steps. The model''s 6-8 part has students split a problem into parts and write a function for each. The lessons the book cites cover number patterns and ways of showing data, with no function or testing task.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-MH-MANDATE-balbharati-class-6-2026-computational-thinking-and-scratch', 'proposed_relates_to', 'A Class 6 Scratch project, optional in the book''s machines-and-materials group, explains a program as step-by-step instructions run in order. Its game checklist covers if-else conditions, loops and variables, and it asks students to find bugs. The model''s 3-5 part builds a program with a sequence, a loop and a condition. Earlier classes were not read.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 'IN-MANDATE-ncf-se-2023-maths-ct-competencies-by-stage', 'proposed_relates_to', 'Middle Stage goal CG-8 names decomposition and asks students to recast problems as ordered steps (p. 256). It does not name writing functions or test cases, which this model part includes. The match covers splitting problems and ordering steps only.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', 'IN-MANDATE-ncf-se-2023-maths-ct-competencies-by-stage', 'proposed_contrasts_with', 'For Classes 6 to 8, competency C-8.2 asks students to devise and follow algorithms while working towards an understanding of their correctness, effectiveness and efficiency (p. 256). This model asks students to argue correctness and compare efficiency only at Classes 9 to 12. For Classes 9 and 10 the framework lists algorithmic problem solving only.'),
  ('f95b2dff-2e43-597e-b8c6-a1857c0f60c7', 'IN-MANDATE-ncf-se-2023-maths-ct-competencies-by-stage', 'proposed_relates_to', 'The stage overview (p. 252) puts data handling in the Preparatory Stage. The only data competency, CG-5 with tables, graphs, mean, median and mode, sits at Classes 6 to 8 (p. 256). This model puts recording and charting at Classes 3 to 5. Partners should check which Class 3 to 5 books cover it.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-MANDATE-ncf-se-2023-maths-ct-competencies-by-stage', 'proposed_contrasts_with', 'The framework first names iteration and logical operations as programmatic thinking at the Middle Stage (C-8.1) and names no programming idea for Classes 3 to 5. This model has children build a program with a sequence, a loop and a condition at Classes 3 to 5.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-MANDATE-nep-2020-coding-and-computational-thinking', 'proposed_contrasts_with', 'NEP 2020 says activities involving coding begin at the Middle Stage (para 4.25), which is Classes 6 to 8. This model has children build a program with a sequence, a loop and a condition at Classes 3 to 5. The policy names no programming idea, so the comparison is about stage only.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-MANDATE-cbse-ct-ai-curriculum-classes-3-5-2026', 'proposed_relates_to', 'Class 3 to 5 outcomes ask children to follow multi-step rules and well-defined conditions on grids, sequences and ordered events, mostly on paper. Only competency C-6 names block-based coding, and loops and conditions are not named as programming ideas. The match is to the step-following side of this part.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 'IN-MANDATE-cbse-ct-ai-curriculum-classes-6-8-2026', 'proposed_relates_to', 'Decomposition is a named skill in the Class 6, 7 and 8 outcomes, and Class 7 adds creating or analysing procedural steps. The curriculum text names no functions, test cases or written specifications, which this model part includes. The overlap is splitting problems and ordering steps.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', 'IN-MANDATE-cbse-ct-ai-curriculum-classes-6-8-2026', 'proposed_contrasts_with', 'Competency C-2 for Classes 6 to 8 asks students to devise and follow algorithms while considering their correctness, effectiveness and efficiency, and Class 8 outcomes add optimisation problems. This model holds arguing correctness and comparing efficiency until Classes 9 to 12.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'IN-MANDATE-cbse-ct-ai-curriculum-classes-6-8-2026', 'proposed_contrasts_with', 'India introduces supervised, unsupervised and reinforcement learning in Class 6, and classification, regression and clustering in Class 7, with hands-on practice on a small dataset. Class 8 adds no-code AI tools. This model puts machine learning at Classes 9 to 12. The Indian syllabus has no comparison with search or distributed systems.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'IN-UNIT-ncert-ct-ai-module-grades-9-12-2026', 'proposed_relates_to', 'Unit 2 separates rule-following automation from systems that learn from examples, and covers supervised, unsupervised and reinforcement learning, a nearest-neighbour example and overfitting (pp. 13-31). It does not compare learning with search on an objective or with distributed systems, which this model part also does.'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', 'IN-MANDATE-cbse-computer-science-informatics-practices-classes-11-12-2026-27', 'proposed_contrasts_with', 'Class 11 Computer Science teaches binary, octal and hexadecimal number systems with conversions, and the ASCII, ISCII and Unicode encodings (Unit 1, pp. 1-2). This model teaches encoding at Classes 6 to 8. CBSE''s Class 8 thinking outcomes already mention binary among number systems, so this syllabus is where the topic becomes a unit of its own.'),
  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', 'IN-MANDATE-cbse-computer-science-informatics-practices-classes-11-12-2026-27', 'proposed_contrasts_with', 'Class 11 Unit 2 lists decomposition, testing and debugging among its problem-solving steps, and Class 12 Unit 1 lists user-defined functions with parameters and return values. This model puts decomposition, functions and test cases at Classes 6 to 8. CBSE''s Classes 6 to 8 outcomes already name decomposition, so the later placement applies to functions and testing.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-MANDATE-cbse-computer-science-informatics-practices-classes-11-12-2026-27', 'proposed_contrasts_with', 'Class 11 Unit 2 is where this syllabus first lists conditional statements and for and while loops, written in Python. This model has children build a program with a sequence, a loop and a condition at Classes 3 to 5. CBSE''s Classes 3 to 5 curriculum names only block-based coding.'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', 'IN-MANDATE-cbse-computer-science-informatics-practices-classes-11-12-2026-27', 'proposed_contrasts_with', 'The Class 11 and 12 syllabus covers algorithms with flowcharts and pseudocode, linear search and stacks. It lists no argument for why an algorithm is correct and no comparison of how the steps grow with input size, which this model part asks for. The topic is left out.'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', 'IN-MANDATE-cbse-ai-417-class-10-and-class-9-ai-course-ended-2026-27', 'proposed_relates_to', 'The Class 10 course contrasts rule-based and learning-based models, covers supervised, unsupervised and reinforcement learning, classification, regression, clustering and neural networks, and judges models with train-test splits, accuracy, precision, recall and F1 score. It has no search or distributed-systems comparison. It is an optional skill subject.'),
  ('8c7bc083-021f-5891-b502-de2f708a1e09', 'IN-MANDATE-nep-2020-multidisciplinary-experiential-competency-based-learning', 'proposed_contrasts_with', 'NEP places coding activities in the Middle Stage (Classes 6 to 8), with computational thinking and puzzle games earlier. The model has Class 3 to 5 children build programs with a sequence, a loop and a condition, and fix faults. Partners should say whether programming at this age is realistic in Indian schools or belongs a stage later.'),
  ('528aba11-45e9-5ec4-b5da-4ddf071ff6a2', 'IN-MANDATE-ncf-fs-2022-foundational-stage-play-based-learning', 'proposed_relates_to', 'A Foundational competency has children sort objects into groups and sub-groups by more than one property. The model part has children sort by one property, say which property they used, and label the groups. The Indian competency goes one step further than the model; partners may want to check which is right for ages 5 to 8.')
) AS v(object_id, source_record_id, relation_type, rationale)
JOIN lpm_data_objects o ON o.id = v.object_id::uuid
JOIN curriculum_repository_records r ON r.source_repo IN ('openlpm-starter-draft', 'india-lpm') AND r.source_record_id = v.source_record_id
WHERE NOT EXISTS (SELECT 1 FROM curriculum_repository_links x WHERE x.data_object_id = o.id AND x.repository_record_id = r.id);

-- ============================================================================
-- 5. The India view for each space
-- ============================================================================

DO $MIGRATION$
DECLARE
  v_project UUID;
  v_view UUID;
  v_role TEXT;
BEGIN
  SELECT id INTO v_project FROM projects WHERE slug = 'bio-core-lpm-synth';
  IF v_project IS NOT NULL THEN
    INSERT INTO project_dashboard_views (project_id, name, kind, template_id)
    SELECT v_project, 'India (English)', 'template', 'bio-core-india-en'
    WHERE NOT EXISTS (SELECT 1 FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'bio-core-india-en');
    SELECT id INTO v_view FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'bio-core-india-en' ORDER BY created_at LIMIT 1;
    FOREACH v_role IN ARRAY ARRAY['editor', 'contributor', 'reviewer', 'viewer'] LOOP
      INSERT INTO project_dashboard_view_assignments (view_id, target_type, target_value) VALUES (v_view, 'role', v_role) ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  SELECT id INTO v_project FROM projects WHERE slug = 'social-core-lpm-synth';
  IF v_project IS NOT NULL THEN
    INSERT INTO project_dashboard_views (project_id, name, kind, template_id)
    SELECT v_project, 'India (English)', 'template', 'social-core-india-en'
    WHERE NOT EXISTS (SELECT 1 FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'social-core-india-en');
    SELECT id INTO v_view FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'social-core-india-en' ORDER BY created_at LIMIT 1;
    FOREACH v_role IN ARRAY ARRAY['editor', 'contributor', 'reviewer', 'viewer'] LOOP
      INSERT INTO project_dashboard_view_assignments (view_id, target_type, target_value) VALUES (v_view, 'role', v_role) ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  SELECT id INTO v_project FROM projects WHERE slug = 'computational-core-lpm-synth';
  IF v_project IS NOT NULL THEN
    INSERT INTO project_dashboard_views (project_id, name, kind, template_id)
    SELECT v_project, 'India (English)', 'template', 'computational-core-india-en'
    WHERE NOT EXISTS (SELECT 1 FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'computational-core-india-en');
    SELECT id INTO v_view FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'computational-core-india-en' ORDER BY created_at LIMIT 1;
    FOREACH v_role IN ARRAY ARRAY['editor', 'contributor', 'reviewer', 'viewer'] LOOP
      INSERT INTO project_dashboard_view_assignments (view_id, target_type, target_value) VALUES (v_view, 'role', v_role) ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  SELECT id INTO v_project FROM projects WHERE slug = 'interdisciplinary-lpm-synth';
  IF v_project IS NOT NULL THEN
    INSERT INTO project_dashboard_views (project_id, name, kind, template_id)
    SELECT v_project, 'India (English)', 'template', 'interdisciplinary-india-en'
    WHERE NOT EXISTS (SELECT 1 FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'interdisciplinary-india-en');
    SELECT id INTO v_view FROM project_dashboard_views WHERE project_id = v_project AND template_id = 'interdisciplinary-india-en' ORDER BY created_at LIMIT 1;
    FOREACH v_role IN ARRAY ARRAY['editor', 'contributor', 'reviewer', 'viewer'] LOOP
      INSERT INTO project_dashboard_view_assignments (view_id, target_type, target_value) VALUES (v_view, 'role', v_role) ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
END
$MIGRATION$;
